        ["4 KB 頁的 TLB 覆蓋範圍只有幾 MB，資料集一大就每次存取都要走一次分頁表——那個成本不會出現在任何一張「記憶體使用量」的圖上，只表現為「頻寬夠、延遲卻高」。量法是同一份亂序指標鏈、同樣 256 MB 工作集各跑一次，唯一的差別是頁面大小。"] = "The TLB coverage of 4 KB pages is only a few MB; with bigger datasets every access walks the page table — a cost that never shows on any memory-usage chart, only as bandwidth that is fine while latency is high. The measurement runs the same pointer-chase chain over the same 256 MB working set twice; page size is the only difference.",
