        ["HDR 顯示能力"] = "HDR display capability",
        ["IA32_ARCH_CAPABILITIES（0x10A）＝晶片自己宣告的免疫位元；IA32_SPEC_CTRL（0x48）＝作業系統目前實際啟用的緩解。兩者並列即為誠實呈現——全部量到，不需要會過期的漏洞資料庫；不宣稱「你受某 CVE 影響」。"] = "IA32_ARCH_CAPABILITIES (0x10A) is the silicon's own immunity bits; IA32_SPEC_CTRL (0x48) is what the OS actually enables today. Presenting both is the honest picture — all measured, no aging vulnerability database needed; no claim of \"you are affected by CVE X\".",
        ["IA32_PACKAGE_THERM_STATUS（0x1B1）的 log 位元是「發生過就保持為 1」的紀錄：使用者說會頓但開監控時又不頓，這裡能回答自開機以來到底有沒有撞過溫度牆／功耗牆。唯讀，本程式不清除位元。"] = "The log bits of IA32_PACKAGE_THERM_STATUS (0x1B1) stay 1 once set: when the user says it stutters but monitoring shows nothing, this answers whether the temperature/power wall has been hit since boot. Read-only; this program never clears bits.",
