        ["LibreHardwareMonitor（就是現行感測器引擎）、RAMSPDToolkit（自製 SMBus SPD 直讀）、Joular Core（RAPL 功耗直讀）、pciex（PCIe 鏈路與資源）、sc-membench（記憶體頻寬與延遲）、pmu-utils／PCM 的核心 PMU（MSR 直讀與 PMC 編程）。"] = "LibreHardwareMonitor (the current sensor engine), RAMSPDToolkit (in-house SMBus SPD direct read), Joular Core (RAPL power direct read), pciex (PCIe links & resources), sc-membench (memory bandwidth & latency), pmu-utils / PCM for the core PMU (MSR direct read & PMC programming).",
        ["M.2 / U.2 插槽偵測"] = "M.2 / U.2 slot detection",
