        ["NVIDIA 顯示卡（Titan 黑底銀邊 ・ Titan V / CEO 銀底金邊 ・ Tesla 綠）"] = "NVIDIA cards (Titan black with silver trim · Titan V / CEO silver with gold trim · Tesla green)",
        ["NVML 硬核資訊"] = "NVML deep info",
        ["NVMe 直讀健康紀錄（log page 0x02）；SATA 走 SMART_RCV_DRIVE_DATA（磁碟類別驅動代理）。屬性的原始值照韌體回報原樣列出（十六進位＋小端整數），不套任何廠商換算公式——換算就是猜。刻意不用會卡死 IRP 的原始 ATA_PASS-THROUGH；匯流排預檢不通過（USB 橋接等）時如實顯示不支援。"] = "NVMe direct health log (log page 0x02); SATA via SMART_RCV_DRIVE_DATA (storage class driver proxy). Attribute raw values are listed as the firmware reports them (hex + little-endian integer) with no vendor scaling formulas — scaling is guessing. Deliberately avoids raw ATA_PASS-THROUGH, which can hang IRPs; when the bus pre-check fails (USB bridges etc.) it shows unsupported honestly.",
        ["Native WiFi API 直讀 RSSI／速率／認證類型。RSSI 解讀：-30 極佳・-55 良好・-67 可用・-75 偏弱。"] = "Native WiFi API direct read of RSSI / rate / auth type. RSSI reading: -30 excellent · -55 good · -67 usable · -75 weak.",
        ["OpenAI 相容 API（自填端點與金鑰）"] = "OpenAI-compatible API (bring your own endpoint & key)",
        ["PCH 通道"] = "PCH channel",
        ["PCIe 世代參考"] = "PCIe generation reference",
        ["PCIe 分析"] = "PCIe analysis",
        ["PCIe 實際流量"] = "PCIe actual throughput",
        ["PCIe 裝置"] = "PCIe devices",
        ["PCIe 鏈路實況"] = "PCIe link live status",
        ["PMU 編程驗證（多輪測試・不保證可用）"] = "PMU programming verification (multi-round · not guaranteed)",
        ["Paged / Nonpaged Pool 與各優先級 Standby，純 NtQuerySystemInformation 直讀。"] = "Paged / Nonpaged Pool and Standby lists by priority, straight from NtQuerySystemInformation.",
        ["Perfetto（C++／Web 大型專案，與單一執行檔的散佈方式衝突）、Heimdall（多機 gRPC 監控，定位不同）、Silicon Monitor（Rust 無法嵌入）、OSACA（Python 組語靜態分析，受眾極窄）。"] = "Perfetto (C++/Web large projects; conflicts with single-file distribution), Heimdall (multi-machine gRPC monitoring; different purpose), Silicon Monitor (Rust; cannot embed), OSACA (Python assembly static analysis; very narrow audience).",
        ["ReBAR 要 BIOS 開啟、驅動支援、CSM 關掉、以純 UEFI 開機，四個條件缺一個就不會生效——而 Windows 沒有任何地方告訴你現況，驅動說「支援」也不等於現在真的生效。這裡問的是「這張卡實際被指派了多大的記憶體視窗」：還停在傳統的 256 MB 就是沒生效。不需要驅動也不需要管理員權限。"] = "ReBAR needs BIOS enabled, driver support, CSM off and a pure UEFI boot — miss any one and it does not take effect, and Windows nowhere tells you the current state; a driver saying \"supported\" does not mean it is active. This asks how large a memory window the card was actually assigned: still at the legacy 256 MB means not active. No driver or admin rights needed.",
        ["S.M.A.R.T. 原始資料"] = "S.M.A.R.T. raw data",
        ["SATA / eSATA 分析"] = "SATA / eSATA analysis",
        ["SATA 世代"] = "SATA generation",
        ["SATA 分析"] = "SATA analysis",
        ["SATA 磁碟"] = "SATA disks",
        ["SATA 速度參考"] = "SATA speed reference",
        ["SFC 掃描"] = "SFC scan",
        ["SIMD 計算基準"] = "SIMD compute benchmark",
        ["SLC 快取耗盡曲線"] = "SLC cache exhaustion curve",
        ["SMBIOS 原始表"] = "SMBIOS raw tables",
        ["SMBIOS 插槽列表"] = "SMBIOS slot list",
        ["SMBIOS 記憶體裝置"] = "SMBIOS memory devices",
        ["DIMM SPD 深度資料"] = "DIMM SPD details",
        ["SuperPI 圓周率運算"] = "SuperPI pi computation",
        ["TPM 走 Win32_Tpm WMI；Secure Boot 走 registry。兩者是 Windows 11 資格判斷的硬指標。"] = "TPM via Win32_Tpm WMI; Secure Boot via registry. Both are hard indicators for Windows 11 eligibility.",
        ["UEFI 變數直讀 Secure Boot 四態與開機項目數、Hypervisor 簽章（VBS 開啟時 MSR／計時可信度會變，必須明說）、微碼修訂版。全部唯讀。"] = "UEFI variable direct read of Secure Boot's four states and boot entry count, hypervisor signature (with VBS on, MSR/timing trustworthiness changes and must be disclosed), and microcode revision. All read-only.",
        ["USB 鏈路真相"] = "USB link truth",
        ["VBS／HVCI 開啟時 Windows 本身是 Hyper-V 上的一個分割區，MSR 可能被攔截或回傳虛擬值、PMU 計數可能不被轉送、TSC 可能被偏移。本程式所有 MSR 類卡片（Top-down、頻率真相、RDT、MCA、安全位元）的可信度都取決於這張卡片，所以先把資格條件講清楚。全部唯讀。"] = "With VBS/HVCI on, Windows itself is a partition on Hyper-V: MSRs may be intercepted or virtualized, PMU counters may not be forwarded, TSC may be offset. Every MSR-backed card in this program (Top-down, frequency truth, RDT, MCA, immunity bits) depends on this card, so eligibility comes first. All read-only.",
        ["VRM 供電模組"] = "VRM power stages",
        ["VRM 溫度"] = "VRM temperature",
        ["SPI 快閃熵圖（內容組成）"] = "SPI flash entropy map (content composition)",
        ["唯讀讀回整顆快閃、逐 4 KiB 塊算 Shannon 熵，依 FREG 區域切分。高熵＝像壓縮或加密的資料、低熵＝空白或高度規律、全 F＝抹除區。只描述分布，不判斷好壞或是否原廠；PRx 讀保護攔截的範圍會被算成抹除區，報告會標明。"] = "Reads the whole flash back read-only, computes Shannon entropy per 4 KiB block and splits it by FREG region. High entropy = looks compressed or encrypted, low = blank or highly regular, all-FF = erased. Describes distribution only — never whether content is good or original; PRx read-protected ranges read back as all-FF and are counted as erased, which the report states.", 
        ["虛擬化平台（元件／服務／虛擬層）"] = "Virtualization platform (components / services / hypervisor)",
        ["Windows 從不把「Hyper-V 到底在不在跑」放在一個地方：CPUID 說的是有沒有虛擬層、選用功能說的是元件裝了沒、服務狀態說的是管理服務起了沒。這三件事可以任意組合，所以這一張卡片分開陳列——特別是「裝了但開機未載入」這種狀態，不會有 VM 能跑、也不佔資源，但服務與攻擊面是開著的。"] = "Windows never puts \"is Hyper-V actually running\" in one place: CPUID tells you whether a hypervisor is present, optional features tell you whether the components are installed, and service state tells you whether the management service started. Those three combine freely, so this card lists them separately — especially the \"installed but not loaded at boot\" state, where no VM can run and nothing is consumed, but the services and their attack surface are open.",
        ["把「Hyper-V 元件裝了沒」「管理服務在跑沒」「開機有沒有載入虛擬層」三件事分開陳列，而不是壓成一句「Hyper-V：已啟用／停用」。"] = "Lists three things separately instead of collapsing them into one \"Hyper-V: enabled/disabled\": whether the components are installed, whether the management service is running, and whether the hypervisor was loaded at boot.",
        ["這三件事在 Windows 上各自獨立，可以任意組合，其中最容易被講錯的是「裝了但開機未載入」：不會有 VM 能執行、也不佔記憶體與 CPU，但 vmms 服務、驅動與其攻擊面是開著的。反過來，虛擬層也不是只有 Hyper-V 會拉起來——VBS／記憶體完整性、WSL2、容器都會，所以「有虛擬層」不等於「Hyper-V 在使用」。這一頁把四種處境分開：全關（裸機，MSR／TSC 讀值原生）、裝了未載入、VBS 拉起、真正在跑 VM。MSR／TSC 讀值是否原生直接影響本程式所有 MSR 類卡片的可信度。"] = "These three are independent on Windows and combine freely; the one most often misstated is \"installed but not loaded at boot\": no VM can run and no memory or CPU is consumed, but the vmms service, its drivers and their attack surface are open. Conversely, Hyper-V is not the only thing that starts a hypervisor — VBS/memory integrity, WSL2 and containers all do, so \"a hypervisor is present\" does not mean \"Hyper-V is in use\". This page separates four situations: all off (bare metal, MSR/TSC reads native), installed but not loaded, pulled up by VBS, and actually running VMs. Whether MSR/TSC reads are native directly affects the credibility of every MSR-backed card in this program.",
        ["唯讀。只讀 CPUID 指令、選用功能狀態、服務狀態與 WMI 列舉，不啟停任何服務、不改 hypervisorlaunchtype、不動任何設定。要改開機設定請自行使用 bcdedit——本程式只負責把現況講清楚。"] = "Read-only. It reads the CPUID instruction, optional-feature state, service state and WMI enumeration only — it starts or stops no service, changes no hypervisorlaunchtype and touches no setting. Use bcdedit yourself if you want to change boot settings; this program's job is to state the current situation clearly.",
        ["通道配置"] = "Channel configuration",
        ["螢幕組成"] = "Monitor composition",
        ["尚未讀取。"] = "Not read yet.",
        ["識別與資產"] = "Identity and asset",
        ["已安裝角色與功能"] = "Installed roles and features",
        ["覆蓋申報"] = "Coverage disclosure",
        ["落差"] = "Gap",
        ["相符"] = "Matched",
        ["寬度受限"] = "Width limited",
        ["速度待確認"] = "Speed to verify",
        ["省電設計"] = "Power-saving by design",
        ["上游上限"] = "Upstream ceiling",
        ["未判定"] = "Not judged",
        ["落差判讀"] = "Gap analysis",
        ["把「裝置宣告的能力」和「實際跑到的鏈路」之間的差距，依成因分類：相符／寬度受限／速度待確認／上游上限／未判定。"] = "Classifies the gap between a device's declared capability and its actually negotiated link by cause: matched / width-limited / speed-to-verify / upstream ceiling / not judged.",
        ["五種分類各有不同的處置，混在一起就會誤判：①「相符」沒事了；②「寬度受限」是固定損失——寬度在開機訓練時就定了，通常是插槽走線、M.2／SATA 佔用通道或 BIOS 的分流設定造成，不會自己恢復，要查主機板手冊的通道分配表；③「上游上限」代表瓶頸在插槽或上游埠，這張卡本身沒問題，換插槽或換平台才會改善；④「速度待確認」是靜態快照分不出來的部分——PCIe 鏈路速度是動態電源管理的一部分，顯示卡與 NVMe 閒置時會降到 Gen1 省電，負載一來才升回去，要確認只能在負載中再量一次。"] = "Each of the five classes calls for a different response, and lumping them together invites a wrong conclusion: (1) Matched — nothing to do; (2) Width limited — a fixed loss, since width is fixed at boot-time link training, usually caused by slot routing, M.2/SATA lane sharing or a BIOS lane-split setting, and it never recovers on its own; check the board manual's lane allocation table; (3) Upstream ceiling — the bottleneck is the slot or upstream port, not this card, and only another slot or platform improves it; (4) Speed to verify — what a static snapshot cannot settle: PCIe link speed is part of dynamic power management, so GPUs and NVMe drives downclock to Gen1 when idle and ramp back under load, and only a measurement under load distinguishes the two.",
        ["唯讀。上游連接埠的能力是另外讀它的 Link Capabilities 得到的；本版不建整棵 PCIe 拓撲，所以「上游讀不到」會如實標成未判定，不會當成「上游沒有限制」。協商上限（Link Control 2 的 Target Link Speed）被 BIOS 或驅動壓低時會明說——那種情況再怎麼重測都不會上去，除非改設定。"] = "Read-only. The upstream port's capability comes from reading its own Link Capabilities; this version does not build the whole PCIe topology, so \"upstream unreadable\" is reported as not-judged rather than as \"upstream unlimited\". When the negotiation ceiling (Link Control 2's Target Link Speed) has been lowered by BIOS or a driver, it says so plainly — in that case no amount of re-measuring will raise the link without a setting change.",
        ["裝置宣告 {0}、目前 {1}。PCIe 的鏈路速度是動態電源管理的一部分——顯示卡與 NVMe 閒置時會降到 Gen1 省電，負載一來才升回去；靜態快照分不出「閒置降速」與「真的只跑得動這個速度」。要確認請在負載中（跑遊戲、大量讀寫）再量一次，或看本頁重新掃描後的結果。"] = "Device declares {0}, currently {1}. PCIe link speed is part of dynamic power management — GPUs and NVMe drives downclock to Gen1 when idle and ramp back under load; a static snapshot cannot tell \"idle downclock\" from \"this is all it can do\". To confirm, measure again under load (run a game, heavy I/O) or re-scan from this page.",
        ["處理器功耗"] = "CPU power",
        ["處理器電壓"] = "CPU voltage",
        ["顯示卡功耗"] = "GPU power",
        ["記憶體用量"] = "Memory used",
        ["儲存溫度"] = "Storage temperature",
        ["VRM 相位數"] = "VRM phase count",
        ["WHEA 硬體錯誤紀錄"] = "WHEA hardware error log",
        ["WMI 列舉 Thunderbolt Controller 與 USB4 Host Router。埠級速率需系統管理員，此處僅列控制器存在與韌體。"] = "Enumerates Thunderbolt Controllers and USB4 Host Routers via WMI. Per-port rates need administrator; only controller presence and firmware are listed here.",
        ["Wi-Fi 訊號"] = "Wi-Fi signal",
        ["共用核心後端（MSR 試讀）"] = "Shared kernel backend (MSR read check)",
        ["WinSAT 為 Windows 內建評分（1.0–9.9），基礎分取各子項最低值。重新評分需數分鐘；遠端桌面或無圖形環境下 D3D／遊戲項可能略過，屬正常。"] = "WinSAT is Windows' built-in score (1.0–9.9); the base score is the lowest sub-score. Re-scoring takes minutes; over remote desktop or headless sessions the D3D/game items may be skipped — that is normal.",
        ["Windows 電源計劃"] = "Windows power plans",
        ["Windows 體驗指數（WinSAT）"] = "Windows Experience Index (WinSAT)",
        ["XSAVE 狀態元件（leaf 0x0D，每次執行緒切換要搬多少位元組）"] = "XSAVE state components (leaf 0x0D — bytes moved per thread switch)",
        ["iMC 逐通道計數器與 CHA／Cbo（mesh／ring）計數器走 MMIO 映射，本程式的唯讀路徑（MSR 與 PCI 設定空間）到不了；PCIe 鏈路訓練歷史、誤碼率與電源狀態轉換次數在標準設定空間裡不存在，那需要 PHY 層的協定分析儀。這些一律明說讀不到，不給猜出來的值。"] = "iMC per-channel counters and CHA/Cbo (mesh/ring) counters are MMIO-mapped — this program's read-only paths (MSR and PCI config) cannot reach them; PCIe link training history, error rates and power-state transition counts don't exist in standard config space — that needs a PHY-layer protocol analyzer. All stated as unreachable, never guessed.",
        ["openSeaChest 是唯一有實質衝突的：它自帶核心驅動做原始 ATA passthrough，而本程式在 1.9.2 刻意改成經過磁碟類別驅動代理的路徑並加上逾時看門狗——因為實測原始 passthrough 會卡死驅動、殺掉整個行程。"] = "openSeaChest is the only real conflict: it ships its own kernel driver for raw ATA passthrough, while this program deliberately moved (in 1.9.2) to a storage-class-driver proxied path with a timeout watchdog — raw passthrough was measured to hang the driver and kill the whole process.",
        ["x1 頻寬 (MB/s)"] = "x1 bandwidth (MB/s)",
        ["y-cruncher 原始輸出（尾段，供人核對）："] = "y-cruncher raw output (tail, for manual cross-check):",
        ["y-cruncher 計算圓周率並持續自我校驗——算錯就代表 CPU／記憶體在壓力下產生了靜默運算錯誤。這是原生壓測（只量溫度／吞吐）到不了的能力。"] = "y-cruncher computes pi with continuous self-verification — a wrong result means the CPU/memory produced a silent computation error under stress. That is beyond what plain stress tests (temperature/throughput only) can reach.",
        ["•  檔案丟失"] = "•  Lost files",
        ["•  硬體損毀"] = "•  Hardware damage",
        ["•  軟體崩潰"] = "•  Software crashes",
        ["← →：移動速度　↑ ↓：背景色　空白鍵：暫停移動　R：重設統計　Esc：離開"] = "← →: speed  ↑ ↓: background  Space: pause  R: reset stats  Esc: exit",
        ["↑↓ 選擇　・　Enter 執行　・　Esc 關閉"] = "↑↓ select · Enter run · Esc close",
        ["─ 藍色中隊"] = "─ Blue Squadron",
        ["⚠ 中國大陸使用者注意：共用額度與留言建議的中轉伺服器架設在 Cloudflare 上，而 workers.dev 網域在中國大陸被 GFW（防火長城）封鎖。若未使用代理，這兩項功能將無法連線。建議改用本機 Ollama（完全離線）或自填可連線的端點。"] = "⚠ Note for users in mainland China: the shared quota and the suggested relay server run on Cloudflare, and the workers.dev domain is blocked there by the GFW. Without a proxy these two features cannot connect. Local Ollama (fully offline) or a reachable custom endpoint is recommended.",
        ["⚠ 偵測到 VRM 控制器時，變更等級會直接透過 SMBus 寫入硬體。設錯可能導致 CPU 供電不穩、當機或損壞硬體。未偵測到控制器時僅作 BIOS 設定參考，不會有任何寫入。"] = "⚠ When a VRM controller is detected, changing levels writes to hardware over SMBus. Wrong settings can cause unstable CPU power, crashes or hardware damage. Without a controller it is BIOS-setting reference only — nothing is written.",
        ["⚠ 偵測到運算錯誤"] = "⚠ Computation errors detected",
        ["⚠ 壓測會把 CPU 與記憶體長時間壓到滿載，溫度顯著升高。請先確保散熱良好；筆電與散熱不良的機器尤其留意。本程式不內含 y-cruncher 執行檔，只偵測並啟動你已安裝的版本。"] = "⚠ Stress runs push the CPU and memory to full load for a long time and temperatures rise significantly. Ensure cooling is adequate; laptops and poorly cooled machines especially. This program does not bundle y-cruncher — it only detects and launches your installed copy.",
        ["⚠ 燒機安全提醒"] = "⚠ Burn-in safety notice",
        ["⟨ 回到測速頁面"] = "⟨ Back to speed test",
        ["⟳ 全面掃描"] = "⟳ Full scan",
        ["⧉ 複製"] = "⧉ Copy",
        ["「--」代表這台機器沒有這項讀值（多為缺少驅動權限或平台未暴露該感測），不是 0。"] = "\"--\" means this machine has no reading for this item (usually a driver-privilege gap or an unexposed sensor) — it is not 0.",
        ["「PCIe 鏈路」那一頁讀設定空間，看得到所有裝置協商到的速度與寬度；但那裡看不到「真的跑了多少」。這幾個數字是 NVML 自己量的最近約 20 毫秒平均，不是推算的。"] = "The \"PCIe links\" page reads config space and shows every device's negotiated speed and width; but not how much actually flows. These numbers are NVML's own ~20 ms averages, not extrapolations.",
        ["「共用上界」是 CPUID 給的可定址邏輯處理器數（EAX 25:14＋1），硬體會向上取到 2 的冪次，只能當上界看：18 核 36 執行緒的 L3 會回「最多 64 執行緒」，那不代表有 64 個核心。「含括下層」讀 EDX 位 1；L1 之下沒有更低階快取，這一欄對它沒有意義，故留「—」。"] = "\"Shared upper bound\" is CPUID's addressable logical-processor count (EAX 25:14 + 1); hardware rounds up to a power of two, so treat it as an upper bound only: an 18C/36T L3 reports \"up to 64 threads\", which does not mean 64 cores. \"Includes lower levels\" reads EDX bit 1; nothing sits below L1, so that column is \"—\" for it.",
        ["「同時達成頻寬」量的是施壓執行緒在穩態下的合計吞吐——沒有每一輪重啟執行緒的成本，也不必等最慢那條收工，所以合理地會高於上面那張 STREAM 式階梯的峰值；兩個數字量的不是同一件事。但它一定不會超過本卡片最上方推算的理論上限，超過就是記帳錯了而不是機器變快了。"] = "\"Concurrent achieved bandwidth\" measures the stressing threads' sustained total throughput — no per-round thread restart cost, no waiting for the slowest stream — so it can legitimately exceed the STREAM-style ladder's peak above; they measure different things. It must never exceed the theoretical ceiling computed at the top of this card; if it does, the accounting is wrong, not the machine faster.",
        ["「已使用 12 GB」掩蓋一半事實——認可（Commit）才是程式真正要求過的量。認可尖峰超過實體＝系統曾經真的動用分頁檔（開機至今累積），卡頓的常見源頭。"] = "\"12 GB in use\" hides half the truth — Commit is what programs actually demanded. A commit peak above physical RAM means the system really used the page file (cumulative since boot) — a common source of stutter.",
        ["「影像資料率」＝實際像素時鐘 × 每像素位元數。每像素位元數隨色彩編碼變：RGB 與 YCbCr 4:4:4 是每像素三個取樣，4:2:2 兩個，4:2:0 一點五個。所以同一個解析度與刷新率，降色度就能省下三分之一到一半的頻寬——這正是驅動在頻寬不足時偷偷做的事。"] = "\"Pixel data rate\" = actual pixel clock × bits per pixel. Bits per pixel varies with color encoding: RGB and YCbCr 4:4:4 are three samples per pixel, 4:2:2 two, 4:2:0 one and a half. The same resolution and refresh rate can save a third to half the bandwidth by chroma subsampling — exactly what drivers quietly do when bandwidth runs short.",
        ["「明明還有很多核閒著卻很卡」有兩個成因。一半是中斷全落在同一顆核上——那在「DPC 延遲與中斷歸屬」看得到；另一半是執行緒一直被搬來搬去，每次搬動都把已經拉進 L1／L2 的資料留在原地，跨 CCX 或跨 NUMA 時連 L3 都得重新拉。後者在工作管理員裡完全看不見：使用率一樣、頻率一樣，就是慢。全程唯讀，只訂閱 ETW 事件。"] = "\"Plenty of free cores yet it stutters\" has two causes. Half is interrupts all landing on one core — see \"DPC latency & interrupt affinity\". The other half is threads being migrated constantly, each move leaving L1/L2-warm data behind; across CCX or NUMA even L3 must be re-fetched. Task Manager cannot see the latter: same utilization, same clocks, just slow. Fully read-only, ETW subscriptions only.",
        ["「開始撞牆量測」會把全部核心壓滿數十秒（依窗數與秒數而定）：機器會變燙、風扇會轉起來，這正是量測的一部分。要中止隨時按停止，負載執行緒會立刻結束。"] = "\"Start wall measurement\" loads every core for tens of seconds (depending on windows and seconds): the machine gets hot and fans spin up — that is part of the measurement. Press stop anytime; the load threads end immediately.",
        ["【未經過校驗】本探測的結果沒有對照過任何參考實作（usermode 無 clflush），非保證觸發 Rowhammer；輸出僅代表壓力下自擁有頁面的翻轉觀察，不作為記憶體可靠性的結論。"] = "【Unverified】This probe's results have not been checked against any reference implementation (usermode has no clflush) and is not guaranteed to trigger Rowhammer; output only represents observed bit flips in self-owned pages under stress, not a conclusion about memory reliability.",
        ["・ 使用中"] = "· In use",
        ["・刷新已修改頁面：把已修改頁面寫回磁碟後轉為待命，讓後續清除待命能釋放更多。一鍵深度整理＝清空工作集 → 刷新已修改 → 清除待命，依此順序取得最大實際釋放量。"] = "· Refresh modified pages: write modified pages back to disk; they then become standby, so a later standby clear can release more. One-click deep tidy = empty working sets → refresh modified → clear standby, in that order for the largest actual release.",
        ["・清空工作集：命令所有行程把工作集頁面移往待命清單。「使用中」數字會下降，但頁面多半只是轉到待命、需要時會被重新讀回，可能造成短暫卡頓；本身不等於釋放。"] = "· Empty working sets: tells all processes to move their working-set pages to the standby list. The \"in use\" number drops, but pages mostly just move to standby and get read back when needed; brief stutter possible. Not a release by itself.",
        ["・清除待命快取：把系統快取的檔案資料釋回「可用」——唯一能大量釋放 RAM 的動作。代價是這些快取本用來加速讀取，清掉後相關檔案下次需重新讀取。適合在跑大型任務前、或待命占用異常膨脹時使用。"] = "· Clear standby cache: returns file data cached by the system to \"free\" — the only action that releases large amounts of RAM. The cost: that cache existed to speed reads, and cleared files must be re-read next time. Best before large tasks or when standby grows abnormally.",
        ["一、光譜選擇性——綠色乖乖的包裝反射波長介於 520–565 nm，恰好落在印刷電路板阻焊層的吸收峰附近，形成諧振安撫效應。黃色與紅色包裝的反射波段偏離此區間，僅對人類味覺受體有效。"] = "I. Spectral selectivity — green Guai-Guai packaging reflects wavelengths between 520–565 nm, right at the absorption peak of PCB solder mask, forming a resonant soothing effect. Yellow and red packaging reflect outside this band and only affect human taste receptors.",
        ["一段心路歷程　▸"] = "A journey  ▸",
        ["一般"] = "General",
        ["一萬次在 SMT 兄弟之間跳，和一萬次跨 NUMA 跳，是完全不同的兩件事。所以這裡不給一個「每秒遷移數」了事，而是照代價分層。"] = "Ten thousand hops between SMT siblings is a completely different thing from ten thousand NUMA hops. So this does not hand you a single \"migrations per second\" — it layers them by cost.",
        ["一鍵全修（SFC→DISM→CHKDSK）"] = "One-click repair all (SFC → DISM → CHKDSK)",
        ["一鍵初始化"] = "One-click initialize",
        ["一鍵加速 Speed Optimizer"] = "One-click boost (Speed Optimizer)",
        ["一鍵套用全部"] = "Apply all at once",
        ["一鍵安裝 FurMark"] = "One-click install FurMark",
        ["一鍵把風扇曲線、Windows 電源計劃與顯示卡功耗／溫度上限調成同一個取向。缺少的能力（例如無可控風扇或非 NVIDIA 顯示卡）會自動略過並如實說明。"] = "One click aligns fan curves, the Windows power plan and GPU power/temperature limits to the same orientation. Missing capabilities (no controllable fan, non-NVIDIA card) are skipped automatically and stated honestly.",
        ["一鍵深度整理"] = "One-click deep tidy",
        ["一鍵獲取"] = "Fetch list",
        ["一鍵裝機"] = "One-click install",
        ["一鍵評價本機　▸"] = "Review this PC  ▸",
        ["一鍵重置為預設"] = "One-click reset to defaults",
        ["三、時效衰減——文獻指出乖乖場（Guai-Guai Field）強度隨賞味期限呈指數衰減。逾期後矽晶體將失去共振鎖定，系統穩定性可能出現非預期波動。"] = "III. Temporal decay — literature states Guai-Guai Field strength decays exponentially with the best-before date. Past it, the silicon loses resonant lock and system stability may fluctuate unexpectedly.",
        ["三個問題的答案：這台是不是正版、重裝之後會不會掉、能不能移到新電腦。資料取自 Windows 自己的授權服務，全程唯讀——本頁不提供啟用、變更或移除授權的功能，那是 Windows 設定裡的事。"] = "Answers three questions: is this a genuine license, will it survive a reinstall, and can it move to a new PC. Data comes from Windows' own licensing service, fully read-only — this page offers no activation, change or removal; that lives in Windows Settings.",
        ["上一頁"] = "Previous",
        ["上傳"] = "Upload",
        ["上移"] = "Move up",
        ["上行"] = "Upload",
        ["下一頁"] = "Next",
        ["下移"] = "Move down",
        ["下行"] = "Download",
        ["下載"] = "Download",
        ["不想開瀏覽器、不想註冊 GitHub 也沒關係，在這裡寫完按上傳就到我這邊了。只會送出你在下面兩個框裡打的字、你自己選擇附加的檔案與版本號——沒有硬體規格、沒有機器識別碼、沒有記錄檔，一個位元都不會夾帶。"] = "No browser, no GitHub account needed — write here and press Upload. Only the text you type in the two boxes, files you explicitly attach, and the version number are sent — no hardware specs, no machine ID, no logs, not a single extra byte.",
        ["不提供各機型的參考倍率：那類對照表無法誠實——同型號的機器換一支散熱膏、換一種電源計劃就差一成，標成「約略」也只是把猜測寫得像量測。要跟別台電腦比，請在兩台機器上各選同一個棋種與同樣的執行緒數／時間跑一次：兩邊算的是同一個數學常數，工作量嚴格相等，這個比較才成立。"] = "No per-model reference multipliers are offered: such comparison tables cannot be honest — the same model with different thermal paste or a different power plan differs by ten percent; labeling it \"approximate\" just dresses a guess up as a measurement. To compare machines, run the same chess type with the same threads/time on both: both compute the same mathematical constant with strictly equal work — only then is the comparison valid.",
        ["不是，換一張"] = "No, try another",
        ["不符處數"] = "Mismatch count",
        ["世代"] = "Generation",
        ["中國象棋"] = "Chinese Chess",
        ["中斷"] = "Interrupts",
        ["中斷落在哪顆核"] = "Which core takes the interrupts",
        ["中斷（>500 ms）"] = "Interrupts (>500 ms)",
        ["中止"] = "Abort",
        ["中止目前的請求。已經顯示出來的文字會保留，並註明是中途停止、不是完整回答。"] = "Abort the current request. Text already shown is kept, marked as stopped mid-answer — not a complete reply.",
        ["中鍵次數"] = "Middle clicks",
        ["主動診斷：警示觸發時自動請 AI 分析"] = "Proactive diagnosis: auto AI analysis on alerts",
        ["主機板分析"] = "Motherboard analysis",
        ["主機板深度規格由背景 CPU-Z 報告解析（約開機後 10 餘秒）；製造商與型號另以 WMI 補入。若部分欄位為「—」，表示該平台未提供或報告尚在讀取。"] = "Motherboard deep specs come from background CPU-Z report parsing (~10+ seconds after boot); vendor and model are also filled via WMI. A \"—\" means the platform did not provide it or the report is still loading.",
        ["主硬碟"] = "Primary drive",
        ["主要 DNS，如 1.1.1.1"] = "Primary DNS, e.g. 1.1.1.1",
        ["主記憶體"] = "Main memory",
        ["主題"] = "Theme",
        ["之後想換版本：設定 › 外觀 › 簡易模式，勾起來就是「簡略」，取消就是「詳細進階」，即時生效不必重開程式。另外，被收起來的頁面只是不列在側邊欄——隨時按 Ctrl+K 開命令面板，打名字照樣搜得到、打得開。"] = "To change later: Settings › Appearance › Simple mode — check for \"Simple\", uncheck for \"Detailed advanced\", effective immediately without restart. Collapsed pages just don't show in the sidebar — press Ctrl+K for the command palette anytime and they are still searchable and openable by name.",
        ["之後第一筆 4K 讀取"] = "First 4K read after",
        ["乖度"] = "Guai rating",
        ["事件檢視器 Microsoft-Windows-WHEA-Logger 頻道的近 30 天紀錄：CPU 內部錯誤、PCIe 可修正／不可修正錯誤、記憶體與快取階層的韌體級錯誤都在這裡。零特權、由 Windows 收集，可靠；0 筆是好事，就照實說。"] = "Last 30 days from the Microsoft-Windows-WHEA-Logger channel: CPU internal errors, PCIe corrected/uncorrected errors, firmware-level memory and cache hierarchy errors. Zero privilege, collected by Windows, reliable; 0 entries is good news, said as-is.",
        ["事實清單"] = "Fact list",
        ["二、密封完整性——拆封將破壞鋁箔膜的法拉第屏蔽結構，導致內容物的鎮靜因子（Snack Stability Factor, SSF）歸零。此為不可逆相變。"] = "II. Seal integrity — opening the package destroys the foil's Faraday shielding, zeroing the contents' Snack Stability Factor (SSF). An irreversible phase transition.",
        ["五、免責聲明——以上論述之學術地位約等同於薛丁格的貓：在您打開機殼觀測之前，乖乖同時有效且無效。本程式不對拜神結果提供任何形式之保固。"] = "V. Disclaimer — the academic standing of the above is roughly Schrödinger's cat: until you open the case and observe, the Guai-Guai is simultaneously effective and ineffective. This program provides no warranty of any kind for prayer outcomes.",
        ["五族共和・攜手共進"] = "Five families in harmony, moving forward together",
        ["五項全螢幕檢測，全部由曦覽自己實作：純原生輸入／顯示事件，不連網、不需要安裝任何外部程式。每一項都會另開一個全螢幕視窗，按 Esc 隨時離開。"] = "Five fullscreen checks, all implemented in-house: pure native input/display events, no network, no external programs. Each opens its own fullscreen window; Esc leaves anytime.",
        ["交叉對帳判決"] = "Cross-check verdict",
        ["以 .NET 內建的 CPUID 指令直接問矽晶片：快取真實幾何、指令集位元、標稱頻率與拓樸層級。超出最大葉位的葉絕不讀取（會回傳無意義值）；讀不到的項目顯示「—」。"] = "Asks the silicon directly with .NET's built-in CPUID: true cache geometry, feature bits, nominal frequency and topology levels. Leaves beyond the maximum are never read (they return garbage); unreadable items show \"—\".",
        ["以 Chudnovsky 級數搭配二分裂解計算圓周率至指定位數，為單執行緒純運算負載；「完成所需時間」即為分數（越短越好），常用於比較單核運算效能。計時僅涵蓋實際運算，不含將上億位結果轉為十進位字串的輸出步驟。5000 萬／1 億位極耗時（數分鐘至數小時）且佔用大量記憶體，請斟酌選用。"] = "Computes pi to the chosen digit count with the Chudnovsky series and binary splitting — a single-threaded pure compute load; \"time to complete\" is the score (shorter is better), commonly used to compare single-core performance. Timing covers computation only, not converting hundreds of millions of digits into a decimal string. 50M/100M digits take minutes to hours and lots of memory — choose with care.",
        ["以 perft（合法走法產生 + 走子/還原）為確定性整數負載，量測節點速率（kN/s）。每執行緒各持獨立引擎、無鎖競爭，可超額訂閱實體核心。固定局面固定深度的節點數是數學常數，因此每一輪都順便核對：算出別的數字代表這台機器算錯了，而不是它比較慢。"] = "Uses perft (legal move generation + make/unmake) as a deterministic integer load, measuring node rate (kN/s). Each thread runs its own engine with no lock contention; oversubscribing physical cores is fine. Node counts for a fixed position at fixed depth are mathematical constants, so every round also cross-checks: a different number means this machine computed wrong, not that it is slower.",
        ["以上內容由 AI 依型號推斷，非本機實測。若與實物不符，以主機板手冊為準。"] = "AI-inferred from the model number, not measured locally. If it disagrees with the physical board, the motherboard manual wins.",
        ["以上內容由 AI 依型號推斷，非本機實測。若與實物不符，以顯示卡官方規格表為準。"] = "AI-inferred from the model number, not measured locally. If it disagrees with the physical card, the GPU vendor's official spec sheet wins.",
        ["以上場景基於常見情況歸納，實際原因可能不同。進階頁面有更精準的量測與分析。"] = "Scenarios are summarized from common cases; actual causes may differ. The advanced pages have more precise measurement and analysis.",
        ["以下每一個數字都是裝置自己宣告的，不是量到的。「離開延遲」是控制器承諾的上限：閒置後的第一筆 I/O 最多會被這麼久拖住。"] = "Every number here is declared by the device, not measured. \"Exit latency\" is the controller's promised upper bound: the first I/O after idle can be held up by at most this long.",
        ["以下為各核心的電壓覆寫「設定值」與偏移量（來自 XTU 可調項），非每核心即時量測——多數平台僅能量測封裝級 Vcore（見下方波形）。整數倍頻上限一併列出。"] = "Listed below are per-core voltage override \"setpoints\" and offsets (from XTU-adjustable items), not per-core instantaneous measurements — most platforms can only measure package-level Vcore (see the waveform below). Integer multiplier limits are listed too.",
        ["以你選定的 AI 模型評價本機硬體，或就配置、升級、散熱等問題自由提問。所有硬體數據皆為真實讀值。開啟「診斷代理」後，AI 能自己查溫度、事件、磁碟健康、記憶體時序與升級建議等 33 項本機唯讀資料——其中 11 項是硬核底層事實（Top-down 管線歸因、頻率真相、平台可信度、韌體與微碼、逐核時間歸因、電源政策、記憶體認可帳本、機器檢查與 WHEA、免疫位元、RDT 監測、效能天花板），這些多半要你先在對應頁面按下量測才有值，沒量過 AI 會照實說沒有。它看得到整台機器，但不會動到任何設定。"] = "Have your chosen AI model review this machine's hardware, or ask freely about configuration, upgrades and cooling. All hardware data are real readings. With \"diagnostic agent\" on, the AI can query 33 local read-only items itself — temperatures, events, disk health, memory timings, upgrade advice and more — 11 of which are hardcore low-level facts (Top-down pipeline attribution, frequency truth, platform trustworthiness, firmware & microcode, per-core time attribution, power policy, commit ledger, machine check & WHEA, immunity bits, RDT monitoring, performance ceiling) that mostly require pressing measure on the matching page first; the AI will honestly say so if you haven't. It sees the whole machine but changes nothing.",
        ["以全部邏輯執行緒持續高強度運算，將 CPU 推至滿載，觀察長時間高負載下的溫度、頻率與是否降頻。請搭配下方「即時走勢」的溫度 / 頻率曲線一同判讀。"] = "Runs all logical threads at sustained high intensity to push the CPU to full load and observe temperature, frequency and throttling over time. Read it together with the temperature / frequency curves in \"live trends\" below.",
        ["以公認的第三方負載產生器 FurMark 2 對顯示卡施加滿載，並由 XinSpect 誠實呈現即時溫度、功耗、時脈與風扇。FurMark 為 Geeks3D 專有免費軟體，本程式不內含其執行檔，首次使用以 Windows 內建 winget 從官方來源安裝。"] = "Loads the GPU to full with the recognized third-party generator FurMark 2, while XinSpect honestly shows live temperature, power, clocks and fan. FurMark is Geeks3D's proprietary freeware; this program does not bundle it — first use installs from the official source via Windows' built-in winget.",
        ["以指標追逐法掃描 1 KB → 1 GB（半倍頻步進）的平均存取延遲；快取邊界由曲線階梯推導（量到的），與 CPUID leaf 0x04 宣稱的容量並列對照。工作集上限受可用記憶體約束（保留 1 GB）。"] = "Pointer-chase sweep from 1 KB to 1 GB (half-decade steps) for average access latency; cache boundaries are derived from the curve's steps (measured), shown side by side with what CPUID leaf 0x04 claims. The working-set cap is bounded by available memory (1 GB reserved).",
        ["以指標追逐法量測不同工作集大小的隨機存取延遲，藉延遲跳升推估各級快取與主記憶體的存取延遲（數值越低越快）。"] = "Pointer-chase latency across working-set sizes; latency jumps estimate each cache level and main memory (lower is faster).",
        ["以曲線自動調速"] = "Auto speed by curve",
        ["以瀏覽器開啟 GitHub 專案頁"] = "Open the GitHub project page in a browser",
        ["以目前可用的讀取後端重新擷取驅動相依事實；啟用深層存取後不必重啟即可翻成真值。"] = "Re-collect driver-dependent facts with the currently available backend; after enabling deep access, values flip to real without a restart.",
        ["以空白分隔多個詞彙；全部命中才會列出（例如「ssd 健康」）。名稱、說明、分類、英文別名都在搜尋範圍內。"] = "Separate terms with spaces; all must match (e.g. \"ssd health\"). Name, description, category and English aliases are all searched.",
        ["以系統瀏覽器開啟目前網址"] = "Open the current URL in the system browser",
        ["以系統管理員重新啟動"] = "Restart as administrator",
        ["任一即時值超過下列上限時，於內容區頂端顯示紅色橫幅並發出系統匣氣泡通知（回落一段幅度後自動解除）。"] = "When any live value exceeds the limits below, a red banner appears at the top of the content area and a tray bubble notification fires (auto-cleared after falling back by a margin).",
        ["估計回報率"] = "Estimated report rate",
        ["位數"] = "Digits",
        ["佔比"] = "Share",
        ["佔用"] = "Usage",
        ["作業系統"] = "Operating system",
        ["作用中電源計劃"] = "Active power plan",
        ["作用核心"] = "Active cores",
        ["你的建議"] = "Your suggestion",
        ["使用 PowerShell（取消勾選＝命令提示字元 cmd）"] = "Use PowerShell (uncheck = cmd)",
        ["使用 Vulkan（預設 OpenGL）"] = "Use Vulkan (default OpenGL)",
        ["使用中"] = "In use",
        ["使用率"] = "Utilization",
        ["使用者"] = "User",
        ["來源"] = "Source",
        ["來源："] = "Source:",
        ["例：Ollama → llama3.2 / qwen2.5 / gemma2；OpenAI 相容 → gpt-4o-mini / 相容服務之模型名。可先填端點後按「一鍵獲取」自動列出可用模型。"] = "Example: Ollama → llama3.2 / qwen2.5 / gemma2; OpenAI-compatible → gpt-4o-mini or the service's model name. Fill the endpoint first and press \"Fetch list\" to enumerate models.",
        ["供應商"] = "Vendor",
        ["供電 (W)"] = "Power (W)",
        ["供電模組"] = "Power stages",
        ["供電模組分析"] = "Power stage analysis",
        ["供電狀態"] = "Power delivery status",
        ["依「該先看」的順序排。同時出現多條時，上面那條通常是因、下面那些是果——例如撞了功耗牆才導致全核頻率壓低。"] = "Ordered by \"look at this first\". When several appear together, the top one is usually cause and the rest effects — hitting the power wall is what pushed all-core clocks down.",
        ["依「遷移率」排序而不是絕對次數：絕對次數只會把最忙的行程排在前面，那是同義反覆。切入次數少於 200 的行程不列——只切了 3 次而其中 2 次換核，算出來是 67%，但那不代表什麼。"] = "Sorted by migration rate, not absolute counts: absolute counts just put the busiest process first — a tautology. Processes with fewer than 200 context switches are excluded — 2 of 3 switches changing cores computes 67%, which means nothing.",
        ["依序執行三項 WPF 繪圖管線壓力測試（填充率、3D 幾何、文字渲染），每項 5 秒，測量平均 FPS 並計算綜合分數。注意：這是 WPF 的軟體光柵化路徑，不經 GPU——分數反映 CPU 端繪製速度，換顯示卡不會有明顯差異。測試期間介面將暫停回應。"] = "Runs three WPF rendering-pipeline stress tests (fill rate, 3D geometry, text rendering), 5 seconds each, measuring average FPS and a combined score. Note: this is WPF's software rasterization path, not the GPU — the score reflects CPU-side draw speed; a different graphics card barely changes it. The UI will freeze during the test.",
        ["保留天數"] = "Retention days",
        ["保留對話（下次啟動接續）"] = "Keep conversation (resume next launch)",
        ["信賴度"] = "Confidence",
        ["倍頻鎖定"] = "Multiplier lock",
        ["值"] = "Value",
        ["停止"] = "Stop",
        ["健康明細"] = "Health details",
        ["健康總評"] = "Health summary",
        ["健康評分："] = "Health score:",
        ["側邊欄只列一般使用者用得到的頁面"] = "Sidebar lists only pages everyday users need",
        ["側邊欄只列一般會用到的頁面：總覽、處理器、記憶體、主機板、顯示卡、儲存、網路、感測器、健康、報告…（約 20 頁）。想知道「我這台是什麼配備、健不健康」選這個。"] = "The sidebar lists everyday pages only: Overview, Processor, Memory, Motherboard, Graphics, Storage, Network, Sensors, Health, Reports… (~20 pages). For \"what is this machine and is it healthy\", pick this.",
        ["側鍵（前/後）"] = "Side buttons (forward/back)",
        ["偵測"] = "Detect",
        ["偵測 Intel／AMD／Qualcomm NPU（神經處理單元），回報裝置名稱、驅動版本與估計算力。"] = "Detects Intel/AMD/Qualcomm NPUs (neural processing units), reporting device name, driver version and estimated compute.",
        ["偵測到極短點擊間隔，可能為微動開關抖動（單擊變雙擊）。"] = "Very short click intervals detected — likely switch bounce (one click read as two).",
        ["偵測到的腳座"] = "Detected socket",
        ["偵測到的記憶體類型"] = "Detected memory type",
        ["偵測各分頁功能所需的執行階段／驅動／服務是否就緒（.NET、系統管理員、感測器核心驅動、WebView2 內建瀏覽器、winget 一鍵裝機、NVIDIA 顯示卡超頻、Intel XTU CPU 超頻）。缺少的項目會標示並附官方取得連結。全為真實偵測。"] = "Checks whether each page's required runtime/driver/service is ready (.NET, administrator, the sensor kernel driver, the WebView2 embedded browser, winget one-click install, NVIDIA GPU overclocking, Intel XTU CPU overclocking). Missing items are flagged with official download links. All real detection.",
        ["傳輸率 (GT/s)"] = "Transfer rate (GT/s)",
        ["僅列出運作中且非回送 / 通道的介面；流量為每秒累計位元組差值換算。"] = "Lists only operating, non-loopback / tunnel interfaces; traffic is computed from per-second byte deltas.",
        ["優先度"] = "Priority",
        ["儲存"] = "Storage",
        ["儲存提示詞"] = "Save prompt",
        ["儲存根"] = "Storage root",
        ["儲存目前設定"] = "Save current settings",
        ["儲存與主機板（Optane 3D XPoint ・ 各家超頻名門板）"] = "Storage & motherboards (Optane 3D XPoint · famed overclocking boards)",
        ["允許 AI 主動呼叫本機唯讀查詢工具（溫度、事件、磁碟健康、歷史統計等）"] = "Let the AI call local read-only query tools on its own (temps, events, disk health, history stats, etc.)",
        ["允許低於 20%（可能造成過熱，後果自負）"] = "Allow below 20% (may overheat; at your own risk)",
        ["允許同時執行多份曦覽"] = "Allow multiple XinSpect instances",
        ["允許曲線低於 20 %（含停轉，後果自負）"] = "Allow curve below 20% (including full stop; at your own risk)",
        ["先從 WMI 讀出主機板廠牌型號，再用你設定的 AI 查詢詳細規格（晶片組、供電、插槽、網路與音效晶片）。"] = "First reads the board's vendor and model, then asks your configured AI for detailed specs (chipset, power stages, slots, network and audio chips).",
        ["先讀出顯示卡型號與驅動版本，再用你設定的 AI 查詢詳細規格（GPU 晶片、製程、串流處理器、記憶體規格、功耗與競品對照）。"] = "First reads the GPU model and driver version, then asks your configured AI for detailed specs (GPU chip, process node, stream processors, memory specs, power and competitor comparison).",
        ["免責聲明"] = "Disclaimer",
        ["內建瀏覽器無法啟動"] = "Embedded browser failed to start",
        ["全不選"] = "Select none",
        ["全核心電壓"] = "All-core voltage",
        ["全核指派同一個 RMID（PQR_ASSOC），每秒逐核心經 QM_EVTSEL／QM_CTR 讀 L3 快取占用（即時值）與記憶體頻寬（區間差分）。占用量以 CPUID 0x0F.1 的 upscaling 換算成位元組，與 Linux resctrl 的 mon_scale 是同一個值。"] = "All cores share one RMID (PQR_ASSOC); each second every core's L3 occupancy (live) and memory bandwidth (interval delta) are read via QM_EVTSEL/QM_CTR. Occupancy converts to bytes using CPUID 0x0F.1 upscaling — the same value Linux resctrl calls mon_scale.",
        ["全系統記憶體頻寬"] = "System-wide memory bandwidth",
        ["全螢幕"] = "Fullscreen",
        ["全螢幕純色循環（黑／白／紅／綠／藍／灰），用來找亮點、暗點（壞點）、漏光與背光不均。滑鼠點擊或方向鍵換色，Esc 離開。"] = "Fullscreen solid-color cycle (black/white/red/green/blue/gray) for finding bright and dark (stuck) pixels, backlight bleed and unevenness. Click or arrow keys change color; Esc exits.",
        ["全選"] = "Select all",
        ["全部來自 MSR 直讀與實測，不解析任何第三方報告：0xCE（PLATFORM_INFO）給基頻／最低效能倍頻與倍頻是否解鎖；0x10（TSC）對 QPC 實測 TSC 頻率，除以基頻倍頻得到實際 BCLK（不假設 100 MHz）；0x1AD／0x1AE 給渦輪倍頻表；0xE7／0xE8（MPERF／APERF）差分給逐邏輯處理器的有效時脈。"] = "All read straight from MSRs and measured — no third-party report parsing: 0xCE (PLATFORM_INFO) gives base/min multipliers and lock state; 0x10 (TSC) against QPC measures the actual TSC frequency, and dividing by the base multiplier yields the real BCLK (never assuming 100 MHz); 0x1AD/0x1AE give the turbo ratio table; MPERF/APERF (0xE7/0xE8) deltas give per-logical-processor effective clocks.",
        ["全部停用曲線"] = "Disable all curves",
        ["全部勾選"] = "Check all",
        ["全部合併"] = "Merge all",
        ["全部套用"] = "Apply all",
        ["全部套用樣板"] = "Apply template to all",
        ["全部核心"] = "All cores",
        ["全部直接讀自 MSR，是「這台機器現在的設定」而不是規格書上的數字——BIOS 改過就是改過的值。每一列都附原始暫存器值與取用的位元範圍，你可以自己覆核。"] = "All read directly from MSRs — \"this machine's current settings\", not spec-sheet numbers — what BIOS changed is changed. Every row shows the raw register value and the bit ranges used, so you can verify yourself.",
        ["全部還原自動"] = "Restore all to auto",
        ["全部頁面都列出來，包含硬核唯讀量測（效能天花板、Top-down 管線歸因、頻率真相、平台可信度、記憶體真實面貌、核心到核心延遲、PCIe／USB 鏈路、NVMe 電源狀態、DPC 延遲）與超頻模組。"] = "Lists every page, including the hardcore read-only measurements (performance ceiling, Top-down pipeline attribution, frequency truth, platform trustworthiness, memory truth, core-to-core latency, PCIe/USB links, NVMe power states, DPC latency) and the overclocking modules.",
        ["兩個執行緒各自釘在指定的邏輯處理器上，對同一條快取線做原子交換，量其往返延遲（多輪取中位數，ns）。可看出 SMT 兄弟（同實體核）、同 mesh 與跨 mesh 的層次差異。量測期間參與的邏輯處理器滿載；僅支援單一處理器群組（≤64 邏輯處理器）。"] = "Two threads are pinned to the specified logical processors and atomically swap a shared cache line, measuring round-trip latency (median over rounds, ns). Reveals the hierarchy: SMT siblings (same physical core), same mesh vs across mesh. Participating logical processors are fully loaded during measurement; single processor groups only (≤64 logical processors).",
        ["兩個常見又難查的問題：半夜自己醒來，以及明明沒在用卻睡不下去。Windows 其實把答案放在 powercfg 的幾條查詢裡，只是很少有人知道。這一頁把它們一次跑完並原樣呈現——刻意不解析輸出文字，因為那些字會隨系統語言翻譯，比對關鍵字會在別的語言上靜靜失效，而「解析失敗」與「沒事」長得一模一樣。"] = "Two common, hard-to-diagnose problems: waking up by itself at night, and refusing to sleep when idle. Windows keeps the answers in a few powercfg queries few people know. This page runs them all and shows the raw output — deliberately without parsing, because those strings get translated with the system language and keyword matching would silently break on other languages, where \"parse failed\" and \"all good\" look identical.",
        ["內建工具完整保留；第三方項目仍導向官方來源，也可加入自訂 EXE 或 HTTP/HTTPS 網址。相同程式與參數或相同網址會合併為別名。自訂 EXE 會以目前帳戶權限執行，不受本程式沙箱隔離。"] = "All built-in tools are retained. Third-party entries still point to official sources; you can also add custom EXEs or HTTP/HTTPS links. The same program with the same arguments, or the same URL, is merged as an alias. Custom EXEs run with your current account permissions and are not sandboxed by XinSpect.",
        ["新增工具"] = "Add tool",
        ["新增本機 EXE 或 HTTP/HTTPS 網址"] = "Add a local EXE or HTTP/HTTPS URL",
        ["EXE 路徑或 HTTP/HTTPS 網址"] = "EXE path or HTTP/HTTPS URL",
        ["啟動參數（每行一個；僅 EXE 適用）"] = "Launch arguments (one per line; EXE only)",
        ["自訂 EXE 會以目前帳戶權限執行，XinSpect 不會沙箱化或攔截其行為。"] = "Custom EXEs run with your current account permissions. XinSpect does not sandbox or intercept them.",
        ["選擇 EXE…"] = "Choose EXE…",
        ["選擇自訂工具 EXE"] = "Choose a custom tool EXE",
        ["編輯自訂工具"] = "Edit custom tool",
        ["編輯"] = "Edit",
        ["移除此自訂工具"] = "Remove this custom tool",
        ["自訂程式確認"] = "Confirm custom program",
        ["自訂 EXE 會以目前帳戶權限執行，XinSpect 不會限制或隔離它。只啟動你信任的程式。"] = "Custom EXEs run with your current account permissions and are not restricted or isolated by XinSpect. Only launch programs you trust.",
        ["共用上界"] = "Shared upper bound",
        ["其他頁各自量一件事，這一頁把它們合起來看一次，回答「現在是什麼在拖住這台機器」。用的全是本機已經讀到的數字：沒讀到的不談，也不預估「提升幾 %」——那需要 A／B 對照，本頁沒做。"] = "Other pages each measure one thing; this one puts them together to answer \"what is holding this machine back right now\". It uses only numbers already read on this machine: unread items are not discussed, and no \"+N%\" predictions — that needs A/B comparison, which this page does not do.",
        ["分數 100 對應的參考上限（只是視覺基準，不是上不封頂的絕對極限）："] = "Reference ceiling for a score of 100 (a visual baseline, not an absolute hard limit):",
        ["分析"] = "Analyze",
        ["分類"] = "Category",
        ["分類彙總"] = "Category summary",
        ["切入次數"] = "Context switches",
        ["切換日期紀年方式"] = "Switch calendar era format",
        ["切換是否永遠置頂"] = "Toggle always-on-top",
        ["切換落在哪幾顆核"] = "Which cores the switches land on",
        ["切換迷你浮動監視器"] = "Toggle mini floating monitor",
        ["列出本機所有 TCP／UDP 連線與監聽埠，並標出占用該埠的行程。純本機讀取（Windows IP Helper API），可一鍵結束占用行程。"] = "Lists all local TCP/UDP connections and listening ports, flagging which process occupies each. Pure local reads (Windows IP Helper API); the occupying process can be killed in one click.",
        ["列出這台機器實際安裝的每一支驅動，把簽章狀態與驅動日期攤開來比。未簽章的驅動、以及顯示／網路／儲存／晶片組這些關鍵類別裡老到不合理的版本，在裝置管理員裡得一個一個點進內容才看得到。全程唯讀，不安裝也不移除任何驅動。"] = "Lists every driver actually installed, with signature status and driver date side by side. Unsigned drivers, and absurdly old versions among display/network/storage/chipset classes, normally require clicking each device's properties in Device Manager. Fully read-only — installs and removes nothing.",
        ["列舉 SATA (AHCI) 控制器與連接磁碟，分析 SATA 世代、協商速度與 NCQ 支援。全程唯讀。"] = "Enumerates SATA (AHCI) controllers and attached disks, analyzing generation, negotiated speed and NCQ support. Fully read-only.",
        ["列舉登錄 Run 機碼、啟動資料夾，以及登入／開機觸發的排程工作——工作管理員的「啟動」分頁看不到排程工作，很多常駐更新程式正是靠它起來的。停用登錄與資料夾項目＝寫入與工作管理員相同、可逆的核准旗標；停用排程工作＝走 Windows 自己的 schtasks，兩者都不刪除原始項目，隨時可還原。變更「全部使用者」或系統排程工作需系統管理員權限。"] = "Enumerates registry Run keys, startup folders, and logon/boot-triggered scheduled tasks — Task Manager's Startup tab does not show scheduled tasks, which is exactly how many background updaters start. Disabling registry/folder entries writes the same reversible approval flag as Task Manager; disabling scheduled tasks goes through Windows' own schtasks. Neither deletes the original entry; both are reversible anytime. Changing \"all users\" or system tasks needs administrator.",
        ["判定"] = "Verdict",
        ["判決"] = "Ruling",
        ["判讀"] = "How to read",
        ["刷新已修改頁面"] = "Refresh modified pages",
        ["刻意不整合的"] = "Deliberately not integrated",
        ["刻意閒置"] = "Deliberate idle",
        ["前往"] = "Go",
        ["前往 Microsoft Store 取得"] = "Get it from Microsoft Store",
        ["前往設定頁的 AI 區塊"] = "Go to the AI section in Settings",
        ["前端"] = "Front-end",
        ["剩餘壽命與溫度來自 S.M.A.R.T.，部分裝置或未提供。"] = "Remaining life and temperature come from S.M.A.R.T.; some devices do not provide them.",
        ["功耗"] = "Power",
        ["功耗 Power"] = "Power",
        ["功耗上限"] = "Power limit",
        ["功耗上限、風扇與溫度上限透過 NVML（NVIDIA 官方介面）；核心／顯示記憶體頻率偏移透過 NVAPI 私有介面（帶版本保護，若驅動不支援僅會回報「無法套用」，不會寫入異常值）。每次套用皆檢查回傳碼並如實顯示結果。"] = "Power limit, fan and temperature limit go through NVML (NVIDIA's official interface); core/memory clock offsets through NVAPI's private interface (version-guarded — an unsupported driver just reports \"cannot apply\", never writes garbage). Every apply checks return codes and reports results honestly.",
        ["功能模組"] = "Feature modules",
        ["加速比"] = "Speedup",
        ["動態檢測"] = "Motion test",
        ["動態與幀時間檢測"] = "Motion & frame-time test",
        ["動態視覺效果"] = "Dynamic visual effects",
        ["勾選推薦"] = "Check recommended",
        ["勾選清單裡全部套件（已安裝的不重複裝）——一鍵裝到滿用"] = "Check every package in the list (installed ones are skipped) — one click to a full toolkit",
        ["勾選要顯示的區塊，用 ▲ ▼ 調整上下順序。變更立即生效，並記憶為下次啟動的版面。"] = "Check the sections to show and reorder with ▲ ▼. Changes apply immediately and are remembered for next launch.",
        ["勾選軟體後一鍵批次安裝，全程由 Windows 內建的 winget 從官方來源下載；本程式不含任何安裝檔。「硬體工具」分類收錄圖吧風格的檢測工具——多數曦覽已有對應頁面，要不要重複裝由你決定。"] = "Check software for one-click batch install — everything downloads from official sources via Windows' built-in winget; this program ships no installers. The \"hardware tools\" category collects tech-tubers-style diagnostic tools — most already have XinSpect pages; whether to double-install is up to you.",
        ["北橋 / CPU 整合"] = "Northbridge / integrated in CPU",
        ["匯入 .ocp"] = "Import .ocp",
        ["匯入報告"] = "Import report",
        ["匯出 .ocp"] = "Export .ocp",
        ["匯出 CSV"] = "Export CSV",
        ["匯出 HTML 報告"] = "Export HTML report",
        ["匯出報告…"] = "Export report…",
        ["匯出硬體報告"] = "Export hardware report",
        ["匯出驗機報告"] = "Export inspection report",
        ["匯流排 Bus"] = "Bus",
        ["升級建議"] = "Upgrade advice",
        ["協商後的鏈路速率與通道數（例如 DisplayPort 的 HBR3 × 4 lane）Windows 沒有提供，要靠各家廠商的私有 API；本頁因此不印那個數字，只講「這個模式需要多少」與「色彩有沒有被壓」。"] = "The negotiated link rate and lane count (e.g. DisplayPort HBR3 × 4) are not exposed by Windows and need per-vendor private APIs; this page therefore does not print that number — only \"what this mode needs\" and \"whether color is being compressed\".",
        ["協商速度"] = "Negotiated speed",
        ["協商鏈路"] = "Negotiated link",
        ["協商頻寬"] = "Negotiated bandwidth",
        ["協定"] = "Protocol",
        ["南橋 / PCH"] = "Southbridge / PCH",
        ["占用量"] = "Occupancy",
        ["卡點清單"] = "Bottleneck list",
        ["危險區：修改 BIOS 設定／刷寫韌體"] = "Danger zone: modify BIOS settings / flash firmware",
        ["即時使用量"] = "Live usage",
        ["即時合成左／右／雙聲道測試音與 20 Hz～20 kHz 掃頻，確認接線、左右聲道是否對調與有無破音。1～5 選音、S 停止、Esc 離開。"] = "Synthesizes left/right/stereo test tones and a 20 Hz–20 kHz sweep live, to verify wiring, channel swap and distortion. 1–5 select tone, S stops, Esc exits.",
        ["即時感測資料由 LibreHardwareMonitor 提供；靜態規格取自 WMI；記憶體真實時序於背景透過 CPU-Z 讀取；「免費共用」那條 AI 額度的模型由 Cloudflare Workers AI 提供。"] = "Live sensor data by LibreHardwareMonitor; static specs from WMI; true memory timings read in the background via CPU-Z; the \"free shared\" AI quota's model is provided by Cloudflare Workers AI.",
        ["即時數據"] = "Live data",
        ["即時波形"] = "Live waveform",
        ["即時狀態"] = "Live status",
        ["即時監測（XinSpect 原生讀值）"] = "Live monitoring (XinSpect native readings)",
        ["即時走勢（近 90 秒）"] = "Live trends (last 90 s)",
        ["即時遙測"] = "Live telemetry",
        ["原因"] = "Cause",
        ["原始值"] = "Raw value",
        ["原始快照"] = "Raw snapshot",
        ["原始頻寬"] = "Raw bandwidth",
        ["參考：圖吧工具箱 WinUI3（GitHub：luolangaga/tubatools）、Windows Package Manager（winget）等。"] = "Reference: TuBa Toolbox WinUI3 (GitHub: luolangaga/tubatools), Windows Package Manager (winget), etc.",
        ["取到的 V/F 工作點"] = "Sampled V/F operating points",
        ["取樣"] = "Sample",
        ["取樣數"] = "Sample count",
        ["取消"] = "Cancel",
        ["取消後會被其他視窗蓋住，但仍留在畫面上。這兩項也能在監視器自己的標題列上就地切換。"] = "Once unchecked, other windows can cover it, but it stays on screen. Both toggles also live on the monitor's own title bar.",
        ["取消變更"] = "Revert changes",
        ["只有底板變淡，讀值文字維持不透明才讀得清楚。"] = "Only the backdrop fades; the reading text stays opaque or it becomes illegible.",
        ["只統計 ISR（中斷服務常式）真正在哪顆核上執行；DPC 可能被排到別的核，混在一起會失去意義。歸屬的粒度是驅動映像，不是裝置實例——同型號的兩張網卡是同一支 .sys。"] = "Counts only where ISRs (interrupt service routines) actually execute; DPCs may be scheduled onto other cores, and mixing them loses the point. Affinity granularity is the driver image, not the device instance — two NICs of the same model are one .sys.",
        ["只讀硬性上限"] = "Read-only hard limits",
        ["只顯示監聽埠"] = "Listening ports only",
        ["只顯示需要注意的"] = "Only items needing attention",
        ["可信度"] = "Trustworthiness",
        ["可用"] = "Available",
        ["可能原因"] = "Possible causes",
        ["可輸入埠號、行程名稱或位址"] = "Enter a port number, process name or address",
        ["可靠性歷史"] = "Reliability history",
        ["右緣固定在現在，隨心跳持續右移"] = "Right edge pinned to now, drifting right with each heartbeat",
        ["右聲道 R"] = "Right channel R",
        ["右鍵次數"] = "Right clicks",
        ["右鍵選單管理"] = "Context menu manager",
        ["各世代 DIMM 對照表"] = "DIMM generations side by side",
        ["各世代金手指缺口（key）在不同位置——插槽的凸起對不上就插不進去，這是各代不能互插的原因。金色為金手指，示意疏密不代表精確腳位。目前偵測到的世代以強調色標示。"] = "Each generation's gold-finger notch sits at a different position — the slot's key does not line up, which is why generations cannot cross-insert. Gold represents the contacts; density is illustrative, not an exact pin map. The detected generation is highlighted in the accent color.",
        ["各核心即時"] = "Per-core live",
        ["各維度算力"] = "Compute by dimension",
        ["各負載窗實測對照"] = "Measured per load window",
        ["各邏輯處理器使用率（仿工作管理員）"] = "Per-logical-processor usage (Task Manager style)",
        ["同一台機器、同一段時間內的四種負載。倍頻是 APERF／MPERF 逐核差分算出來的有效值（不是瞬時峰值、也不是報告值）；「作用中核心」是用 MPERF 只在 C0 前進這個性質量出來的，倍頻表就是按這個數字查的。"] = "Four loads on the same machine over the same period. Multipliers are APERF/MPERF per-core deltas — effective values, neither instantaneous peaks nor reported ones; \"active cores\" is measured using the property that MPERF only advances in C0 — the ratio table is indexed by that number.",
        ["同一場 Run Session 的 CPU、拓樸、記憶體、GPU 與儲存深測。原 38 項全量登記；可執行與延後項目都會攤開，不把未做過的事說成量測。"] = "CPU, topology, memory, GPU and storage deep-bench from one Run Session. The full 38-item catalog is registered; executed and deferred items are both listed — nothing unmeasured is called a measurement.",
        ["同場結果證據"] = "Same-session evidence",
        ["同場聚合"] = "Same-session aggregation",
        ["同時偵測重複檔案（較慢）"] = "Also detect duplicates (slower)",
        ["同時按住越多鍵仍全部亮起，代表防鬼鍵／NKRO 能力越好；普通薄膜鍵盤通常僅保證特定組合。"] = "The more keys held simultaneously that all stay lit, the better the anti-ghosting / NKRO; ordinary membrane keyboards usually guarantee only specific combos.",
        ["同時達成頻寬"] = "Concurrent achieved bandwidth",
        ["同時開多份"] = "Multiple instances",
        ["名稱"] = "Name",
        ["含 PL1 時間窗、各負載核心數倍頻上限等進階項目，數量較多；預設收合以保持畫面整潔，需要時再展開。"] = "Includes PL1 time windows, per-load-core multiplier limits and other advanced items — numerous; collapsed by default to keep the page tidy, expand when needed.",
        ["含括下層"] = "Includes lower levels",
        ["命令面板（Ctrl+K）：搜尋任何頁面、工具與動作"] = "Command palette (Ctrl+K): search any page, tool and action",
        ["和目前比較"] = "Compare with current",
        ["品牌機與預裝 Windows 的機器通常會把金鑰寫在主機板韌體裡，重裝時自動帶入。這一欄預設遮蔽；按下按鈕才顯示，而且只顯示在畫面上——不寫入任何檔案、不進診斷紀錄、不隨報告匯出。"] = "OEM and pre-installed Windows machines usually embed the key in motherboard firmware, auto-applied on reinstall. This field is masked by default; the button reveals it on screen only — never written to any file, never into the diagnostics log, never exported with reports.",
        ["哪些行程最會彈跳"] = "Which processes bounce the most",
        ["問題數"] = "Issues",
        ["問題類別"] = "Issue category",
        ["啟動／重啟"] = "Start / restart",
        ["啟用後由曲線每秒依溫度自動調速，切到其他分頁仍持續生效。畫布上可直接拖動控制點、空白處雙擊新增、右鍵移除。"] = "Once enabled, the curve adjusts speed by temperature every second and keeps working on other tabs. Drag control points on the canvas, double-click empty space to add, right-click to remove.",
        ["啟用看門狗（套用後 30 秒無回應即自動還原設定）"] = "Enable watchdog (auto-restore if unresponsive 30 s after apply)",
        ["啟用警示"] = "Enable alerts",
        ["喇叭檢測"] = "Speaker test",
        ["單位"] = "Unit",
        ["單執行緒"] = "Single thread",
        ["單次回覆的 max_tokens。0 表示不送這個欄位、由端點自行決定——本機 Ollama 建議留 0；計費 API 想控制花費時再設上限。設太小會讓長篇評價在中途被截斷（截斷是端點做的，畫面上就會看到話沒說完）。"] = "max_tokens per reply. 0 = don't send the field, let the endpoint decide — recommended 0 for local Ollama; set a cap for paid APIs to control spend. Too small truncates long reviews mid-sentence (the endpoint does the truncating; you will see the reply cut off).",
        ["嚇哭了"] = "Scared to tears",
        ["四、空間耦合——乖乖必須直立放置於機殼頂部，使其底面與主機板法線方向平行，方能達成最佳場耦合。置於抽屜中的乖乖因距離平方反比定律，作用強度趨近於零。"] = "IV. Spatial coupling — the Guai-Guai must stand upright on top of the case, its base parallel to the motherboard normal, for optimal field coupling. A Guai-Guai in a drawer, by the inverse-square law, has an effect approaching zero.",
        ["四條曲線分別是讀取／複製／相加／三元運算四種存取型態在 1 → N 執行緒下的達成頻寬。曲線趨平表示記憶體控制器已被吃滿，再往上加執行緒只會浪費核心。"] = "The four curves are the read/copy/scale/triad access patterns as threads go 1 → N. A flattening curve means the memory controller is saturated; more threads just waste cores.",
        ["回到網速測試頁"] = "Back to the speed test page",
        ["回報率為估計值，受系統事件合併與畫面更新率影響，僅供參考；精確測量請用專用工具。"] = "Report rate is an estimate, affected by event coalescing and refresh rate; for reference only. Use a dedicated tool for precise measurement.",
        ["回復最後穩定設定"] = "Restore last stable settings",
        ["回復預設"] = "Restore defaults",
        ["回答一個問題：這顆 CPU 為什麼跑不到它該有的頻率。先把所有硬性上限直接從 MSR 讀出來（節流溫度、PL1／PL2、倍頻表、電流與供電警報），再自己製造負載去撞，最後用限制原因暫存器指出撞到的是哪一面牆。溫度牆、功耗牆、電流牆、向量降頻——它們在閒置時完全看不見，只有壓上去才會現形。"] = "Answers one question: why this CPU does not reach the frequency it should. First all hard limits are read straight from MSRs (throttle temperature, PL1/PL2, the ratio table, current and power alerts), then load is generated to hit them, and finally the limit-reason register names which wall was hit. Temperature wall, power wall, current wall, AVX throttle — invisible at idle, revealed only under load.",
        ["回覆邊產生邊顯示；端點不支援時自動退回整段模式"] = "Replies stream in as generated; falls back to whole-reply mode if the endpoint does not support streaming",
        ["回覆長度上限"] = "Max reply length",
        ["回送舊對話則數"] = "Previous messages to send",
        ["固定局面、固定深度的 perft 節點數與 CPU 型號、時脈、執行緒數都無關，是一個唯一的整數。本測試每輪都拿它核對一次，因此除了速度，也會回報這台機器算得對不對——不穩的超頻常常先表現為極少數的靜默計算錯誤，而分支密集的整數負載出錯的方式與 Prime95 的 FFT 不同，兩者互補。"] = "A fixed position at fixed depth yields a perft node count independent of CPU model, clocks or threads — a unique integer. Every round checks against it, so besides speed it reports whether this machine computes correctly — unstable overclocks often first show as rare silent computation errors, and a branch-heavy integer load fails differently from Prime95's FFT; the two complement each other.",
        ["固定風扇轉速可壓低溫度，但風扇壽命與噪音需自行權衡；取消手動即恢復驅動自動調速。"] = "A fixed fan speed lowers temperature, trading off fan life and noise; unchecking manual restores driver auto control.",
        ["固態硬碟閒著的時候會自己降到省電狀態，被喚醒時要先花「離開延遲」爬回來——於是閒置之後的第一筆讀取特別慢。這是規格允許的行為，不是故障，但在檔案總管裡完全看不出來。這一頁把碟自己宣告的電源狀態表，和實際量到的「閒置 N 毫秒後第一筆讀取要多久」擺在一起看。全程唯讀：不改電源狀態、不設 Features。"] = "SSDs drop into power-saving states when idle and must spend \"exit latency\" climbing back out — the first read after idle is especially slow. Spec-compliant behavior, not a fault, yet invisible in File Explorer. This page puts the drive's own power-state table next to the measured \"first read after N ms of idle\". Fully read-only: never changes power states, never sets Features.",
        ["圖形"] = "Graphics",
        ["圖樣檢測"] = "Pattern test",
        ["在一段實際配置到的記憶體上寫入特定圖樣再整段回讀比對，抓永遠卡在某一態的位元、相鄰位元干擾與位址解碼錯誤。測試期間可正常操作，但整機會變慢。"] = "Writes known patterns into actually allocated memory and reads it back for comparison, catching bits stuck at one state, adjacent-bit interference and address decoding errors. The machine stays usable but slower during the test.",
        ["在瀏覽器開啟"] = "Open in browser",
        ["均衡"] = "Balanced",
        ["型式"] = "Form",
        ["型號"] = "Model",
        ["埠支援"] = "Port support",
        ["執行"] = "Run",
        ["執行 Windows 內建的系統修復命令（SFC、DISM、CHKDSK、BootRec、BCDEdit），將即時輸出記錄於下方。多數命令需要以系統管理員身分執行。"] = "Runs Windows' built-in repair commands (SFC, DISM, CHKDSK, BootRec, BCDEdit), logging live output below. Most commands need administrator.",
        ["執行壓力探測（256 MiB）"] = "Run stress probe (256 MiB)",
        ["執行緒"] = "Threads",
        ["執行緒遷移與排程落點"] = "Thread migration & scheduling placement",
        ["執行編程驗證（3 輪）"] = "Run programming verification (3 rounds)",
        ["基於驅動稽核的掃描結果，提供分類彙總、年齡分布、重複偵測、已知問題驅動與更新建議。全程唯讀。"] = "Based on the driver audit scan: category summary, age distribution, duplicate detection, known-problem drivers and update advice. Fully read-only.",
