        ["定位"] = "Locate",
        ["實測 TSC 頻率"] = "Measured TSC frequency",
        ["實測：閒置之後的第一筆讀取"] = "Measured: first read after idle",
        ["實際 BCLK"] = "Actual BCLK",
        ["實際最大值"] = "Actual maximum",
        ["實體核心"] = "Physical cores",
        ["實體模組"] = "Physical modules",
        ["實體記憶體分佈"] = "Physical memory distribution",
        ["寬度"] = "Width",
        ["封裝 Vcore 波形（即時）"] = "Package Vcore waveform (live)",
        ["封裝功耗"] = "Package power",
        ["封裝功耗 W"] = "Package power W",
        ["封裝溫度"] = "Package temperature",
        ["封裝溫度 °C"] = "Package temperature °C",
        ["專業卡與運算卡（Quadro / RTX Pro 黑底 ・ 資料中心綠 ・ Instinct 紅 ・ Radeon Pro 藍）"] = "Workstation & compute cards (Quadro / RTX Pro black · data center green · Instinct red · Radeon Pro blue)",
        ["尚未安裝 Intel XTU 引擎？請先下載並安裝"] = "Intel XTU engine not installed? Download and install it first",
        ["尚未播放　按 1～5 選擇測試音"] = "Not playing yet — press 1–5 to pick a tone",
        ["尚未比較，或兩份快照沒有差異。"] = "Not compared yet, or the two snapshots have no differences.",
        ["尚未開始"] = "Not started",
        ["尚無對話。點「一鍵評價本機」讓 AI 依真實數據評價，或於下方輸入問題。\n提示：本機 Ollama 免費且離線，資料不會離開這台電腦。"] = "No conversation yet. Press \"Review this PC\" for an AI review from real data, or type a question below.\nTip: local Ollama is free and offline — data never leaves this computer.",
        ["尚無跑分數據——請先到「綜合跑分」、「磁碟測試」等頁面執行至少一項測試，再回來查看算力圖。"] = "No scores yet — run at least one test on the \"Comprehensive\" or \"Disk test\" pages first, then come back to the compute chart.",
        ["展開／收合每核心明細（預設收合，避免畫面雜亂）"] = "Expand / collapse per-core details (collapsed by default to keep things tidy)",
        ["展開／收合進階項目（預設收合，避免畫面雜亂）"] = "Expand / collapse advanced items (collapsed by default to keep things tidy)",
        ["層級"] = "Level",
        ["屬性"] = "Properties",
        ["工作管理員與 perfmon 用的同一份計數器（NtQuerySystemInformation，零特權）。取兩次樣求差約一秒——不報自開機以來的累計平均，那會把三天前的一次編譯攤平成看不出問題的數字。"] = "The same counters Task Manager and perfmon use (NtQuerySystemInformation, zero privilege). Two samples about a second apart, differenced — not a since-boot average, which would flatten last Tuesday's compile into an unremarkable number.",
        ["工具目錄"] = "Tool catalog",
        ["自訂工具"] = "Custom tools",
        ["新增自訂工具"] = "Add custom tool",
        ["儲存工具"] = "Save tool",
        ["左聲道 L"] = "Left channel L",
        ["左鍵次數"] = "Left clicks",
        ["左／右／中／側鍵與滾輪逐一確認，畫出移動軌跡並估計回報率；連點抖動（同一下被讀成兩下）會直接標出來。Esc 離開。"] = "Verifies left/right/middle/side buttons and the wheel one by one, draws the movement trail and estimates report rate; click chatter (one press read as two) is flagged directly. Esc exits.",
        ["已分析"] = "Analyzed",
        ["已安裝網路卡（實體）"] = "Installed NICs (physical)",
        ["已指派的記憶體視窗"] = "Assigned memory window",
        ["已測試鍵數"] = "Keys tested",
        ["已知問題"] = "Known issues",
        ["已計幀數"] = "Frames counted",
        ["已記錄"] = "Recorded",
        ["已配對的藍牙裝置與電量（GATT Battery→WMI 映射）。讀不到電量時以 — 呈現，不猜。"] = "Paired Bluetooth devices and battery level (GATT Battery→WMI mapping). A missing battery level shows \"—\", never guessed.",
        ["已開啟圖片搜尋。請對照實體主機板，確認是不是這一張——是的話按「是這張」，AI 才會給出針對這張板子的詳細介紹。"] = "Image search opened. Compare with the physical board and confirm it is this one — press \"It's this one\" and the AI will describe this exact board.",
        ["已開啟圖片搜尋。請對照實體顯示卡，確認是不是這一張——是的話按「是這張」，AI 才會給出針對這張卡片的詳細介紹。"] = "Image search opened. Compare with the physical card and confirm it is this one — press \"It's this one\" and the AI will describe this exact card.",
        ["常見用途："] = "Common uses:",
        ["常駐畫面一角的精簡讀值面板（工具列「迷你」鈕或系統匣選單開啟）。拖曳後會記住位置，下次顯示回到原處；若那台螢幕已拔除，則自動貼回工作區右上角。"] = "A compact always-available reading panel in a screen corner (toolbar \"Mini\" button or tray menu). Its position is remembered after dragging; if that display is gone, it snaps back to the workspace's top-right corner.",
        ["幀時間中位"] = "Median frame time",
        ["幀時間取自合成器每幀回報的時間戳，量的是「本程式實際被畫出來的節奏」，不是顯示器的面板規格；關閉垂直同步、多螢幕不同更新率或系統忙碌都會反映在這些數字上。前 20 幀（開窗抖動）不計入。"] = "Frame times come from the compositor's per-frame timestamps — the rhythm this program is actually drawn at, not the panel's spec; vsync off, mixed refresh rates or system load all show up in these numbers. The first 20 frames (window-open jitter) are excluded.",
        ["幀間隔（越平穩越順，長條竄高就是頓的那一下）"] = "Frame intervals (steadier is smoother; a spike is exactly that one stutter)",
        ["平台可信度（讀到的數字算不算原生）"] = "Platform trustworthiness (are these readings native)",
        ["平台睡眠能力（平台自己宣告的，不是建議）"] = "Platform sleep capability (declared by the platform, not advice)",
        ["平台能力（作業系統回報）"] = "Platform capability (reported by the OS)",
        ["平台資訊"] = "Platform info",
        ["平均"] = "Average",
        ["平均 FPS"] = "Average FPS",
        ["平均間隔"] = "Average interval",
        ["檢查共用核心後端能否讀取 MSR，以及 LibreHardwareMonitor 是否已回報即時讀值。"] = "Check whether the shared kernel backend can read MSRs and whether LibreHardwareMonitor is reporting live readings.",
        ["底板不透明度"] = "Backdrop opacity",
        ["座標"] = "Coordinates",
        ["廠商"] = "Manufacturer",
        ["延遲"] = "Latency",
        ["延遲曲線回答「一次存取多久」，這裡回答「同時能搬多少」與「被搶的時候會慢多少」。讀取／複製／相加／三元運算四種型態逐級加執行緒量到飽和，再一邊用其他核心把記憶體塞滿、一邊量單一存取的延遲。通道插錯與「一跑編譯整台機器就鈍」只有這裡看得出來。"] = "The latency curve answers \"how long is one access\"; this answers \"how much can move at once\" and \"how much slower under contention\". Read/copy/scale/triad scale threads up to saturation, then other cores fill memory while single-access latency is measured. Wrong channel population and \"the whole machine dulls the moment a compile starts\" are only visible here.",
        ["建立原始快照"] = "Create raw snapshot",
        ["建立時間膠囊"] = "Create time capsule",
        ["建議"] = "Advice",
        ["建議動作"] = "Recommended action",
        ["引擎狀態"] = "Engine status",
        ["強化建議"] = "Hardening advice",
        ["強調色"] = "Accent color",
        ["待命快取（可釋放）"] = "Standby cache (releasable)",
        ["待命清單（各優先級）"] = "Standby list (by priority)",
        ["後端"] = "Backend",
        ["從 HWiNFO、AIDA64、Core Temp 等第三方工具的共享記憶體讀取感測器數值。這些工具須在背景執行並開啟共享記憶體功能。"] = "Reads sensor values from the shared memory of third-party tools like HWiNFO, AIDA64 and Core Temp. Those tools must run in the background with shared memory enabled.",
        ["循序寫入"] = "Sequential write",
        ["循序讀取"] = "Sequential read",
        ["循序讀取邏輯卷，逐 1 MB 區塊量延遲，標記慢區（>100 ms）與讀取錯誤。這是實際讀一輪的量測，和 SMART 報告值互補。"] = "Reads a logical volume sequentially, timing each 1 MB block, flagging slow zones (>100 ms) and read errors. A real full-pass measurement, complementary to SMART's reported values.",
        ["微碼"] = "Microcode",
        ["忙碌"] = "Busy",
        ["忙碌%"] = "Busy %",
        ["快取 / 記憶體延遲"] = "Cache / memory latency",
        ["快取 Cache（Uncore／Ring）"] = "Cache (Uncore / Ring)",
        ["快取幾何（leaf 0x04，實測容量＝路數×分割×行×集合）"] = "Cache geometry (leaf 0x04; measured capacity = ways × partitions × lines × sets)",
        ["快取階層"] = "Cache hierarchy",
        ["快取（環匯流排）倍頻與電壓／電壓偏移集中於此，緊接目標時脈規劃之下。倍頻為整數倍；電壓偏移範圍限 −1 V～+1 V、預設 0 V。細節見各列 ❓ 說明。"] = "Ring (cache bus) multiplier and voltage/offset live here, right below target clock planning. The multiplier is integer-stepped; the offset range is −1 V to +1 V, default 0 V. See each row's ❓ for details.",
        ["快問"] = "Quick ask",
        ["快照差異"] = "Snapshot diff",
        ["快速動作"] = "Quick actions",
        ["怎麼讀這一頁"] = "How to read this page",
        ["想看更多細節，切換到「進階模式」。"] = "Want more detail? Switch to \"Detailed advanced\".",
        ["意見反饋 ・ 聯絡我們"] = "Feedback · Contact",
        ["感測器記錄（CSV）"] = "Sensor log (CSV)",
        ["成績"] = "Score",
        ["我了解：寫壞 BIOS／ME 會讓主機板無法開機，且曦覽不會、也不能替我救回來。"] = "I understand: a bricked BIOS/ME means a motherboard that will not boot, and XinSpect cannot and will not rescue it.",
        ["我已了解風險（可能損壞資料、建議專用測試機），明確同意執行"] = "I understand the risk (data damage possible; a dedicated test machine recommended) and explicitly consent",
        ["我已了解風險（寫入固定計數器使能位、絕不碰 PMI 位元、每輪還原原值），明確同意執行"] = "I understand the risk (enables fixed-counter bits, never touches PMI bits, restores originals every round) and explicitly consent",
        ["我已了解風險，繼續"] = "I understand the risk, continue",
        ["我明白風險，繼續進入"] = "I understand the risk, enter",
        ["我知道我在做什麼（今後不再顯示）"] = "I know what I am doing (don't show again)",
        ["我要超 10GHz 讓全人類感謝我"] = "I will hit 10 GHz and humanity will thank me",
        ["所有功能一鍵初始化"] = "One-click initialize everything",
        ["所有感測器"] = "All sensors",
        ["所有量測的精度來源：QPC 走 TSC 還是被 useplatformclock 降級到 HPET、系統計時器解析度被誰拉高、Invariant TSC 支援與否。誠實的工具必須先交代地基。"] = "The foundation of every measurement: whether QPC rides TSC or was demoted to HPET by useplatformclock, who raised the system timer resolution, and whether Invariant TSC is supported. An honest tool discloses its foundation first.",
        ["手動指定…"] = "Specify manually…",
        ["手動指定路徑"] = "Specify path manually",
        ["手動控制風扇轉速（取消勾選＝還原自動）"] = "Manual fan speed (uncheck = restore auto)",
        ["手動目標"] = "Manual target",
        ["把八行規格複製到剪貼簿，方便貼到論壇或聊天室問人。不含電腦名稱、使用者名稱與任何序號。"] = "Copies the eight-line spec to the clipboard for forums and chats. No computer name, no user name, no serial numbers.",
        ["把整機規格、即時讀值、健康評分、跑分紀錄、升級建議與 AI 評價寫成一份報告。HTML 為單一自帶樣式的檔案（不外連字型或指令碼），在瀏覽器按「列印／另存 PDF」即得已排好版的 A4 文件；Markdown 適合貼上論壇或議題；純文字適合貼進信件或工單。"] = "Writes the full machine spec, live readings, health score, benchmark history, upgrade advice and AI review into one report. The HTML is a single self-styled file (no external fonts or scripts) — \"Print / Save as PDF\" in a browser gives a laid-out A4 document; Markdown suits forums and issues; plain text suits emails and tickets.",
        ["把本機真實硬體規格與即時感測數據交給 AI 做客觀評價。可用本機免費模型（Ollama，無須金鑰、資料不出本機）、填入任何 OpenAI 相容的 API 端點與金鑰，或用免費共用額度（模型由 Cloudflare Workers AI 提供，經作者自架中轉分享；對話、評價與主動診斷都可以用）。"] = "Hands this machine's real hardware specs and live sensor data to the AI for an objective review. Use a free local model (Ollama — no key needed, data never leaves), fill in any OpenAI-compatible endpoint and key, or use the free shared quota (model by Cloudflare Workers AI via the author's own relay; chat, reviews and proactive diagnosis all work).",
        ["把每一筆硬體事實的值、來源、可信度和量測時間一起保存；比較兩個時間點時只報實際差異，不把差異自動解讀成故障。"] = "Saves each hardware fact's value, source, trustworthiness and measurement time together; comparing two points in time reports only actual differences — a difference is never auto-interpreted as a fault.",
        ["把目前對話（含代理查詢紀錄）整段複製到剪貼簿，可直接貼給別人"] = "Copies the entire conversation (including agent queries) to the clipboard, ready to paste",
        ["把處理器、記憶體、顯示卡、儲存、NPU 的跑分數字統一正規化為 0–100 長條，一眼看出這台機器各維度的相對強弱。數字來自其他頁面已執行的測試——沒跑過的維度不會顯示。"] = "Normalizes processor, memory, graphics, storage and NPU scores into 0–100 bars for an at-a-glance strength profile. Numbers come from tests already run on other pages — dimensions never run do not show.",
        ["把韌體安全全組事實（含交叉對帳）匯出成自足 HTML 單檔；離線可開、可列印，尾端 SHA-256 可重算驗證。"] = "Exports the whole firmware-security fact set (with cross-checks) as a self-contained HTML file; opens offline, printable, with a SHA-256 at the end for re-computation.",
        ["投資有風險，超頻需謹慎，此功能面向專業玩家"] = "Investing carries risk; overclock with care. This feature targets experienced users.",
        ["拆分"] = "Split",
        ["拓撲（作業系統原生）"] = "Topology (OS native)",
        ["拓樸層級（0x1F／0x0B）"] = "Topology levels (0x1F / 0x0B)",
        ["拜"] = "Pray",
        ["拜神"] = "Shrine",
        ["持續"] = "Sustained",
        ["持續寫入選定磁碟區（每秒強制 FlushToDisk，量到的是真的落到裝置的速度），畫出速度曲線並偵測 SLC 快取耗盡後的斷崖——廠商規格表絕不會寫的數字。斷崖點由曲線推導，會受溫度與背景活動影響。測試檔結束後自動刪除。"] = "Writes continuously to the selected volume (forced flush-to-disk every second — measuring what really lands on the device), plots the speed curve and detects the cliff after SLC cache exhaustion — a number vendor spec sheets never publish. The cliff point is derived from the curve and varies with temperature and background activity. The test file deletes itself afterwards.",
        ["持續把 CPU／GPU 溫度、頻率、負載、記憶體、顯示記憶體等即時值寫入 CSV，可用 Excel／試算表事後分析。全為真實讀值。"] = "Continuously writes CPU/GPU temperature, frequency, load, memory and VRAM live values to CSV for later analysis in a spreadsheet. All real readings.",
        ["持續累積歷史資料"] = "Keep accumulating history",
        ["指令集"] = "Instruction sets",
        ["指標"] = "Metrics",
        ["指標狀態"] = "Pointer state",
        ["掃描"] = "Scan",
        ["掃描常見暫存與快取位置，勾選後刪除。僅清理公認安全可再生的位置，使用中的檔案會自動略過。"] = "Scans common temp and cache locations; delete after checking. Only widely accepted, regenerable locations are cleaned; in-use files are skipped automatically.",
        ["排程把執行緒切到哪幾顆核上。分佈嚴重不均時，看的是同一件事的另一面：某幾顆核在做全部的工作，其餘的閒著。"] = "Which cores the scheduler picks for a thread. When the distribution is badly skewed, it is the other side of the same story: a few cores doing all the work while the rest idle.",
        ["採 RAMMap 等級的系統記憶體清單操作，真正把待命快取釋回可用記憶體，而非只是移動單一行程的工作集數字。"] = "RAMMap-grade system memory list operations — actually releases standby cache back to free memory, rather than just moving one process's working-set number.",
        ["接頭類型"] = "Connector type",
        ["控制器"] = "Controller",
        ["推估更新率"] = "Estimated refresh rate",
        ["提供者"] = "Provider",
        ["插槽"] = "Slots",
        ["插槽配置"] = "Slot layout",
        ["搜尋裝置、類別、版本、提供者或 INF 檔名"] = "Search device, class, version, provider or INF filename",
        ["搜尋頁面、工具、設定與動作…"] = "Search pages, tools, settings and actions…",
        ["收起"] = "Collapse",
        ["收起來的是直讀暫存器、編程效能計數器那一類頁面（效能天花板、超頻、PCIe／USB 鏈路、NVMe 電源狀態、DPC 延遲…）。這只是不列在側邊欄——按 Ctrl+K 照樣搜得到每一頁，功能不會消失。首次啟動時問過的「簡略／詳細進階」就是這個開關。"] = "Collapsed are the direct-register, performance-counter-programming pages (performance ceiling, overclocking, PCIe/USB links, NVMe power states, DPC latency…). They are just not in the sidebar — Ctrl+K still finds and opens every page; no functionality is lost. The \"Simple / Detailed advanced\" question at first launch is this switch.",
        ["收錄 8086K・至尊・Xeon・撕裂者・Titan・工程樣品等專屬原創徽章"] = "Original badges for the 8086K, Extreme, Xeon, Threadripper, Titan, engineering samples and more",
        ["效能測試"] = "Performance tests",
        ["整數倍"] = "Integer steps",
        ["數位民俗學 ・ 矽晶體安撫技術"] = "Digital folklore · silicon soothing technology",
        ["數值"] = "Numeric",
        ["數字面板"] = "Numeric panel",
        ["數量"] = "Count",
        ["於所選磁碟建立約 512 MB 暫存檔，量測循序讀寫（MB/s）與隨機 4K 讀寫（IOPS），完成後自動刪除暫存檔。全程採未緩衝直接 I/O（繞過作業系統讀寫快取，避免讀到快取殘留而失真），隨機 4K 為佇列深度 1（QD1）——因此每一筆 I/O 的延遲都留得下來，測完會一併給出延遲的百分位與直方圖。"] = "Creates a ~512 MB temp file on the chosen disk, measuring sequential read/write (MB/s) and random 4K read/write (IOPS), deleting it afterwards. All unbuffered direct I/O (bypassing the OS cache so cached residue cannot distort results); random 4K at queue depth 1 (QD1) — so each I/O's latency is preserved, with percentiles and a histogram at the end.",
        ["施壓等級"] = "Stress level",
        ["族內位置"] = "Position in family",
        ["明確保留序號、UUID 與 ProcessorId（預設遮蔽；公開分享時不要勾）"] = "Explicitly keep serials, UUIDs and ProcessorId (masked by default; do not check for public sharing)",
        ["是這張"] = "It's this one",
        ["時脈"] = "Clocks",
        ["時長"] = "Duration",
        ["時間"] = "Time",
        ["時間膠囊"] = "Time capsule",
        ["晶片組"] = "Chipset",
        ["晶片組分析"] = "Chipset analysis",
        ["晶片組功能一覽"] = "Chipset feature overview",
        ["晶片組安全暫存器與 ACPI 錯誤表。讀得到給裁決；缺 ring0／不支援／權限不足一律誠實標示，不以舊值或 0 填補。"] = "Chipset security registers and ACPI error tables. Readable → verdict; missing ring0 / unsupported / no permission are all honestly flagged — never backfilled with old values or zeros.",
        ["晶片組識別"] = "Chipset identification",
        ["智能熱保護：溫度達上限自動停止"] = "Smart thermal protection: auto-stop at the temperature limit",
        ["暫存預算 MiB"] = "Scratch budget MiB",
        ["曦覽 XinSpect — 特殊型號徽章示意圖"] = "XinSpect — special model badge sheet",
        ["曦覽 XinSpect ・ By Xinglanclever"] = "XinSpect · by Xinglanclever",
        ["曦覽 監視器"] = "XinSpect Monitor",
        ["曦覽一路長到四十幾頁，其中不少是給懂的人看的——直讀 MSR、編程效能計數器、解 PCI 設定空間。先選一個起點就好，這個選擇之後隨時能改，而且不論選哪一個，功能都不會被停用。"] = "XinSpect has grown past forty pages, many for people who read registers — direct MSR reads, counter programming, PCI config parsing. Just pick a starting point; it can change anytime, and no choice ever disables functionality.",
        ["曦覽整合系統、處理器、記憶體、主機板、顯示卡與儲存裝置的靜態規格與即時感測資料，於單一介面呈現型號參數、占用率、頻率、記憶體時序與溫度，靈感取自常見硬體檢測工具與 AIDA64。"] = "XinSpect unifies static specs and live sensor data for the system, processor, memory, motherboard, graphics and storage in one interface — model parameters, utilization, clocks, memory timings and temperatures. Inspired by common hardware tools and AIDA64.",
        ["曦覽遇到讀不到的東西時（MSR 被拒、WMI 查詢失敗、感測器不存在、驅動沒開放）會讓那一欄顯示「—」並繼續跑，而不是整頁掛掉。但「量不到」和「程式有缺陷」在畫面上長得一模一樣——這份清單就是用來分辨兩者的：每一筆記下發生位置、例外型別與訊息，以及對你的實際後果。"] = "When XinSpect cannot read something (MSR refused, WMI query failed, sensor absent, driver closed off) it shows \"—\" in that field and keeps running instead of crashing the page. But \"cannot measure\" and \"the program is broken\" look identical on screen — this list exists to tell them apart: every entry records where it happened, the exception type and message, and what it actually means for you.",
        ["更多走勢（近 90 秒）"] = "More trends (last 90 s)",
        ["更換插槽…"] = "Change slot…",
        ["更新"] = "Update",
        ["更新建議"] = "Update advice",
        ["更新間隔"] = "Update interval",
        ["最低電壓"] = "Minimum voltage",
        ["最低頻率（滿載）"] = "Minimum frequency (full load)",
        ["最多同時按鍵"] = "Max simultaneous keys",
        ["最大"] = "Max",
        ["最大功耗"] = "Maximum power",
        ["最大功耗限制"] = "Maximum power limit",
        ["最大幀時間"] = "Max frame time",
        ["最大檔案（前 100）"] = "Largest files (top 100)",
        ["最小"] = "Min",
        ["最差"] = "Worst",
        ["最後按鍵"] = "Last key",
        ["最短點擊間隔"] = "Shortest click interval",
        ["最終頻率 = 全核心倍頻 × 外頻（BCLK）。倍頻為整數倍調整（Intel XTU 僅支援整數倍）；外頻與電壓為連續值。倍頻與外頻按「套用目標時脈」一次寫入；全核心電壓（含電壓錶與微調鈕）併在同一區，但有自己的「套用電壓」按鈕，不會被連帶寫入。"] = "Final frequency = all-core multiplier × BCLK. Multipliers adjust in integer steps (Intel XTU only supports integers); BCLK and voltage are continuous. Multiplier and BCLK are written together by \"Apply target clocks\"; all-core voltage (meter and fine-tune) shares the section but has its own \"Apply voltage\" button and is never written along.",
        ["最近有異常嗎"] = "Anything unusual lately?",
        ["最長一幀"] = "Longest frame",
        ["最高溫"] = "Peak temperature",
        ["最高溫度"] = "Highest temperature",
        ["最高溫度限制"] = "Maximum temperature limit",
        ["最高頻率"] = "Highest frequency",
        ["有效倍頻"] = "Effective multiplier",
        ["有效時脈"] = "Effective clock",
        ["有效頻率"] = "Effective frequency",
        ["朕知道了"] = "Noted.",
        ["未偵測到 winget（應用程式安裝程式）。"] = "winget (App Installer) not detected.",
        ["未偵測到獨立顯示卡感測器，或顯示卡未提供即時資料。"] = "No discrete-GPU sensor detected, or the GPU provides no live data.",
        ["未執行。勾選同意前按鈕不可用；結果必定帶「未經過校驗」標註。"] = "Not run. The button stays disabled until you consent; results always carry the \"unverified\" label.",
        ["未執行。逐輪驗證：啟用讀回一致→計數器活動→還原後讀回原值。"] = "Not run. Per-round verification: enable read-back matches → counters move → originals read back after restore.",
        ["未從系統取得可用的 EDID 色度資訊。遠端桌面、虛擬顯示器或部分螢幕可能不提供，此為正常情形。"] = "No usable chromaticity from the display's EDID. Remote desktop, virtual displays and some monitors do not provide it — that is normal.",
        ["末幀像素檢核為空白（離屏 3D 在部分驅動／遠端工作階段輸不出內容），此項分數不計入評價。"] = "The final-frame pixel check came back blank (offscreen 3D produces nothing on some drivers/remote sessions); this score is excluded.",
        ["本工具只負責產生並輸出訊號，是否真的聽見由你判斷——程式無法代替耳朵，也不會回報未曾量到的音量。環繞聲道（5.1／7.1）需要獨占輸出裝置，本工具不涉入。"] = "This tool only generates the signal; whether you actually hear it is your call — the program cannot replace ears and never reports a volume it did not measure. Surround channels (5.1/7.1) need an exclusive output device; this tool does not go there.",
        ["本模組偵測已知攻擊痕跡與平台安全設定的事實狀態。不保證偵測所有威脅。讀不到的項目標為「無法評估」而非危險。所有檢查為唯讀——不修改任何系統設定。評分公式公開透明：每一分的扣除都可在防線展開卡片中追溯到具體的檢查項目與原始值。"] = "This module detects known attack traces and the factual state of platform security settings. It does not guarantee detection of all threats. Unreadable items are labeled \"cannot assess\", never \"dangerous\". Every check is read-only — no system settings are modified. The scoring formula is public: each deducted point traces to a specific check and raw value in the defense cards.",
        ["本模組透過 Intel XTU 超頻引擎對硬體進行真實寫入。可即時生效的項目會立刻套用；需重新開機的項目（如外頻、記憶體比率）將排入下次開機。若引擎未就緒，畫面僅提供唯讀監測，不會有任何寫入。"] = "This module writes to hardware for real through Intel XTU's overclocking engine. Items that apply live take effect immediately; reboot-required items (BCLK, memory ratio) are queued for next boot. Without the engine, this page is read-only monitoring — nothing is written.",
        ["本機 Ollama（免費・離線・建議）"] = "Local Ollama (free · offline · recommended)",
        ["本機位址"] = "Local address",
        ["本機歷史"] = "Local history",
        ["本機跑分紀錄（實測對照）"] = "Local run history (measured comparison)",
        ["本機頻寬"] = "Local bandwidth",
        ["本程式已經有等價實作的"] = "XinSpect already does this equivalently",
        ["本軟體採雙授權（dual licensing），適用於所有版本（不限最新版）：兩條路二選一、功能相同：① GNU Affero General Public License, version 3 or later（AGPL-3.0-or-later）——免費，可自由下載、使用、研究、修改、散布與商業使用，但散布修改版或以網路服務提供給他人使用時，須以相同授權公開原始碼；② 商業授權（見 COMMERCIAL-LICENSE.md）——付費，供閉源整合與隨硬體出貨，不觸發原始碼公開義務。軟體按「現狀」提供，所偵測之數值僅供參考，作者不對其準確性作任何明示或默示之擔保，一切使用風險由使用者自負。"] = "This software is dual-licensed; this applies to all versions, not only the latest. The two routes are alternatives with identical functionality. (1) GNU Affero General Public License, version 3 or later (AGPL-3.0-or-later) — free: use, study, modify, distribute and use commercially, but a modified version or a network service must release its source under the same licence. (2) A commercial licence (see COMMERCIAL-LICENSE.md) — paid: for closed-source integration and hardware bundling, with no source-disclosure obligation. Provided \"as is\"; detected values are for reference; the author makes no express or implied warranty of accuracy. All usage risk is yours.",
        ["本頁全程唯讀：只讀取與彙整，不寫入任何暫存器、不改任何設定。停留期間會每兩秒重算一次（用的是感測引擎已經在跑的那份讀值，不額外增加取樣）；離開這一頁就停。"] = "This page is read-only throughout: it reads and summarizes, writing no registers and changing no settings. While open it recomputes every two seconds (from the sensor engine's existing readings — no extra sampling); leaving the page stops it.",
        ["架構效能監測單元（leaf 0x0A，決定 Top-down 卡片能不能跑）"] = "Architectural performance monitoring unit (leaf 0x0A — decides whether the Top-down card can run at all)",
        ["查看特殊型號徽章一覽　▸"] = "View special model badges  ▸",
        ["查詢"] = "Query",
        ["核心"] = "Cores",
        ["核心 Core"] = "Core",
        ["核心停放、PCIe ASPM、USB 選擇性暫停這三項會直接造成間歇卡頓或裝置掉線，而它們在 Windows 的進階電源設定裡預設是隱藏的。這裡把目前計劃的實際值攤開。"] = "Core parking, PCIe ASPM and USB selective suspend all cause intermittent stutter or device dropouts, and all three are hidden in Windows' advanced power settings by default. This lays out the current plan's actual values.",
        ["核心到核心延遲"] = "Core-to-core latency",
        ["核心時脈"] = "Core clock",
        ["核心溫度"] = "Core temperature",
        ["核心熱力圖"] = "Core heatmap",
        ["核心熱區圖"] = "Core thermal map",
        ["核心規格"] = "Core specs",
        ["核心記憶體池細目"] = "Kernel memory pool breakdown",
        ["核心頻率偏移"] = "Core clock offset",
        ["棋種"] = "Chess type",
        ["棋類跑分（原生節點吞吐・自我驗證）"] = "Chess benchmark (native node throughput · self-verifying)",
        ["極限模式"] = "Extreme mode",
        ["標稱"] = "Nominal",
        ["模型名稱"] = "Model name",
        ["機器檢查銀行（MCA）"] = "Machine-check banks (MCA)",
        ["機器與主機板"] = "Machine & motherboard",
        ["檢查步驟"] = "Check steps",
        ["檢測視窗會蓋滿整個螢幕；若使用多螢幕，它會出現在曦覽所在的那一面。"] = "The test window covers the whole screen; with multiple monitors it appears on the one XinSpect is on.",
        ["檢測驅動"] = "Detect drivers",
        ["次數"] = "Count",
        ["次要 DNS（選填）"] = "Secondary DNS (optional)",
        ["次要時序 / 晶片組"] = "Secondary timings / chipset",
        ["歡迎回報問題、提出建議或功能需求；點擊上方連結可直接前往 GitHub 提交 Issue，或來信與我聯絡。"] = "Bug reports, suggestions and feature requests welcome — the link above goes straight to GitHub Issues, or email me.",
        ["正在分析…"] = "Analyzing…",
        ["此刻"] = "Now",
        ["此為"] = "This is",
        ["此為 D3D11 VideoDevice 的能力宣告，非實測解碼速度。"] = "This is the D3D11 VideoDevice's declared capability, not a measured decode speed.",
        ["歷史記錄"] = "History",
        ["每 3 秒自動更新"] = "Auto-update every 3 s",
        ["每一列的數字是「該層在上一層範圍內的邏輯處理器數」（EBX 15:0），不是那一層有幾個實例：SMT 層是每個核心的執行緒數，核心層是每個封裝的邏輯處理器數（18 核 36 執行緒會回 36）。"] = "Each row's number is \"logical processors at this level within the level above\" (EBX 15:0), not the number of instances: the SMT row is threads per core, the core row is logical processors per package (18C/36T reports 36).",
        ["每一支驅動的中斷集中在哪裡"] = "Where each driver's interrupts concentrate",
        ["選定邏輯處理器的 LLC 未命中按每次 64 位元組換算等效量；不代表 DRAM 實際傳輸，也未隔離其他工作負載。"] = "LLC misses on the selected logical processor are converted at 64 bytes per event. These are equivalent bytes, not measured DRAM transfers; other workloads are not isolated.",
        ["每一版做了什麼，由新到舊。1.2.0 起的每一條都對得上 Git 紀錄；1.2.0 之前的四個階段在進入版本控制之前，沒有留下逐項紀錄，因此只寫到階段層級——不補一份想像出來的清單。"] = "What each version did, newest first. Every entry since 1.2.0 matches the Git log; the four phases before 1.2.0 predate version control and only left stage-level notes — no imagined itemized list was invented to fill the gap.",
        ["每周期退休插槽"] = "Retired slots per cycle",
        ["每核心即時溫度"] = "Per-core live temperature",
        ["每核心明細 ↗"] = "Per-core details ↗",
        ["每核心獨立調節 Per-Core"] = "Per-core tuning",
        ["每核心電壓（設定值）"] = "Per-core voltage (setpoints)",
        ["每格代表一顆實體核心，底色由溫度決定（冷藍 → 青綠 → 黃綠 → 琥珀 → 熱紅）；缺讀值的那幾格不會被拿掉，會如實留白。沒有逐核溫度感測器的平台不會有這張圖。"] = "Each cell is one physical core, background colored by temperature (cold blue → teal → yellow-green → amber → hot red); cells without a reading are kept and left blank rather than dropped. Platforms without per-core temperature sensors have no such map.",
        ["每格對應一個實體核心，紅＝熱、藍＝冷；缺讀值的那幾格不會被拿掉，會如實留白。"] = "Each cell is one physical core; red = hot, blue = cold. Cells without a reading are kept and left blank rather than dropped.",
        // ── 核心熱區圖（圖例、統計列、格子的提示）──
        ["冷端"] = "Cold end",
        ["熱端"] = "Hot end",
        ["無讀值"] = "No reading",
        ["最熱核心"] = "Hottest core",
        ["最冷核心"] = "Coldest core",
        ["讀值"] = "Readings",
        ["格"] = "cells",
        ["位置"] = "Position",
        ["沒有溫度讀值"] = "no temperature reading",
        ["這個位置沒有對應的逐核感測器"] = "no per-core sensor maps to this position",
        ["沒有任何逐核溫度讀值（平台沒有逐核感測器，或感測器還沒回報）"] = "No per-core temperature reading at all (this platform has no per-core sensors, or none has reported yet)",
        ["讀值格數多於拓樸實體核心數（逐核讀值可能以邏輯處理器計）"] = "More cells have readings than the topology reports physical cores (per-core readings may be counted per logical processor)",
        ["沒有可畫的核心：這個平台沒有逐核溫度感測器，或感測器還沒回報第一筆讀值。"] = "Nothing to draw: this platform has no per-core temperature sensors, or none has reported its first reading yet.",
        ["每條建議的「依據」都是本機實際讀到的數字；讀值不足以支撐的規則會整條跳過。「預期效益」寫的是同類升級的經驗範圍，不是本機實測結果。"] = "Every suggestion's \"basis\" is a number actually read on this machine; rules the readings cannot support are skipped entirely. \"Expected benefit\" is the experience range for this upgrade class, not a locally measured result.",
        ["每次請求最多回送幾則舊對話（0 表示全部）。硬體快照本身就佔掉不少上下文，整段歷史一併送出會越談越貴、也容易撞上模型上限。有省略時會在系統提示中告知模型，避免它以為看到的是完整對話。"] = "How many previous messages to send per request (0 = all). The hardware snapshot itself eats a lot of context; sending the whole history gets expensive and can hit model limits. When trimming happens, the system prompt tells the model, so it does not assume a complete conversation.",
        ["每窗計數"] = "Count per window",
        ["每顆實體核心的倍頻上限、電壓覆寫與電壓偏移合併於同一區塊；倍頻為整數倍。並非所有平台都開放單核調節，未提供的項目不顯示。細節見各列 ❓ 說明。"] = "Per-core multiplier limits, voltage overrides and offsets share one section; multipliers are integer-stepped. Not every platform exposes per-core tuning — unoffered items do not show. See each row's ❓ for details.",
        ["沒有符合的項目"] = "No matching items",
        ["活躍核心"] = "Active cores",
        ["深層核心存取"] = "Deep core access",
        ["深度審計與時間軸"] = "Deep audit & timeline",
        ["深度規格 (CPU-Z)"] = "Deep specs (CPU-Z)",
        ["深度識別（CPU-Z）"] = "Deep identification (CPU-Z)",
        ["四種主題（深色／淺色／極限版／瑞士現代主義平面設計）與十種強調色。選擇後整個介面立即換色（無須重啟），並記憶為下次啟動的外觀。"] = "Four themes (Dark, Light, Extreme Edition, and Swiss Modernist Graphic Design) and ten accent colours. Changes apply immediately and are remembered for next launch.",
        ["清理垃圾檔案"] = "Clean junk files",
        ["清理所選"] = "Clean selected",
        ["清空所有工作集"] = "Empty all working sets",
        ["清空搜尋詞"] = "Clear search text",
        ["清空歷史資料"] = "Clear history data",
        ["清空畫面紀錄"] = "Clear on-screen log",
        ["清空跑分紀錄"] = "Clear benchmark history",
        ["清除"] = "Clear",
        ["清除 DNS 快取"] = "Flush DNS cache",
        ["清除低優先待命"] = "Clear low-priority standby",
        ["清除勾選"] = "Uncheck all",
        ["清除對話"] = "Clear conversation",
        ["清除待命快取"] = "Clear standby cache",
        ["清除紀錄"] = "Clear log",
        ["清除輸出"] = "Clear output",
        ["渦輪倍頻表"] = "Turbo ratio table",
        ["測試時間"] = "Test time",
        ["測試期間即時走勢（近 90 秒）"] = "Live trends during test (last 90 s)",
        ["測試版"] = "Beta",
        ["測試版・真實寫入"] = "Beta · real writes",
        ["測試版功能"] = "Beta feature",
        ["測試範圍"] = "Test scope",
        ["測試量"] = "Test volume",
        ["測試音由本程式即時合成後送往系統預設輸出裝置（44.1 kHz／16 位元／立體聲）。左右分離用於確認接線與聲道對調；掃頻用於聽出破音、雜音與明顯的頻段缺口。"] = "Tones are synthesized live and sent to the system default output (44.1 kHz / 16-bit / stereo). Left-right separation verifies wiring and channel swap; the sweep exposes distortion, noise and obvious band gaps.",
        ["測速節點"] = "Speed test nodes",
        ["溫度 / 壽命來自感測器與 S.M.A.R.T.；磁碟空間取用量最高的磁碟區。部分裝置或未提供資料。"] = "Temperature / life come from sensors and S.M.A.R.T.; disk space from the most-used volume. Some devices do not provide the data.",
        ["溫度上限"] = "Temperature limit",
        ["溫度來源"] = "Temperature source",
        ["溫度持續高於 90°C 就要注意散熱。使用率 100% 持續很久可能就是卡頓的原因。"] = "Sustained temperatures above 90°C deserve a cooling check. Utilization pinned at 100% for long stretches may be exactly why it stutters.",
        ["溫度正常嗎"] = "Are temperatures OK?",
        ["溫度／負載警示"] = "Temperature / load alerts",
        ["溫度／頻率／負載皆為感測器實測值；取不到時顯示「—」。"] = "Temperature / frequency / load are live sensor readings; \"—\" when unavailable.",
        ["滑鼠檢測"] = "Mouse test",
        ["滾輪縮放 ・ 拖曳平移 ・ 雙擊還原 ・ 游標讀值"] = "Wheel zoom · drag pan · double-click reset · cursor readout",
        ["滾輪（上/下）"] = "Wheel (up/down)",
        ["滿分參考值"] = "Full-score reference",
        ["滿刻度"] = "Full scale",
        ["瀏覽…"] = "Browse…",
        ["為選定的網路介面卡設定 DNS 伺服器。透過 Windows 內建 netsh 真實寫入，套用後自動清除解析快取。可隨時一鍵還原為自動取得（DHCP）。變更 DNS 需系統管理員權限。"] = "Sets DNS servers for the selected adapter via Windows' built-in netsh — a real write — and flushes the resolver cache after applying. One click restores DHCP auto anytime. Changing DNS needs administrator.",
        ["烤機時間"] = "Burn-in duration",
        ["烤機（穩定度壓力測試）"] = "Burn-in (stability stress test)",
        ["熱能與電源管理能力（leaf 0x06）"] = "Thermal & power management features (leaf 0x06)",
        ["燒機工具就緒後，這裡會即時顯示顯示卡的溫度、功耗與時脈。"] = "Once the burn-in tool is ready, this shows the GPU's temperature, power and clocks live.",
        ["燒機會將顯示卡推至極限高溫與高功耗，請確保散熱與供電充足；筆電與散熱不良的機器尤須謹慎。本頁已內建智能熱保護：即時溫度達設定上限時自動停止。測試數值僅供參考，使用風險自負。"] = "Burn-in pushes the GPU to extreme temperature and power — ensure cooling and power delivery are adequate; laptops and poorly cooled machines especially. Smart thermal protection is built in: when live temperature hits the limit, the test stops automatically. Numbers are for reference; the risk is yours.",
        ["燒機設定"] = "Burn-in settings",
        ["燒香"] = "Incense",
        ["版本、組建、授權、更新與安全態勢，收攏在一頁。全程唯讀（WMI／登錄檔／韌體變數），不改動任何系統設定。"] = "Version, build, licensing, updates and security posture in one page. Fully read-only (WMI / registry / firmware variables); changes nothing.",
        ["版本更新紀錄"] = "Changelog",
        ["現值"] = "Current value",
        ["現階段到不了的量測"] = "Measurements out of reach for now",
        ["理論最大值"] = "Theoretical maximum",
        ["環境自檢"] = "Environment check",
        ["產生完整電池報告"] = "Generate full battery report",
        ["用 SIMD FMA 平行浮點運算量 CPU 吞吐量（GFLOPS），與上面 NPU 廠標 TOPS 對照——廠標是 NPU 理論值，這裡是 CPU 實測值。"] = "Measures CPU throughput with SIMD FMA floating-point (GFLOPS) against the NPU's vendor TOPS above — the vendor number is NPU theory; this is CPU reality.",
        ["留空次要即只設主要；輸入含冒號的位址會套用為 IPv6。"] = "Leave secondary empty to set primary only; an address containing a colon applies as IPv6.",
        ["本機能力矩陣"] = "Capability matrix",
        ["九條彙總事實回答「這台機器上，哪條讀取通路真的在 work」：顯示「可用」才是真的量到過；顯示三態是環境沒有這個東西或通路未就緒；顯示「無法判定」是來源鍵缺席——缺席不讀成不支援，也不讀成可用。"] = "Nine aggregated facts answer “which read paths actually work on this machine”. “Available” means it was really measured; a three-state means the environment lacks it or the path is not ready; “cannot determine” means the source key was absent — absence is not read as unsupported, nor as available.",
        ["寫入稽核（本次執行）"] = "Write audit (this run)",
        ["同意閘門回答「該不該做」，這張卡回答「點頭之後到底寫了什麼」：每一次 MSR／PCI 設定空間／I/O 埠寫入的時間、目標、呼叫者與成敗，由底層橋接自動記帳、帳本每輪收集重置。唯讀收集時如實顯示沒有寫入——「沒有」和「沒去查」不是同一句話。"] = "The consent gate answers “should we”; this card answers “what was actually written”. Every MSR / PCI config-space / I/O-port write is logged by the low-level bridge with time, target, caller and outcome; the ledger resets each collection round. Read-only runs honestly show no writes — “none” is not the same as “never checked”.",
        ["檢查更新"] = "Check for updates",
        ["檢查中…"] = "Checking…",
        ["開啟下載頁（GitHub Releases）"] = "Open the download page (GitHub Releases)",
        ["已是最新版（v"] = "Already on the latest version (v",
        ["）。"] = ").",
        ["有新版 v"] = "New version v",
        ["（目前 v"] = " (current v",
        ["）——可到下載頁取得。"] = ") — get it from the download page.",
        ["查不到（網路不通或 GitHub 限流）——程式不假裝已是最新。"] = "Could not check (offline or GitHub rate-limited) — the app will not pretend it is up to date.",
        ["查不到（GitHub 回應無法解析）——程式不假裝已是最新。"] = "Could not check (GitHub response not parseable) — the app will not pretend it is up to date.",
        ["查不到（GitHub 沒有回報版本標籤）——程式不假裝已是最新。"] = "Could not check (no tag in GitHub response) — the app will not pretend it is up to date.",
        ["留言建議"] = "Message & suggestions",
        ["登錄關鍵字"] = "Registry keyword",
        ["百分位取的是排序後真的量到過的那一筆（最近排名，不內插、不抽樣、不套分佈模型）；每一筆都含兩次計時器讀取的成本，沒有扣掉。中間的空區間留著不填——快慢兩群之間的那段空白本身就是要看的東西。"] = "Percentiles pick the actually-observed sample after sorting (nearest rank — no interpolation, no sampling, no distribution model); every sample includes the cost of two timer reads, not subtracted. Empty gaps between clusters stay empty — the gap itself is what to look at.",
        ["監測目標"] = "Monitor targets",
        ["目前"] = "Current",
        ["目前 DNS："] = "Current DNS:",
        ["目前值"] = "Current value",
        ["目前僅支援 Intel 平台（透過 Intel XTU 引擎驅動真實寫入）；AMD 平台尚未支援，於 AMD 機器上本頁僅提供唯讀監測。所有倍頻（全核／單核／負載倍頻上限）一律以整數倍調整，因為 Intel XTU 僅支援整數倍；電壓與電壓偏移則為連續值。"] = "Intel platforms only for now (real writes via the Intel XTU engine); AMD is read-only monitoring here. All multipliers (all-core / per-core / load-limit ratios) adjust in integer steps because Intel XTU only supports integers; voltages and offsets are continuous.",
        ["目前同時按住"] = "Currently held",
        ["目前未以系統管理員身分執行。多數修復命令需要提升權限才能成功。"] = "Not running as administrator. Most repair commands need elevation to succeed.",
        ["目前檔案"] = "Current file",
        ["目前沒有警示事件。"] = "No alert events.",
        ["目前沒有降級紀錄可列。"] = "No degradation records to list.",
        ["目前版本"] = "Current version",
        ["目前狀態"] = "Current status",
        ["目前的讀值還不足以支撐任何一條建議。累積一段時間的歷史記錄（設定頁可開啟）後再回來看會更準——曦覽寧可少說，也不以「一般情況」代替你這台機器的實際數字。"] = "The current readings cannot support a single suggestion yet. Accumulate some history (enable in Settings) and come back — XinSpect would rather say less than substitute \"typical\" for your machine's actual numbers.",
        ["目前認可"] = "Current commit",
        ["目前輸出"] = "Current output",
        ["目前速度"] = "Current speed",
        ["目前電壓"] = "Current voltage",
        ["目前類型規格"] = "Current type specs",
        ["目標時脈規劃"] = "Target clock planning",
        ["目標磁碟"] = "Target disk",
        ["直接問每個 USB 集線器，把「這個埠支援什麼協定」、「裝置自己宣告的能力」與「現在真的跑在什麼速度」擺在一起比。支援 10 Gb/s 的外接 SSD 只跑 480 Mb/s，在檔案總管裡看不出來——這裡還會分清是插錯埠還是線材只有 2.0。全程唯讀查詢，不重設埠、不改電源狀態。"] = "Asks every USB hub directly, putting \"what this port supports\", \"what the device declares\" and \"what speed it actually runs\" side by side. A 10 Gb/s external SSD stuck at 480 Mb/s is invisible in File Explorer — and this distinguishes a wrong port from a 2.0 cable. Fully read-only queries; no port resets, no power-state changes.",
        ["直接編程 Intel PMU 的四個通用計數器，量測「目前系統正在跑的負載」把每周期的發射插槽花在哪裡：退休／錯誤推測／前端受限／後端受限。這不是跑分——它量的是此刻的真實負載，不會自己製造負載。"] = "Programs Intel PMU's four general-purpose counters directly to measure where \"the load the system is running right now\" spends its issue slots: retired / bad speculation / front-end bound / back-end bound. This is not a benchmark — it measures the actual current load and never generates load itself.",
        ["直接解析韌體的 SMBIOS 表（位移核對 dmidecode 3.x）。沒填的欄位顯示「—」；不認得的列舉值顯示原始位元組，不硬掰。"] = "Parses the firmware's SMBIOS tables directly (offsets verified against dmidecode 3.x). Unfilled fields show \"—\"; unrecognized enum values show the raw byte, never reinterpreted.",
        ["直接讀每個裝置的 PCIe 能力結構，把「目前協商到的速度與寬度」和「裝置自己宣告的能力」擺在一起比。x16 的顯示卡實際跑在 x4、NVMe 插在只有兩條通道的 M.2 上，只有這裡看得出來。全程唯讀，不寫任何暫存器。"] = "Reads each device's PCIe capability structure directly, comparing \"negotiated speed and width\" against \"what the device declares\". An x16 card actually running x4, or an NVMe on a 2-lane M.2, is only visible here. Fully read-only; writes nothing.",
        ["直讀韌體 Type 17 結構：每條記憶體的插槽位置、標稱／設定速度、序號、型號與 Rank——這些是韌體回報的資料（位移核對 dmidecode 3.x），未填的欄位顯示「—」。"] = "Reads firmware Type 17 structures directly: each module's slot, nominal/configured speed, serial, part number and rank — firmware-reported data (offsets verified against dmidecode 3.x); unfilled fields show \"—\".",
        ["相對"] = "Relative",
