        ["磁碟空間"] = "Disk space",
        ["磁碟表面掃描"] = "Disk surface scan",
        ["移動條判讀拖影與過衝，同時實測每一幀的呈現間隔、長幀次數與中斷（TestUFO 的原生替代，不需連網）。← → 調速、↑ ↓ 換背景、空白鍵暫停、R 重設、Esc 離開。"] = "Judge ghosting and overshoot with the moving bar while measuring every frame's presentation interval, long-frame counts and interruptions (a native TestUFO alternative, no network). ← → speed, ↑ ↓ background, Space pause, R reset, Esc exit.",
        ["移動條用來以肉眼判讀拖影與過衝：邊界後方拖出灰尾＝反應速度不足，出現反相亮／暗邊＝過驅過頭。與下方靜止參考對照最準。"] = "The moving bar is for judging ghosting and overshoot by eye: a gray tail behind the edge = response too slow; inverted bright/dark edges = overdrive too aggressive. Compare against the static reference below for best accuracy.",
        ["移動畫軌跡　按各鍵測試觸發　滾輪測試上下　C：清除計數　Esc：離開"] = "Move to trace  press each key to test  wheel up/down  C: clear counts  Esc: exit",
        ["移動速度　—"] = "Speed  —",
        ["移除"] = "Remove",
        ["移除插槽"] = "Remove slot",
        ["移除這個檔案"] = "Remove this file",
        ["穩定度"] = "Stability",
        ["等級"] = "Level",
        ["简体中文"] = "Simplified Chinese",
        ["简体中文（切换后整个介面立即转换，无须重启）"] = "Simplified Chinese (switches the whole interface immediately, no restart)",
        ["管壁上的細線是最近數秒的高點——瞬間的滿載不會留在每秒取樣裡，這條線會。灰管＝拿不到那顆核心的溫度，不是它涼。"] = "The thin line on each tube is the last few seconds' peak — a momentary spike never survives per-second sampling, but it survives this line. A gray tube = no temperature for that core, not that it is cool.",
        ["管理檔案總管右鍵選單的靜態指令。隱藏＝寫入可逆的 LegacyDisable 標記，不刪除任何原始指令，隨時可還原。COM 處理常式由各軟體註冊，僅供檢視。修改登錄需系統管理員權限。"] = "Manages File Explorer's static context-menu commands. Hide = writes the reversible LegacyDisable flag; nothing is deleted and everything is restorable. COM handlers are registered by their software and shown for reference. Registry edits need administrator.",
        ["管線歸因 Top-down（PMU 實測）"] = "Pipeline attribution Top-down (PMU measured)",
        ["範圍"] = "Range",
        ["簡易模式"] = "Simple mode",
        ["簡易燒機（穩定度測試）"] = "Simple burn-in (stability test)",
        ["簡略"] = "Simple",
        ["簽章"] = "Signature",
        ["精簡模式：收起 CPU／GPU 波形，只留四行讀值"] = "Compact mode: collapse the CPU/GPU waveforms, keep four reading rows",
        ["精簡／展開（收起波形）"] = "Compact / expand (collapse waveforms)",
        ["系統提示詞（要求 AI 客觀公正；可自行修改）"] = "System prompt (asks the AI to be objective; edit freely)",
        ["系統管理中斷（SMI）由韌體處理，發生時核心離開作業系統的視野——工作管理員永遠是 0%，但音訊會爆、幀時間會有尖峰。硬體只留下次數，沒有留下每次待了多久，所以本卡片只給頻率，不換算損失時間。C-state 駐留則說明封裝與核心真的睡了多久：閒著卻沒睡，代表有東西定期把它叫起來。"] = "System management interrupts (SMI) are handled by firmware — while one runs, the core leaves the OS's view: Task Manager always shows 0%, yet audio pops and frame times spike. Hardware only keeps a count, never a duration, so this card reports frequency only and never translates it into lost time. C-state residency then says how long the package and cores actually slept: idle-but-not-sleeping means something wakes it periodically.",
        ["系統總覽"] = "System overview",
        ["系統資訊"] = "System info",
        ["機型資訊"] = "Model",
        ["瑞士現代主義平面設計"] = "Swiss Modernist Graphic Design",
        ["瑞士深色模式"] = "Swiss Dark Mode",
        ["瑞士主題的暗色版本：近黑底色、淺色文字、直角與大字排版。"]
            = "The dark Swiss variant uses a near-black surface, light text, square geometry, and larger type.",
        ["貓貓語喵（每段介面文字加上喵）"] = "Meow language (adds a meow to each interface passage)",
        ["自然人類"] = "Human contributors",
        ["隱藏外框（只留底板與讀值）"] = "Hide the outer frame (keep only the panel and readings)",
        ["微架構"] = "Microarchitecture",
        ["本機型號、系統與關鍵硬體參數的摘要；即時數據請到各自的專頁，儀表預設收起。"]
            = "A summary of this machine's model, OS and key hardware; live readings live on their own pages — the gauges start collapsed.",
        ["已運行時間"] = "Uptime",
        ["詳細資訊"] = "Details",
        ["顯示器"] = "Monitor",
        ["硬碟"] = "Disk",
        ["聲卡"] = "Sound card",
        ["開機於 {0}"] = "Booted {0}",
        ["目前使用 {0}"] = "In use {0}",
        ["未讀到（EDID 未提供或為虛擬顯示器）"] = "Not read (no EDID, or a virtual display)",
        ["未讀到（磁碟列舉沒有回報）"] = "Not read (disk enumeration reported nothing)",
        ["未讀到（作業系統沒有回報音訊裝置）"] = "Not read (the OS reported no audio device)",
        ["未讀到（沒有實體網路卡或查詢失敗）"] = "Not read (no physical NIC, or the query failed)",
        ["系統身分"] = "System identity",
        ["系統風扇控制"] = "System fan control",
        ["約 20–30 秒。程式會自己控制負載階梯（1／2／4… 顆核心滿載）讓處理器走過睿頻表，全程唯讀，不寫入任何倍頻或電壓。"] = "About 20–30 s. The program walks the load ladder itself (1/2/4… cores saturated) so the processor passes through its turbo table; fully read-only, writes no multipliers or voltages.",
        ["約 5 分鐘全核心壓力測試，記錄最高溫；若核心溫度超過 100°C 將自動暫停並回退電壓。"] = "~5 minutes of all-core stress recording peak temperature; above 100°C it auto-pauses and reverts voltage.",
        ["純色畫面用於檢查亮點／暗點（壞點）；黑色畫面用於檢查漏光與背光均勻度"] = "Solid colors check bright/dark (stuck) pixels; black checks backlight bleed and uniformity",
        ["結束"] = "End",
        ["綜合分數"] = "Combined score",
        ["綜合分數 = 單執行緒 × 2 + 多執行緒 + 記憶體頻寬 × 20。這組權重是本程式自訂的，沒有跨機器的意義，只能用於同一台機器的前後比較；測試期間請避免其他高負載程式。"] = "Combined = single-thread × 2 + multi-thread + memory bandwidth × 20. These weights are this program's own and mean nothing across machines — same-machine before/after only. Avoid other heavy loads during the test.",
        ["綜合效能測試"] = "Combined performance test",
        ["綜合測試結果"] = "Combined results",
        ["綠色乖乖效應：作用機理與操作規範"] = "The green Guai-Guai effect: mechanism and operating procedure",
        ["網路介面卡"] = "Network adapters",
        ["編碼"] = "Encoding",
        ["編輯 Windows hosts 檔（網域→IP 對應）。儲存前自動備份，可一鍵還原上一版並清除 DNS 快取。需以系統管理員身分執行方能寫入。"] = "Edits the Windows hosts file (domain→IP mapping). Auto-backup before saving, one-click restore of the previous version, DNS cache flush. Writing needs administrator.",
        ["總上行"] = "Total upload",
        ["總下行"] = "Total download",
        ["總數"] = "Total",
        ["總計 / 認可"] = "Total / Commit",
        ["總頻寬"] = "Total bandwidth",
        ["繁體中文"] = "Traditional Chinese",
        ["繼續進入，且不再顯示此風險提示"] = "Continue and don't show this warning again",
        ["缺口位置就是 Key 的定義，也決定哪張卡插得進哪個插槽。Key M（缺口在右）走 NVMe x4，是最常見的 SSD；Key B+M 兩側都有缺口，插得進 B 或 M 插槽但只走 x2。金色為金手指，示意腳位不代表精確編號。"] = "The notch position is the key definition — it decides which card fits which slot. Key M (notch right) is NVMe x4, the common SSD; Key B+M has notches on both sides and fits B or M slots at x2 only. Gold is the contacts; illustrative, not exact pin numbering.",
        ["缺口位置示意圖"] = "Notch position diagram",
        ["缺哪些資料、去哪補測："] = "What is missing and where to measure it:",
        ["耗時"] = "Elapsed",
        ["聚合只引用同一 Run Session 的證據；缺少哪個域就明示缺少，不推算總分。"] = "Aggregation only cites evidence from the same Run Session; a missing domain is declared missing — no total is extrapolated.",
        ["聯絡方式（選填，想收到回覆再填；留空就是匿名）"] = "Contact (optional — only if you want a reply; blank stays anonymous)",
        ["能力"] = "Capability",
        ["能力評估"] = "Capability assessment",
        ["能力鏈路"] = "Capability link",
        ["能力頻寬"] = "Capability bandwidth",
        ["能量計數"] = "Energy counter",
        ["腳座示意圖"] = "Socket diagram",
        ["腳座腳位"] = "Socket pins",
        ["自主降態（APST）"] = "Autonomous power state transitions (APST)",
        ["自動跟隨"] = "Auto-follow",
        ["自訂"] = "Custom",
        ["自訂 DNS（IPv4 或 IPv6）"] = "Custom DNS (IPv4 or IPv6)",
        ["自訂磁貼"] = "Custom tiles",
        ["自顯示器 EDID 解析 CIE 色度座標，計算色域三角形對 sRGB、Adobe RGB、DCI-P3 三種標準的覆蓋率，並以 2D 色度圖把色域畫出來。"] = "Parses CIE chromaticity coordinates from the display's EDID, computes the gamut triangle's coverage of sRGB, Adobe RGB and DCI-P3, and draws the gamut on a 2D chromaticity diagram.",
        ["與其餘感測共用同一套檢測引擎（LibreHardwareMonitor）。顯示卡風扇請至「顯示卡超頻」分頁調整。"] = "Shares the same detection engine as the other sensors (LibreHardwareMonitor). For GPU fans go to the \"GPU Overclocking\" tab.",
        ["與參考映像比對"] = "Compare against a reference image",
        ["與外部底層工具的對照"] = "Comparison with external low-level tools",
        ["與目前差分"] = "Diff against current",
        ["藍牙外設"] = "Bluetooth peripherals",
        ["處理器負載 %"] = "CPU load %",
        ["虛擬化（可信度聲明）"] = "Virtualization (trustworthiness statement)",
        ["虛擬鍵盤逐鍵確認觸發與鍵碼，並統計同時按下的鍵數，用來看這把鍵盤到底能不能防鬼鍵（NKRO）。Esc 離開。"] = "Confirms each key's press and code on a virtual keyboard and counts held keys, revealing whether this keyboard can actually anti-ghost (NKRO). Esc exits.",
        ["虛擬鍵碼 / 掃描碼"] = "Virtual key / scan code",
        ["螢幕檢測"] = "Display test",
        ["行大小"] = "Line size",
        ["行程"] = "Process",
        ["裝置"] = "Device",
        ["裝置管理員「進階」分頁裡那幾十項設定，一次攤開。其中 RSS（接收端調整）最值得看：它決定收包處理能不能分到多顆核心上——「中斷落在哪顆核」那張卡若點名某顆核被網卡打爆，答案常常就在這裡。屬性一律原樣呈現並附上登錄關鍵字，那是跨語言唯一穩定的識別。全程唯讀。"] = "The dozens of settings from Device Manager's Advanced tab, laid out at once. RSS (receive-side scaling) matters most: it decides whether receive processing can spread across cores — if the interrupt-affinity card names one core being hammered by a NIC, the answer is often here. Properties are shown verbatim with their registry keyword, the only stable cross-language identifier. Fully read-only.",
        ["裝置能力"] = "Device capability",
        ["製造商"] = "Manufacturer",
        ["複製整段對話"] = "Copy whole conversation",
        ["複製為 Markdown"] = "Copy as Markdown",
        ["複製登錄路徑並開啟登錄編輯程式"] = "Copy registry path and open Registry Editor",
        ["複製規格摘要"] = "Copy spec summary",
        ["複製這則訊息"] = "Copy this message",
        ["西洋棋"] = "Chess",
        ["要看到多少東西？"] = "How much do you want to see?",
        ["覆蓋率"] = "Coverage",
        ["規格"] = "Specs",
        ["解析度"] = "Resolution",
        ["解析度與刷新率開起來了，不代表畫面沒有被犧牲：頻寬不夠時驅動會自己把色度降成 YCbCr 4:2:2 或 4:2:0，或把每通道位元數壓到 8 位元——設定裡照樣寫著 4K144，只有文字邊緣與細紅字會發糊。這一頁把連接技術、實際像素時鐘、目前的色彩編碼與位元深度擺出來，並算出這個模式需要多少影像資料率。全程唯讀查詢。"] = "A resolution and refresh rate being set does not mean the picture was not sacrificed: when bandwidth runs short the driver subsamples chroma to YCbCr 4:2:2 or 4:2:0, or squeezes bits per channel to 8 — Settings still says 4K144, only text edges and fine red text go fuzzy. This page lays out connection type, actual pixel clock, current color encoding and bit depth, and computes the pixel data rate the mode needs. Fully read-only queries.",
        ["解讀"] = "Interpretation",
        ["訂閱 DXGI Present 事件（ETW），取得任何程式的每一幀時間戳——不注入目標程序、不掛勾、不碰驅動，反作弊軟體無從區別。1%／0.1% Low 採「最差 1%／0.1% 幀的平均 FPS」定義；Present 模式與 GPU 忙碌時間本版未解析，解析不了就不顯示。"] = "Subscribes to DXGI Present events (ETW) for any program's per-frame timestamps — no injection into the target process, no hooks, no driver touching; anti-cheat cannot tell. 1% / 0.1% Low use \"average FPS of the worst 1% / 0.1% of frames\"; Present mode and GPU busy time are not parsed in this version — if it cannot be parsed, it is not shown.",
        ["計時器地基"] = "Timer foundation",
        ["計算結果（前 40 位）"] = "Result (first 40 digits)",
        ["記憶體 Memory"] = "Memory",
        ["記憶體使用率 %"] = "Memory usage %",
        ["記憶體壓力探測（危險・未經校驗）"] = "Memory stress probe (dangerous · unverified)",
        ["記憶體延遲曲線"] = "Memory latency curve",
        ["記憶體插對了嗎"] = "Is memory populated correctly?",
        ["記憶體時序"] = "Memory timings",
        ["記憶體真實面貌（認可）"] = "Memory truth (commit)",
        ["記憶體負載上限"] = "Memory load limit",
        ["記憶體頻寬"] = "Memory bandwidth",
        ["記憶體頻寬與負載延遲"] = "Memory bandwidth & loaded latency",
        ["記憶體頻寬飽和曲線（執行緒 → 頻寬）"] = "Memory bandwidth saturation curve (threads → bandwidth)",
        ["記錄間隔"] = "Log interval",
        ["設定檔"] = "Profiles",
        ["診斷代理"] = "Diagnostic agent",
        ["診斷代理：允許 AI 主動查詢本機唯讀資料"] = "Diagnostic agent: let the AI query local read-only data on its own",
        ["診斷紀錄"] = "Diagnostics log",
        ["註：記憶體比率／電壓多為需重新開機生效項目。Gear 1/2 為 Comet Lake 以後平台的記憶體控制器分頻概念；此平台若無對應旋鈕則不顯示，實際等效頻率與 Gear 以 BIOS 回報為準。"] = "Note: memory ratio/voltage usually need a reboot to take effect. Gear 1/2 is the memory-controller divider concept from Comet Lake onward; if this platform has no such knob it does not show — effective frequency and Gear are as BIOS reports.",
        ["評分越高越健康 ・ 依各項指標嚴重度即時扣分計算"] = "Higher is healthier · points deducted live by each metric's severity",
        ["該升級什麼"] = "What to upgrade",
        ["該升級哪裡"] = "Where to upgrade",
        ["詳細規格（AI 查詢）"] = "Detailed specs (AI query)",
        ["詳細進階"] = "Detailed advanced",
        ["認可尖峰"] = "Commit peak",
        ["語言"] = "Language",
        ["語言 Language"] = "Language",
        ["誠實界線"] = "Honest limits",
        ["誠實界線：RMID 全核統一指派，因此得到的是「全系統＋逐核心」視角，做不到逐行程歸屬（那需要核心層的 RMID 排程）。QM_CTR 回報 Error／Unavailable 旗標時顯示「—」，絕不把錯誤碼當讀值。若整片為 0，最可能是本機 BIOS／平台未開放 RDT 監測——那就如實顯示 0。"] = "Honest limits: one RMID for all cores yields a system-wide + per-core view; per-process attribution is impossible (that needs kernel-level RMID scheduling). When QM_CTR reports Error/Unavailable flags this shows \"—\" — error codes are never presented as readings. An all-zero board most likely means this machine's BIOS/platform does not expose RDT monitoring — displayed as 0, honestly.",
        ["誠實界線：① 錯誤推測一桶不含 INT_MISC.RECOVERY_CYCLES 項（硬體只有 4 個通用計數器，五個事件放不下），故該桶略微低估、後端受限略微高估。② 逐實體核心序列取樣，各核心的取樣時間點不同，非同一瞬間的快照。③ 以 AnyThread 量整顆實體核心（SMT 兩執行緒合計），因為前端事件本質是核心層事件。④ 取樣前後完整存讀並還原 PERFEVTSEL0–3 與 GLOBAL_CTRL，不變動作業系統正在使用的固定計數器；若同時有 VTune／PCM 在用計數器，兩者會互相覆蓋。"] = "Honest limits: ① the bad-speculation bucket omits INT_MISC.RECOVERY_CYCLES (the hardware has only 4 general-purpose counters — five events do not fit), so that bucket slightly under-counts and back-end bound slightly over-counts. ② Physical cores are sampled sequentially — different instants, not one snapshot. ③ Measured per physical core with AnyThread (both SMT threads combined) because front-end events are inherently core-level. ④ PERFEVTSEL0–3 and GLOBAL_CTRL are fully saved, read and restored around sampling; the OS's fixed counters are untouched — but VTune/PCM running simultaneously will fight over the counters.",
        ["誠實界線：倍頻表是「目前的設定」而非原廠規格——BIOS 解鎖改過就是改過的值，本工具不還原成規格書數字。有效時脈是取樣窗內的平均，不是瞬時峰值。「黃金核心」需要 HWP 的逐核心 Highest Performance（MSR 0x771）；讀不到就不宣稱任何一顆是黃金核心。"] = "Honest limits: the ratio table is \"current settings\", not factory spec — a BIOS unlock means changed values; this tool never reverts to spec-sheet numbers. Effective clock is the sampling-window average, not an instantaneous peak. \"Golden core\" needs HWP's per-core Highest Performance (MSR 0x771); unreadable → no golden-core claims.",
        ["說明"] = "Description",
        ["調整風扇轉速為真實寫入主機板控制器。轉速過低可能使機殼／處理器溫度上升，請一邊觀察溫度一邊調整。切換分頁或關閉程式時，所有手動接管的風扇都會自動交回 BIOS 控制。"] = "Adjusting fan speed writes to the motherboard controller for real. Too low a speed can raise case/CPU temperature — watch temperatures as you adjust. Switching tabs or closing the program hands all manually-controlled fans back to BIOS.",
        ["識別碼與平台能力"] = "Identity & platform capability",
        ["讀入 GPU-Z sensor log（txt）、AIDA64 XML 或 HWiNFO CSV，與時間膠囊交叉比對。不捆綁工具，只讀使用者選的檔案。"] = "Reads GPU-Z sensor logs (txt), AIDA64 XML or HWiNFO CSV and cross-checks with time capsules. No bundled tools — only files you pick.",
        ["讀取"] = "Read",
        ["讀取並量測"] = "Read & measure",
        ["讀取磁碟通電時數"] = "Read disk power-on hours",
        ["讀取電池設計容量、目前滿充容量與耗損率，並可產生 Windows 官方完整電池報告。僅適用於筆電／平板。"] = "Reads design capacity, current full-charge capacity and wear rate, and can generate Windows' official full battery report. Laptops/tablets only.",
        ["讀寫吞吐"] = "Read/write throughput",
        ["負載型態"] = "Load pattern",
        ["負載延遲（重壓下的等待）"] = "Loaded latency (waiting under pressure)",
        ["負載線校準 LLC"] = "Load-line calibration LLC",
        ["超頻屬進階操作，可能造成系統不穩定。使用本功能所導致的任何後果，包含但不限於："] = "Overclocking is an advanced operation and can destabilize the system. Any consequence of using this feature, including but not limited to:",
        ["超頻風險告知"] = "Overclocking risk notice",
        ["越低越保守一致（適合客觀評測），越高越發散有創意。"] = "Lower is more consistent and conservative (good for objective review); higher is more creative and divergent.",
        ["跑分紀錄簿"] = "Benchmark logbook",
        ["跨 LLC"] = "Cross-LLC",
        ["載入"] = "Load",
        ["輸出資料夾"] = "Output folder",
        ["轉速"] = "Speed",
        ["轉速曲線"] = "Fan curve",
        ["近 30 天的機器病歷：非預期關機（Kernel-Power 41／6008）、藍屏（BugCheck 1001）、應用程式當機與停止回應（1000／1002），以及開機耗時趨勢（Diagnostics-Performance 100）。只呈現事件與時間，不下診斷結論。"] = "The machine's last 30 days of medical records: unexpected shutdowns (Kernel-Power 41/6008), BSODs (BugCheck 1001), app crashes and hangs (1000/1002), and boot duration trends (Diagnostics-Performance 100). Events and times only — no diagnostic conclusions.",
        ["近期警示事件"] = "Recent alert events",
        ["返回"] = "Back",
        ["迷你浮動監視器"] = "Mini floating monitor",
        ["退休"] = "Retired",
        ["退休占比"] = "Retired share",
        ["送出"] = "Submit",
        ["逐字串流"] = "Stream tokens",
        ["逐字串流回覆"] = "Streaming replies",
        ["逐核時間歸因（閒置／使用者／核心／DPC／中斷）"] = "Per-core time attribution (idle / user / kernel / DPC / interrupt)",
        ["逐核液柱的波紋與氣泡、風扇葉片的旋轉、七段數字的漸亮——這些都對應真實讀值，但每一次重繪都要花 GPU 與封裝功耗。曦覽是量測工具，所以這件事必須關得掉。"] = "Liquid ripples and bubbles in the per-core tubes, spinning fan blades, seven-segment digits fading in — all tied to real readings, but every repaint costs GPU and package power. XinSpect is a measurement tool, so this must be switchable.",
        ["逐核液柱：液面高度是該核使用率，顏色是該核溫度（與熱區圖同一套色階），管壁上的細線是最近數秒的高點。灰管＝拿不到那顆核心的溫度。"] = "Per-core liquid tubes: height is utilization, color is temperature (the same scale as the thermal map), the thin wall line is the last few seconds' peak. A gray tube = no temperature for that core.",
        ["逐核逐銀行讀 IA32_MCi_STATUS：位 63 valid、位 61 不可修正、位 38–52 為已修正錯誤計數。已修正＝系統沒崩、使用者無感——但計數往上跑就是記憶體／IMC 劣化的最早訊號。只列出有內容的銀行；歷史紀錄另見上方 WHEA 卡片。"] = "Reads IA32_MCi_STATUS bank by bank, core by core: bit 63 valid, bit 61 uncorrected, bits 38–52 corrected-error count. Corrected = no crash, the user never noticed — but a climbing count is the earliest sign of memory/IMC degradation. Only banks with content are listed; history lives in the WHEA card above.",
        ["逐級刻意閒置（0 到 4000 毫秒），每一級結束後只讀一筆 4K、只計時那一筆。未緩衝讀取，位移每次不同，避免快取讓第二次變快而看不出降態。整趟約 8 秒，全部是讀取。"] = "Deliberate idles from 0 to 4000 ms; after each level exactly one 4K read, timed, nothing else. Unbuffered, with a different offset each time so the cache cannot make the second read fast and hide the transition. The whole sweep is ~8 seconds, all reads.",
        ["逐邏輯處理器有效時脈（實測）"] = "Per-logical-processor effective clocks (measured)",
        ["逐邏輯處理器（CallNtPowerInformation）"] = "Per logical processor (CallNtPowerInformation)",
        ["逐鍵按下確認觸發（按過的鍵會保持標記）　同時按多鍵測試防鬼鍵／NKRO　連按兩下 Esc：離開"] = "Press each key to confirm (pressed keys stay marked)  hold many keys for anti-ghosting/NKRO  double-tap Esc: exit",
        ["這一段的存在本身就是結論的一部分：有了它，你才分得出「檢查過沒問題」與「根本沒檢查」。要納入哪一項，就去括號裡的那一頁按一下量測——本頁不會替你發動任何會讓機器發熱的動作。"] = "This section's existence is part of the conclusion: it is what lets you tell \"checked, fine\" from \"never checked\". To include an item, go to the page named in brackets and press measure — this page never triggers anything that heats the machine itself.",
        ["這不是 MemTest86 的替代品：作業系統的虛擬記憶體讓程式無法指定實體位址，也碰不到已被系統與其他行程佔用的頁面，因此本檢測只覆蓋當下配置得到的那一段——通過不代表整條記憶體沒問題，但只要出現一處不符，那就是真的量到了。要徹底確認請在開機前環境跑滿整條記憶體。"] = "Not a MemTest86 replacement: the OS's virtual memory means the program cannot choose physical addresses or touch pages held by the system and other processes — this test only covers what it can allocate right now. Passing does not prove the whole memory is fine, but a single mismatch is a real, measured finding. For thorough verification, run a full-coverage test in a pre-boot environment.",
        ["這些動作實際做了什麼（誠實說明）"] = "What these actions actually do (honest explanation)",
        ["這些操作都是安全的，不會改動重要設定。"] = "These operations are safe and change nothing important.",
        ["這個數字是影像本身的資料率，不是線路上的位元率：DisplayPort 1.x 的 8b/10b 編碼要再多兩成，HDMI 的 TMDS 亦有各自的開銷。兩者不該混為一談，本頁只給前者。"] = "This number is the pixel data rate, not the wire bit rate: DisplayPort 1.x's 8b/10b encoding adds another 20%, and HDMI's TMDS has its own overhead. They must not be conflated; this page gives the former only.",
        ["這個數字的前提與限制"] = "Premises and limits of this number",
        ["這個程式由多個 AI 模型協力完成。"] = "This program was built with the help of multiple AI models.",
        ["這台機器多老了"] = "How old is this machine",
        ["通道分配"] = "Channel population",
        ["通道數"] = "Channel count",
        ["通道："] = "Channels:",
        ["進入延遲"] = "Entry latency",
        ["進階 Advanced"] = "Advanced",
        ["遊戲繪圖"] = "Game graphics",
        ["運作中介面（即時流量）"] = "Operating intermediary (live traffic)",
        ["運算正確性"] = "Computational correctness",
        ["運算穩定性壓測（y-cruncher）"] = "Computational stability stress (y-cruncher)",
        ["達成率"] = "Achievement rate",
        ["遞迴掃描資料夾，列出最占空間的大檔；勾選後並以逐位元組 SHA-256 比對，真實判定內容完全相同的重複檔與可回收空間。存取被拒的目錄自動略過。為安全起見僅提供定位，刪除請於檔案總管確認後自行處理。"] = "Recursively scans folders listing the biggest space hogs; checked files are compared byte-by-byte with SHA-256 to truly identify duplicates and reclaimable space. Access-denied directories are skipped automatically. For safety it only locates — deletion is yours to do in File Explorer after confirming.",
        ["遠端位址"] = "Remote address",
        ["適合玩遊戲嗎"] = "Is it good for gaming?",
        ["遮蔽可識別資訊"] = "Mask identifying info",
        ["遲滯"] = "Hysteresis",
        ["遷移分層"] = "Migration tiers",
        ["遷移次數"] = "Migrations",
        ["遷移率"] = "Migration rate",
        ["選一份原廠（或信任來源）的 BIOS 區映像，與快閃可讀面逐 4KB 塊比對；大小不符會誠實拒比。"] = "Pick a factory (or trusted-source) BIOS region image to compare against the flash's readable area block by block (4 KB); a size mismatch honestly refuses to compare.",
        ["選一個最像你碰到的狀況。每個場景會列出可能原因、檢查步驟與建議動作，最後附一個連結帶你到更詳細的分析頁面。"] = "Pick the closest match. Each scenario lists possible causes, check steps and a recommended action, ending with a link to a deeper analysis page.",
        ["選擇 DNS（套用至上方選定的介面卡）"] = "Choose DNS (applies to the adapter selected above)",
        ["選擇要回顧的時間長度"] = "Choose how far back to look",
        ["選擇要顯示哪些區塊、調整上下順序"] = "Choose visible sections and their order",
        ["選擇資料夾"] = "Choose folder",
        ["選擇顯示全部硬碟或單一硬碟"] = "Show all drives or a single drive",
        ["還原上一版備份"] = "Restore previous backup",
        ["還原內建的顯示項目與順序"] = "Restore built-in sections and order",
        ["還原安全預設"] = "Restore safe defaults",
        ["還原自動"] = "Restore auto",
        ["還原預設"] = "Restore defaults",
        ["還沒納入判斷的部分"] = "Not yet part of the verdict",
        ["邊產生邊顯示，長篇評價不必乾等；端點不接受串流時會自動退回整段模式，不會失敗。"] = "Streams as generated — long reviews need no waiting; auto-falls back to whole-reply mode if the endpoint refuses streaming, never failing.",
        ["邊界可信度（偏差 < 20% 高可信、20–50% 中可信、> 50% 低可信；未配對宣稱值不列入）。"] = "Boundary confidence (deviation <20% high, 20–50% medium, >50% low; unpaired claims excluded).",
        ["邏輯處理器"] = "Logical processors",
        ["部分系統工具（如記憶體診斷、磁碟管理）可能要求系統管理員權限；DDU 建議於安全模式下使用。"] = "Some system tools (memory diagnostics, disk management) may need administrator; DDU is best used in Safe Mode.",
        ["釋放記憶體"] = "Free memory",
        ["重新偵測"] = "Re-detect",
        ["重新偵測外部來源"] = "Re-detect external sources",
        ["重新分析"] = "Re-analyze",
        ["重新執行所有模組的偵測與載入（系統與硬體資訊、感測器引擎、網路／行程、磁碟資訊、螢幕色域、CUDA、超頻／顯示卡超頻引擎、winget、深度規格與體驗指數）。若某項功能在啟動時未就緒，可於此重試，不會中斷每秒監控。"] = "Re-runs every module's detection and loading (system & hardware info, sensor engine, network/processes, disk info, screen gamut, CUDA, overclocking/GPU overclocking engines, winget, deep specs and the Experience Index). Retry here anything that was not ready at startup — the per-second monitoring is never interrupted.",
        ["重新掃描"] = "Rescan",
        ["重新整理"] = "Refresh",
        ["重新查詢"] = "Query again",
        ["重新檢查"] = "Re-check",
        ["重新評分"] = "Re-score",
        ["重新讀取"] = "Re-read",
        ["重新載入"] = "Reload",
        ["重複 INF"] = "Duplicate INFs",
        ["重複檔案"] = "Duplicate files",
        ["重複驅動偵測"] = "Duplicate driver detection",
        ["重開機進入 UEFI 設定"] = "Reboot into UEFI settings",
        ["量一次"] = "Measure once",
        ["量到什麼"] = "What was measured",
        ["量每一支驅動的 DPC／ISR 在 CPU 上的執行時長，排出肇事模組排行（ETW 核心追蹤，零驅動安裝）。音訊爆音、滑鼠瞬間停頓、串流掉幀，往往是某支驅動的 DPC 吃掉數百微秒——這個資料只有作業系統知道。經驗法則：單次超過 1000 µs 就值得注意，但它只是統計不是判決。"] = "Measures how long each driver's DPCs/ISRs run on CPU, ranking the guilty modules (ETW kernel tracing, zero driver installs). Audio pops, mouse freezes, stream frame drops are often one driver's DPC eating hundreds of microseconds — data only the OS knows. Rule of thumb: a single event over 1000 µs deserves attention; it is a statistic, not a verdict.",
        ["量測"] = "Measure",
        ["量測對外網路的延遲、下載與上傳速度。需連外，測試期間會消耗流量。NTU 台大（臺灣學術網路）與 SGIX（新加坡交換中心）可原生量測；HKBN 香港寬頻與測速網（中國大陸）未提供公開量測端點，將跳轉至內建瀏覽器開啟其官方測速頁，測完可由瀏覽器工具列的「回到測速頁面」返回。"] = "Measures latency, download and upload to the outside world. Needs internet; consumes traffic during the test. NTU (Taiwan academic network) and SGIX (Singapore) measure natively; HKBN Hong Kong and Speedtest (mainland China) have no public measurement endpoints — they open their official speed-test pages in the embedded browser instead; \"Back to speed test\" in the toolbar returns.",
        ["量測時長"] = "Measurement duration",
        ["量測條件"] = "Measurement conditions",
        ["金鑰是這台機器的憑證，貼給別人等於把授權交出去。抄下來收好就把它藏回去。"] = "The key is this machine's credential — pasting it to someone hands over the license. Copy it, stash it, and hide it again.",
        ["釘選於最上層"] = "Pin on top",
        ["錯誤推測"] = "Bad speculation",
        ["鍵盤檢測"] = "Keyboard test",
        ["長幀（≥1.5×中位數）"] = "Long frames (≥1.5× median)",
        ["開啟"] = "Open",
        ["開啟 AI 助手分頁　▸"] = "Open the AI assistant tab  ▸",
        ["開啟 Intel 官方下載中心（編號 17881）"] = "Open Intel's official download center (id 17881)",
        ["開啟 diag.log"] = "Open diag.log",
        ["開啟下載資料夾"] = "Open the Downloads folder",
        ["開啟主機板廠官方 BIOS 下載頁"] = "Open the board vendor's official BIOS download page",
        ["開啟傾印資料夾"] = "Open the dump folder",
        ["開啟全螢幕純色檢測（Esc 離開）"] = "Open the fullscreen solid-color test (Esc exits)",
        ["開啟動態效果（液柱波紋、風扇葉片、數字漸亮）"] = "Enable dynamic effects (liquid ripples, fan blades, digit fade-in)",
        ["開啟圖形介面"] = "Open the GUI",
        ["開啟後，AI 可自行呼叫 33 項唯讀查詢工具（完整規格、處理器拓樸、即時讀值、所有溫度、感測器總表、風扇與曲線、磁碟健康、事件紀錄、歷史統計、顯示卡與處理器調校現況、場景、健康總評、環境自檢、效能成績、記憶體時序與 SPD、網路組態與流量、螢幕 EDID 色域、升級建議、電池健康、開機啟動項、藍屏傾印，以及 11 項硬核底層事實：Top-down 管線歸因、頻率真相、平台可信度、BIOS 與 ME 微碼、逐核時間歸因、電源政策、記憶體認可帳本、機器檢查與 WHEA、處理器免疫位元、RDT 監測、效能天花板），並在對話中列出每次查詢。全部只讀不寫：不會改設定、不會動硬體、不會啟動任何程式，也不會自己去發動 PMU／MSR 量測——硬核項目你沒按過量測，AI 就只會說「本機尚未量測」。關閉則只送出一次硬體快照。"] = "Once on, the AI can call 33 read-only query tools itself (full specs, CPU topology, live readings, all temperatures, the sensor table, fans and curves, disk health, event log, history stats, GPU/CPU tuning state, scenarios, health summary, environment check, benchmark scores, memory timings & SPD, network config and traffic, display EDID gamut, upgrade advice, battery health, startup entries, BSOD dumps, plus 11 hardcore low-level facts: Top-down pipeline attribution, frequency truth, platform trustworthiness, BIOS & ME microcode, per-core time attribution, power policy, commit ledger, machine check & WHEA, CPU immunity bits, RDT monitoring, performance ceiling) and lists every query in the conversation. All read-only: no settings changed, no hardware touched, no programs launched, and it never triggers PMU/MSR measurements itself — hardcore items you have not measured are reported as \"not measured on this machine\". Off = one hardware snapshot per request.",
        ["開啟後，報告中的主機名稱、使用者名稱、MAC 位址與磁碟序號改以「（已遮蔽）」輸出，其餘規格與讀值照實不動。要把報告貼到公開場合時再開；自己留存的報告該是完整的。曦覽不提供「產生分享網址」——那必然得把這台機器的硬體資訊送到別人的伺服器上存放，送出就收不回來；要分享請直接分享這份檔案。"] = "When on, the report's hostname, user name, MAC addresses and disk serials come out as \"(masked)\"; the rest of the specs and readings stay verbatim. Turn on for public sharing; your own archives should be complete. XinSpect offers no \"share link\" — that would necessarily upload this machine's hardware info to someone else's server, and sent is sent; share the file itself.",
        ["開啟或關閉 BlueSquadronBridge 守護進程"] = "Start or stop the BlueSquadronBridge guard daemon",
        ["開啟所在資料夾"] = "Open containing folder",
        ["開啟拖影與幀間隔檢測（Esc 離開）"] = "Open the ghosting & frame-interval test (Esc exits)",
        ["開啟歷史回放"] = "Open History Replay",
        ["開啟滑鼠按鍵／滾輪／回報率檢測（Esc 離開）"] = "Open the mouse buttons / wheel / report-rate test (Esc exits)",
        ["開啟獨立視窗：每核心即時溫度、每核心電壓設定值與封裝 Vcore／電流波形"] = "Open a separate window: per-core live temperature, per-core voltage setpoints, package Vcore / current waveforms",
