        ["開機時自動啟動（工作排程器・最高權限，登入靜默啟動、可還原）"] = "Launch at boot (Task Scheduler · highest privilege, silent at logon, reversible)",
        ["開機為什麼慢"] = "Why is boot slow",
        ["開機耗時分解"] = "Boot duration breakdown",
        ["開機自動回復最後穩定設定（崩潰重開後）"] = "Auto-restore last stable settings at boot (after a crash-restart)",
        ["開機至今撞過的牆（黏滯紀錄位）"] = "Walls hit since boot (sticky log bits)",
        ["開發者一概不負任何責任。請確認你已了解並自行承擔風險。"] = "The developer accepts no liability whatsoever. Confirm you understand and accept the risk.",
        ["開＝產生本專案自簽 CA 並裝入信任庫，再嘗試載入 XsRegProbe 白名單唯讀驅動（僅允許清單內的 MSR/MMIO 讀取，退出即卸載）；關＝移除信任並卸載。需要管理員權限，未提權時不會做任何變更。注意：Windows 的核心簽章只接受 Microsoft 信任鏈，自簽驅動在未開 testsigning 的一般機器上會被拒絕載入（錯誤 577）——這是政策，不是設定漏了。WinRing0 只負責 MSR 與 PCI 設定空間（實測可用）；實體記憶體讀取會失敗，所以 SPIBAR／MCHBAR／ECAM 只能靠這支驅動——開發機專用。"] = "On = generates this project's self-signed CA into the trust store and tries to load the XsRegProbe allowlisted read-only driver (MSR/MMIO reads inside the allowlist only; unloads on exit); Off = removes trust and unloads. Needs administrator; without elevation nothing changes. Note: Windows kernel signing only accepts a Microsoft-trusted chain, so a self-signed driver is refused on machines without test-signing (error 577) — that is policy, not a missing setting. WinRing0 covers MSR and PCI configuration space only (verified working); physical-memory reads fail, so SPIBAR/MCHBAR/ECAM depend on this driver — development machines only.",
        ["關掉之後讀值照樣即時更新，只是液面直接跳到位、葉片停住不轉。看不見的控制項本來就不會重繪（切到別頁即停），所以這個開關管的是「正在看的那一頁」。"] = "With it off, readings still update live — liquid jumps straight to level, blades stop spinning. Invisible controls never repaint anyway (leaving the page stops them), so this switch governs \"the page you are looking at\".",
        ["關鍵差異與注意事項"] = "Key differences & caveats",
        ["關鍵規格與小知識"] = "Key specs & trivia",
        ["關閉"] = "Close",
        ["關閉本程式並以系統管理員權限重新開啟（會跳出 UAC 確認）"] = "Close and relaunch as administrator (a UAC prompt will appear)",
        ["關閉監視器"] = "Close monitor",
        ["防線狀態"] = "Defense status",
        ["附加圖片或檔案（也可拖放或 Ctrl+V 貼上）"] = "Attach images or files (drag-drop or Ctrl+V work too)",
        ["附加圖片或檔案（每個檔案上限 2 MB，最多 5 個）"] = "Attach images or files (max 2 MB each, up to 5)",
        ["限制原因暫存器與 THERM_STATUS 的紀錄位會一直保持，直到有人寫入清除或重新開機。本工具不清除它們——清除需要寫入，而寫入會毀掉別的工具（也包括你下一次自己看）的證據。所以這裡看到的是自開機以來的完整帳。"] = "Limit-reason registers and THERM_STATUS log bits stay set until someone writes them clear or the machine reboots. This tool never clears them — clearing takes a write, and a write destroys the evidence for other tools (and for your own next look). What you see here is the complete ledger since boot.",
        ["隨機 4K 寫入"] = "Random 4K write",
        ["隨機 4K 寫入 ・ 延遲分佈"] = "Random 4K write · latency distribution",
        ["隨機 4K 讀取"] = "Random 4K read",
