        ["離開延遲"] = "Exit latency",
        ["離開超頻功能，回到安全的地方"] = "Leave overclocking, return to safety",
        ["電池健康度（耗損率）"] = "Battery health (wear rate)",
        ["電源接頭"] = "Power connectors",
        ["電源接頭參考"] = "Power connector reference",
        ["電源政策實況（藏在進階設定裡的那幾項）"] = "Power policy live (the ones hidden in advanced settings)",
        ["電源計劃"] = "Power plan",
        ["靜止參考"] = "Static reference",
        ["靜音"] = "Mute",
        ["韌體"] = "Firmware",
        ["韌體內嵌金鑰"] = "Firmware-embedded key",
        ["韌體與開機信任鏈"] = "Firmware & boot trust chain",
        ["音效裝置"] = "Audio devices",
        ["頁面大小"] = "Page size",
        ["頂視示意：LGA 腳位在腳座上、CPU 是平面接點；PGA 腳位在 CPU 上。金色三角是第 1 腳標記，插反了對不上——照三角對齊角落即可。柵格點只表示腳位密集，密度不代表實際腳位數。"] = "Top view: LGA pins live in the socket, the CPU is a flat pad array; PGA pins live on the CPU. The gold triangle marks pin 1 — reversed it will not line up; align the triangle with the corner. Grid dots only suggest pin density, not the actual count.",
        ["項檢查"] = "item check",
        ["項目"] = "Item",
        ["預設允許。要並排比對兩份報告、或想一邊燒機一邊在另一個視窗翻別的頁面時用得到。但有三件事要知道：設定與歷史是「最後寫入者贏」（寫檔本身是原子的，不會出現寫一半的檔案，但兩份同時改設定，後存的會蓋掉前一份）；WinRing0 驅動是全機共用的服務，其中一份結束時會把它收掉，另一份剩下的暫存器讀取就會開始顯示「—」，重開那一份即可；兩份同時做寫入型量測（超頻套用、體質特徵化、燒機）會互相干擾結果，數字不能當真。關掉此項就回到單一實例：第二份會把既有視窗叫回前景後自行結束。"] = "Allowed by default. Useful for comparing two reports side by side or burn-testing while reading another page. Three things to know: settings and history are last-writer-wins (writes are atomic — no half files — but two simultaneous edits means the later save overwrites the earlier); the WinRing0 driver is a machine-wide service, one instance exiting takes it down and the other's register reads start showing \"—\" until that one is restarted; simultaneous write-type measurements (OC apply, bin characterization, burn-in) interfere — do not trust those numbers. Off = single instance: a second launch brings the existing window to front and exits.",
        ["預設紀年"] = "Default era format",
        ["預設關閉。開啟後，只要溫度或負載越過上方的警示上限，就會自動在 AI 分頁發起一次診斷（同一項目最少間隔 10 分鐘）。這會在你沒開口時送出請求——若你用的是計費 API，費用會照算；端點或模型還沒填妥時則安靜略過。"] = "Off by default. When on, any temperature/load crossing its alert limit auto-triggers one AI diagnosis on the AI tab (same item at most every 10 minutes). This sends requests without you asking — a paid API bills accordingly; with no endpoint/model configured it silently skips.",
        ["頻寬"] = "Bandwidth",
        ["頻寬佔比"] = "Bandwidth share",
        ["頻率・功耗・熱設計"] = "Frequency · power · thermal design",
        ["頻率真相（倍頻表與實際 BCLK）"] = "Frequency truth (ratio table & actual BCLK)",
