        ["顯示卡分析"] = "GPU analysis",
        ["顯示卡功耗與溫度上限（需 NVIDIA + NVML）"] = "GPU power & temperature limits (needs NVIDIA + NVML)",
        ["顯示記憶體時脈"] = "Memory clock",
        ["顯示記憶體頻率偏移"] = "Memory clock offset",
        ["顯示鏈路真相"] = "Display link truth",
        ["顯示項目"] = "Visible sections",
        ["顯示／隱藏完整金鑰"] = "Show / hide full key",
        ["風扇曲線樣板"] = "Fan curve templates",
        ["風扇轉速控制"] = "Fan speed control",
        ["風扇部分沿用「系統風扇」分頁的曲線引擎，套用後由每秒脈動持續依溫度調速；離開程式時所有接管的風扇都會交回 BIOS。電源計劃以 powercfg 切換，Windows 11 若隱藏了「高效能／最佳效能」，會自動以 duplicatescheme 建立後再切換——這是系統支援的做法，不會改動其他計劃。顯示卡功耗與溫度上限需要 NVIDIA 驅動的 NVML 介面；AMD／Intel 顯示卡會被如實略過。"] = "The fan part reuses the \"System Fans\" tab's curve engine, applying speed by temperature every second after applying; leaving the program returns all taken-over fans to BIOS. Power plans switch via powercfg — if Windows 11 hides \"High performance / Best performance\", one is created with duplicatescheme then switched — the system-supported way, other plans untouched. GPU power and temperature limits need NVIDIA's NVML; AMD/Intel cards are honestly skipped.",
        ["首頁（硬體導航）"] = "Home (hardware navigation)",
        ["馬蹄形外框是可見光光譜軌跡；虛線三角形是 sRGB 標準，實心半透明三角形是本機螢幕的色域。三角形越貼近光譜軌跡，能顯示的顏色越飽和。"] = "The horseshoe is the visible-spectrum locus; the dashed triangle is the sRGB standard; the filled translucent triangle is this display's gamut. The closer the triangle hugs the locus, the more saturated the displayable colors.",
