        ["剩餘"] = "Remaining",
        ["防禦態勢優良——大多數已知攻擊面已封閉。"] = "Strong defensive posture — most known attack surfaces are closed.",
        ["防禦態勢尚可——仍有數項可改進的弱點。"] = "Fair defensive posture — several weaknesses remain improvable.",
        ["防禦態勢偏弱——存在可被利用的顯著缺口。"] = "Weak defensive posture — exploitable gaps are present.",
        ["防禦態勢危險——多條防線未啟用或存在已知漏洞。"] = "Dangerous defensive posture — multiple defense lines are off or known vulnerabilities exist.",
        // ── 2026-10-08 第二輪：ConverterParameter 模板＋收割缺口補翻 ──
        ["\\Microsoft\\… 底下的工作是作業系統自己的維護工作，預設不列出"] = "Entries under \\Microsoft\\… are OS maintenance tasks and are hidden by default",
        ["✓ 已複製"] = "✓ Copied",
        ["上傳逾時，請稍後再試。你寫的內容還留在框裡。"] = "Upload timed out, please try again later. Your text is still in the box.",
        ["供「歷史回放」查詢的資料倉：最近一小時保留秒級原始取樣，更早則按分鐘存下最小／平均／最大值。落地於 %APPDATA%\\XinSpect\\history.bin，一個月約數 MB。"] = "Data store queried by History Replay: raw per-second samples for the last hour, then per-minute min/avg/max. Stored at %APPDATA%\\XinSpect\\history.bin, a few MB per month.",
        ["停止載入"] = "Stop loading",
        ["儲存失敗："] = "Save failed: ",
        ["初始化時發生錯誤："] = "Error during initialization: ",
        ["剪貼簿目前被其他程式佔用，請稍後再試（或改用「匯出報告…」存成 .md）。"] = "The clipboard is busy with another program, try again later (or use \"Export report…\" to save as .md).",
        ["可執行檔 (*.exe)"] = "Executable (*.exe)",
        ["執行檔 (*.exe)"] = "Executable (*.exe)",
        ["所有檔案 (*.*)"] = "All files (*.*)",
        ["定位失敗："] = "Reveal failed: ",
        ["對話存於 %APPDATA%\\XinSpect\\aichat.json（僅本機純文字，不含金鑰），最多保留最後 240 則。取消勾選會立刻刪除該檔，不只是停止續寫；按 AI 分頁的「清除對話」同樣會一併刪檔。"] = "Chats are stored at %APPDATA%\\XinSpect\\aichat.json (local plain text, no keys); the last 240 messages are kept. Unchecking deletes the file immediately, not just stops appending; \"Clear chat\" on the AI tab deletes it too.",
        ["尚無備份可還原。"] = "No backup to restore.",
        ["尚無對話。點「一鍵評價本機」讓 AI 依真實數據評價，或於下方輸入問題。提示：本機 Ollama 免費且離線，資料不會離開這台電腦。"] = "No conversation yet. Click \"One-click local review\" to let the AI evaluate this machine from real data, or type a question below. Tip: local Ollama is free and offline; data never leaves this PC.",
        ["左右交替　順序為 左→右→左→右；若與畫面指示相反，就是聲道接反了（單次，約 6 秒）"] = "Alternating L/R: order is L→R→L→R; if it opposes the on-screen cue, your channels are swapped (once, ~6 s)",
        ["已上香，心誠則靈"] = "Incense lit — sincerity works",
        ["🔒 絕密技術（CLASSIFIED）— 經實地場強量測，乖乖神力有效覆蓋範圍為：大中國全境、日本國（包含其代管地區琉球）、大韓民國（包括北韓地區）、印度支那半島、馬來亞半島與馬來群島在內之泛中華區。上述區域以外之矽晶體因超出乖乖場等效輻射邊界，諧振安撫效應不具理論保證，擅自跨區部署概不負責。"] = "🔒 CLASSIFIED — field-strength measurements put the effective coverage of Guai-Guai divinity at: Greater China, Japan (including its administered Ryukyus), the Republic of Korea (including the North), Indochina, and the pan-Chinese region covering the Malay Peninsula and the Malay Archipelago. Silicon outside these areas lies beyond the Guai-Guai field's equivalent radiation boundary, where the resonant soothing effect carries no theoretical guarantee; cross-region deployment is at your own risk.",
        ["已匯出並開啟："] = "Exported and opened: ",
        ["已取消"] = "Cancelled",
        ["已取消匯出。"] = "Export cancelled.",
        ["已取消掃描。"] = "Scan cancelled.",
        ["已於檔案總管中定位該項目。"] = "Revealed the item in File Explorer.",
        ["已複製 Markdown 報告到剪貼簿，可直接貼上論壇或議題。"] = "Markdown report copied to the clipboard — paste it straight into a forum or issue.",
        ["已複製 ✓"] = "Copied ✓",
        ["已跳轉至內建瀏覽器"] = "Opened in the built-in browser",
        ["已送出，謝謝你的建議。"] = "Submitted — thank you for the suggestion.",
        ["已重置為內建預設提示詞。"] = "Reset to the built-in default prompt.",
        ["已開啟啟動資料夾。"] = "Opened the Startup folder.",
        ["已開啟登錄編輯程式（此項為登錄啟動項）。"] = "Opened Registry Editor (this is a registry startup entry).",
        ["已開啟登錄編輯程式，完整路徑已複製到剪貼簿，貼到位址列即可定位。"] = "Opened Registry Editor; the full path is on the clipboard — paste it into the address bar to jump there.",
        ["找不到可用的 Microsoft Edge WebView2 執行階段，或其初始化失敗。"] = "No usable Microsoft Edge WebView2 runtime found, or its initialization failed.",
        ["指定 y-cruncher.exe"] = "Specify y-cruncher.exe",
        ["下載 WebView2 執行階段"] = "Download the WebView2 runtime",
        ["掃描中…"] = "Scanning…",
        ["掃描中……"] = "Scanning……",
        ["掃描失敗："] = "Scan failed: ",
        ["掃描系統小型記憶體傾印（%SystemRoot%\\Minidump），解析停止代碼與參數並判讀常見原因。深入定位肇事驅動需 WinDbg 符號分析。"] = "Scans system minidumps (%SystemRoot%\\Minidump), decodes stop codes and parameters, and interprets common causes. Pinpointing the offending driver needs WinDbg symbol analysis.",
        ["掃頻 20 Hz → 20 kHz　由低到高連續掃過；留意破音、雜音與突然安靜的頻段（單次，約 8 秒）"] = "Sweep 20 Hz → 20 kHz: continuous low-to-high sweep; listen for distortion, noise, or bands that suddenly go quiet (once, ~8 s)",
        ["收起心路歷程　▴"] = "Collapse history ▴",
        ["收起更早的版本　▴"] = "Collapse earlier versions ▴",
        ["整理中…"] = "Tidying…",
        ["曦覽 XinSpect — 特殊型號徽章一覽"] = "XinSpect — special model badge gallery",
        ["本機歷次成績，新的在上。同項目、同設定才可直接相比；「量測條件」是跑分當時實際讀到的溫度與頻率，沒有感測器時留空而不以 0 充數。紀錄存於 %APPDATA%\\XinSpect\\bench-history.json，可在設定頁一併清除。"] = "Past local runs, newest first. Only same test with same settings is directly comparable; \"conditions\" are temperature and clock actually read at run time, left blank (never 0) when no sensor exists. Records: %APPDATA%\\XinSpect\\bench-history.json, clearable on the Settings page.",
        ["本機歷次跑分成績（含當時的溫度與頻率），存於 %APPDATA%\\XinSpect\\bench-history.json，最多保留 300 筆。曦覽不內建任何別台機器的參考分數，這份紀錄就是「與上次相比」「重複性」的唯一依據——清空後在累積出新紀錄前，跑分只會有單次數字而無從比較。"] = "Past local benchmark results (with temperature and clock at run time) live in %APPDATA%\\XinSpect\\bench-history.json, up to 300 entries. XinSpect ships no reference scores from other machines; this record is the only basis for \"vs. last run\" and repeatability — once cleared, a new run shows only a single number with nothing to compare against.",
        ["檢測視窗已開啟；按 Esc 即可回到曦覽。"] = "Test window opened; press Esc to return to XinSpect.",
        ["歡迎使用曦覽"] = "Welcome to XinSpect",
        ["正在上傳…"] = "Uploading…",
        ["正在重新初始化所有功能，請稍候…"] = "Re-initializing all features, please wait…",
        ["每核心明細（溫度・電壓・波形）"] = "Per-core detail (temp · voltage · waveform)",
        ["波長（nm）沿光譜軌跡：380 → 700"] = "Wavelength (nm) along the spectral locus: 380 → 700",
        ["清理中……"] = "Cleaning…",
        ["清除 DNS 快取失敗："] = "DNS cache flush failed: ",
        ["測試中止"] = "Test aborted",
        ["測速完成"] = "Speed test complete",
        ["準備中…"] = "Preparing…",
        ["無法寫入 hosts 檔：權限不足。 請以系統管理員身分重新啟動曦覽。"] = "Cannot write the hosts file: access denied. Restart XinSpect as administrator.",
        ["版本 2.30 ・ Olympus ・ 便攜單一執行檔"] = "Version 2.30 · Olympus · portable single executable",
        ["目前沒有網路連線，無法上傳。你寫的內容不會消失，接上網路後再按上傳即可。"] = "No network connection, cannot upload. Your text is not lost — press Upload again once you are back online.",
        // ── 統計哨兵：靜態文案（動態結論字串由 TComposite 逐段翻） ──
        ["方法：Theil–Sen 穩健斜率（趨勢）、CUSUM 累積和（變化點）、Pearson 相關性（關係）。只陳述數列本身的變化，不對硬體健康下結論；判讀留給使用者。"] = "Methods: Theil–Sen robust slope (trend), CUSUM cumulative sum (change points), Pearson correlation (relationship). States only how the series itself changed — never a conclusion about hardware health; interpretation is yours.",
        ["確定要清理所選項目？被刪除的暫存檔無法還原（資源回收筒的內容將永久清空）。"] = "Clean the selected items? Deleted temporary files cannot be restored (Recycle Bin contents will be emptied permanently).",
        ["結束 曦覽"] = "Exit XinSpect",
        ["處理器單核 2,000 MOPS ‧ 處理器多核 40,000 MOPS ‧ 記憶體頻寬 100 GB/s ‧ 顯示卡算力 100 TFLOPS ‧ 儲存循序讀取 7,000 MB/s ‧ 儲存循序寫入 5,000 MB/s ‧ NPU 50 TOPS"] = "CPU single-core 2,000 MOPS · CPU multi-core 40,000 MOPS · Memory bandwidth 100 GB/s · GPU compute 100 TFLOPS · Storage sequential read 7,000 MB/s · Storage sequential write 5,000 MB/s · NPU 50 TOPS",
        ["複製失敗"] = "Copy failed",
        ["請先勾選要清理的項目。"] = "Tick at least one item to clean first.",
        ["請先選擇有效的資料夾。"] = "Choose a valid folder first.",
        ["請先選擇網路介面卡。"] = "Choose a network adapter first.",
        ["超頻風險確認"] = "Overclocking Risk Confirmation",
        ["載入失敗："] = "Load failed: ",
        ["這個版本還沒有收件端點，暫時無法直接上傳；請改用「GitHub 開源」那張卡片的連結提交 Issue。"] = "This build has no intake endpoint yet, so direct upload is unavailable; use the link on the \"GitHub open source\" card to file an issue instead.",
        ["選擇要掃描的資料夾"] = "Choose a folder to scan",
        ["還原失敗："] = "Restore failed: ",
        ["重複檔案：未發現內容完全相同的重複檔。"] = "Duplicates: no files with identical content found.",
        ["金鑰只存在本機 %APPDATA%\\XinSpect\\settings.json（純文字，未加密——同一台電腦上的其他程式讀得到）。曦覽不會把金鑰寫進報告、記錄檔或任何對外請求以外的地方。"] = "The key is stored only in %APPDATA%\\XinSpect\\settings.json (plain text, unencrypted — other programs on this PC can read it). XinSpect never writes the key into reports, logs, or anywhere besides direct API requests.",
        ["開啟登錄編輯程式失敗："] = "Failed to open Registry Editor: ",
        ["顯示主視窗"] = "Show main window",
        ["顯示項目（FPS 三行讀「幀時間監測」頁的即時量測）"] = "Shown items (the FPS three lines read the live Frame-time page)",
        ["，尚未開發完全，仍在持續完善中。"] = ", still under development and being improved.",
        ["📎 附加檔案…"] = "📎 Attach files…",
        ["等待首次掃描…"] = "Waiting for first scan…",

        // ── 關於頁・第三方授權（U10-UI-0034）──
        ["第三方授權"] = "Third-party licenses",
        ["授權清單檔讀不到"] = "License list file could not be read",
        ["授權清單讀到了，但抽不出元件表——檔案格式可能變了"] = "The license list was read, but no component table could be parsed — the file format may have changed",
        ["隨程式分發的第三方元件與其授權；本清單是事實摘要，不構成法律意見，授權全文以上游連結為準。"] = "Third-party components shipped with the program and their licenses; this is a factual summary, not legal advice. Full license texts live at the upstream links.",

        // ── 總覽健康摘要卡（U10-UI-0048／ui.home.healthcards）：磁貼標題、欄位標籤、
