        ["健康度、溫度與硬體清單——簡易模式首頁"] = "Health, temperatures and hardware at a glance — the home page for Simple mode",
        ["整機規格與即時狀態一覽"] = "A complete overview of system specifications and live status",
        ["交給 AI 診斷本機硬體並提出建議"] = "Ask AI to diagnose this PC's hardware and suggest improvements",
        ["把已量到的讀值合起來看：現在卡住這台機器的是什麼"] = "Correlates measured readings to show what is limiting this PC right now",
        ["處理器完整規格、快取、拓樸與核心負載"] = "Processor specifications, cache, topology and per-core load",
        ["偵測 Intel／AMD／Qualcomm NPU 並回報驅動與估計算力"] = "Detects Intel, AMD and Qualcomm NPUs and reports drivers and estimated compute capability",
        ["記憶體模組、SPD 與主／次要時序"] = "Memory modules, SPD data and primary/secondary timings",
        ["主機板、晶片組與 BIOS 資訊"] = "Motherboard, chipset and BIOS information",
        ["顯示卡規格、顯示記憶體與螢幕色域"] = "Graphics card specifications, video memory and display gamut",
        ["磁碟容量、健康度與讀寫活動"] = "Drive capacity, health and read/write activity",
        ["網路介面、位址與即時流量"] = "Network interfaces, addresses and live traffic",
        ["所有感測器的完整明細總表"] = "A complete detail table for all sensors",
        ["既有感測事實的監看版：核×時間熱圖、電壓對 ATX 規格帶、統計控制圖與異常日曆"] = "Live views of collected sensor data: core-by-time heatmap, voltage vs. ATX limits, statistical control chart and anomaly calendar",
        ["數週的溫度／負載走勢回放與統計"] = "Replay and analyze weeks of temperature and load history",
        ["版本化硬體時間膠囊、逐欄差異、PCI／SPD／裝置與健康證據時間軸"] = "Versioned hardware snapshots, field-by-field diffs, and timelines for PCI, SPD, devices and health evidence",
        ["BIOS 寫入保護、SMRAM 鎖定、ME 狀態與 ACPI 錯誤表——讀得到給裁決，讀不到誠實標示（缺 ring0／不支援）"] = "BIOS write protection, SMRAM lock, ME status and ACPI error tables. Available evidence is assessed; unavailable data is identified as requiring Ring 0 or unsupported.",
        ["溫度／負載／容量彙整的健康總評"] = "Overall health summary for temperatures, load and capacity",
        ["跑分、烤機、快取延遲與磁碟效能"] = "Benchmarks, stress tests, cache latency and disk performance",
        ["同一場 Run Session 的 CPU／拓撲／記憶體／GPU／儲存深測與 44 項平台靶向套件"] = "CPU, topology, memory, GPU and storage tests in one run session, with 44-item platform-targeted suites",
        ["為什麼跑不到該有的頻率：溫度牆／功耗牆／電流牆／向量降頻"] = "Find why the CPU cannot reach expected clocks: thermal, power, current or vector-frequency limits",
