        ["本版實作的每一把事實鍵（1,167 把）攤成一張可搜尋的表：誰讀到了值、誰讀不到、誰這一輪沒跑到"] = "Search all 1,167 fact keys implemented in this version and see which were read, unavailable or not collected this run",
