        ["以 y-cruncher 驗運算穩定性：抓 CPU／記憶體在壓力下的靜默運算錯誤（偵測已安裝，不內含執行檔）"] = "Use y-cruncher to detect silent CPU/memory computation errors under load; detects an existing installation and does not bundle the executable",
