        // ── 狀態與工程頁面說明 ──
        ["01 總覽遙測"] = "01 Overview Telemetry",
        ["02 Ring0 暫存器"] = "02 Ring 0 Registers",
        ["03 藍色中隊"] = "03 Blue Squadron",
        ["05 部署與授權"] = "05 Deployment and License",
        ["10　UPS 續航與機櫃 U 數"] = "10　UPS Runtime and Rack Units",
        ["11 項安全態勢與 ETW 事件流的完整呈現請開主介面的「藍色中隊」頁（同一份資料源）；這裡之後會做濃縮的守門矩陣，接上前不放假表。"] = "For the complete view of 11 security-posture checks and the ETW event stream, open Blue Squadron in the main interface (the same data source). A condensed guard matrix will be added here later; no placeholder table is shown.",
        ["1　NVR 儲存容量"] = "1　NVR Storage Capacity",
        ["2　監控接入頻寬"] = "2　Surveillance Uplink Bandwidth",
        ["3　PoE 功率預算"] = "3　PoE Power Budget",
        ["4　交換機背板與包轉發"] = "4　Switch Fabric and Packet Forwarding",
        ["5　光纖衰減與鏈路裕度"] = "5　Fiber Loss and Link Margin",
        ["6　攝影機端壓降"] = "6　Voltage Drop at Cameras",
        ["7　佈線用線量"] = "7　Cabling Requirements",
        ["8　RAID 可用容量"] = "8　Usable RAID Capacity",
        ["9　無線覆蓋"] = "9　Wireless Coverage",
        ["NVR 容量、接入頻寬、PoE、交換機、光纖、壓降、佈線、RAID、無線與 UPS 的設計試算。所有輸入都是你填的設計參數，輸出是公式推導——這一頁不讀本機硬體，數字不是量測值。"] = "Plan NVR capacity, uplink bandwidth, PoE, switching, fiber, voltage drop, cabling, RAID, wireless and UPS. Inputs are design parameters you provide and outputs are calculated from formulas. This page does not inspect local hardware; its numbers are not measurements.",
        ["POWER CONSOLE ・ 唯讀 ・ 不寫任何硬體暫存器"] = "POWER CONSOLE ・ READ ONLY ・ DOES NOT WRITE HARDWARE REGISTERS",
        ["RING0 唯讀 ・ 資料皆為本機即時值，非概念示意"] = "RING 0 READ ONLY ・ Live values from this PC, not illustrative data",
        ["SECTION 01 // 即時遙測（本機現值）"] = "SECTION 01 // Live telemetry (current local values)",
        ["SECTION 02 // RING0 暫存器檢視（唯讀）"] = "SECTION 02 // RING 0 register view (read only)",
        ["SECTION 03 // 藍色中隊安全姿態"] = "SECTION 03 // Blue Squadron security posture",
        ["SECTION 04 // BRIDGE IPC 終端機"] = "SECTION 04 // Bridge IPC terminal",
        ["SECTION 05 // 執行檔 SHA-256 對帳（本機現算）"] = "SECTION 05 // Executable SHA-256 verification (computed locally)",
        ["SMBIOS 的識別欄位（系統序號、機箱序號、資產標籤…）在組裝機與部分主機板上填的是韌體預設字串，看起來像有值其實沒有。這一區如實標出哪些欄位可以當識別用、哪些不可以，並說明機箱類型（判斷這是不是伺服器最直接的證據）。"] = "On custom-built PCs and some motherboards, SMBIOS identity fields (system serial, chassis serial, asset tag, etc.) may contain firmware defaults that look populated but are not unique identifiers. This section shows which fields are usable for identification and explains the chassis type, one of the clearest indicators of a server.",
        ["Windows 的磁碟 API 只回報介面（NVMe／SATA），不區分 M.2 與 U.2。這裡只在有第一手證據時說出外型（例如型號字串帶 SFF／U.2），其餘如實說「未回報」。"] = "Windows disk APIs report the interface (NVMe/SATA), not whether a drive is M.2 or U.2. Form factor is shown only when there is direct evidence, such as SFF or U.2 in the model string; otherwise it is reported as unavailable.",
        ["以下雜湊是開啟這一頁當場對本機檔案計算的 SHA-256；比對對象是 GitHub Release 的 SHA256SUMS.txt。"] = "These SHA-256 hashes are computed from local files when this page opens and compared with SHA256SUMS.txt from the GitHub Release.",
        ["伺服器角色與選用功能只要安裝了就佔三樣成本：磁碟空間、開機與維護時間，以及可被利用的程式碼面積。沒在用的角色不會因為「沒開」就沒有風險——檔案在、服務定義在、更新要跟著裝。本區只陳述裝了什麼與服務狀態，不建議移除任何項目。"] = "Installed server roles and optional features have three costs: disk space, boot and maintenance time, and attack surface. An unused role still carries risk while its files and services remain installed and require updates. This section reports installed roles and service states; it does not recommend removing anything.",
        ["值來自主程式同一條感測管線（LibreHardwareMonitor＋MSR 唯讀）。「—」代表還沒有真實讀值，本控台不補 0、不編數字。"] = "Values come from the same sensor pipeline as the main application (LibreHardwareMonitor plus read-only MSR access). An em dash means no real reading is available; this console does not fill in zeroes or invent values.",
        ["僅向 GitHub 查詢最新版本號，不上傳本機任何資料"] = "Checks GitHub for the latest version number only; no local data is uploaded",
        ["可能是 M.2 的插槽（BIOS 未標型別）"] = "Slots that may be M.2 (type not identified by BIOS)",
        ["域＝鍵的第一段（ac.dmar.summary 的域是 ac）。「本輪量到」只算真的讀到值的那幾把。"] = "A domain is the first segment of a key (the domain of ac.dmar.summary is ac). “Measured this run” counts only keys that returned an actual value.",
        ["清除瀏覽資料（Cookie、快取、本機儲存）"] = "Clear browsing data (cookies, cache and local storage)",
        ["版本 3.25 ・ 雙級安全模式與平台靶向深測 ・ 便攜單一執行檔"] = "Version 3.25 ・ Two-level safety and targeted platform tests ・ Portable single-file executable",
        ["發送 JSON 指令"] = "Send JSON command",
        ["硬體與安全事件時間軸 (TIMELINE)"] = "Hardware and security event timeline",
        ["重新掃描 PCI"] = "Rescan PCI",
        ["重設縮放為 100%"] = "Reset zoom to 100%",
        ["金鑰只存在本機 %APPDATA%\\XinSpect\\settings.json，並以 Windows DPAPI 加密（只有本機、此使用者帳號解得開；換機器或換帳號就解不開）。曦覽不會把金鑰寫進報告、記錄檔或任何對外請求以外的地方。"] = "The key is stored only in %APPDATA%\\XinSpect\\settings.json and encrypted with Windows DPAPI. Only this user account on this PC can decrypt it; it will not work on another PC or account. XinSpect does not put the key in reports, logs or any other location.",
        ["韌體回報的溫度探針（SMBIOS Type 28）與冷卻裝置（Type 29）——與作業系統／驅動的感測器是兩套口徑，同一台機器上兩邊常常對不起來，這裡只陳列韌體那一套。"] = "Firmware-reported temperature probes (SMBIOS Type 28) and cooling devices (Type 29) are a separate source from OS/driver sensors and often disagree on the same PC. This page shows firmware data only.",
        ["沒有可辨識的 ATX 電壓軌（+12V／+5V／+3.3V）——主機板沒有以軌名回報電壓，本頁不猜測哪個感測器是哪一軌。"] = "No identifiable ATX voltage rails (+12 V/+5 V/+3.3 V) were reported. The motherboard does not label voltages by rail, and this page does not guess which sensor belongs to which rail.",
        ["AI 協力貢獻表"] = "AI Contribution Rankings",
        ["核心存取後端"] = "Kernel access backends",
        ["自動與僅沙箱可使用已安裝且通過試讀的 PawnIO，不會由此路由載入 WinRing0。"] = "Automatic and sandbox-only modes can use an installed PawnIO that passes the read check. This route does not load WinRing0 in either mode.",
        ["路由模式"] = "Routing mode",
        ["自動（使用已接入的沙箱／原生後端；不載入 WinRing0）"] = "Automatic (use connected sandbox/native backends; do not load WinRing0)",
        ["僅沙箱（只使用通過試讀的沙箱後端）"] = "Sandbox only (use sandbox backends that pass the read check)",
        ["允許 WinRing0（明確同意較廣的核心存取暴露面，才會載入）"] = "Allow WinRing0 (explicitly permit its broader kernel-access exposure before it is loaded)",
        ["PawnIO 共用路由目前在 Windows x64 Intel 平台提供白名單 MSR 讀取。LibreHardwareMonitor 感測器、WMI、XsRegProbe 與其他直連功能各有自己的讀取路徑。"] = "The shared PawnIO route provides allowlisted MSR reads on Intel Windows x64. LibreHardwareMonitor sensors, WMI, XsRegProbe, and other direct features use separate paths.",
        ["供應商名次（依指定排序）"] = "Provider rankings (specified order)",
        ["查看具體型號名次"] = "View model rankings",
        ["據作者統計所排名"] = "Rankings based on the author’s statistics",
        ["目前沒有按供應商與型號彙總的歷史 Token 數據。名次依指定順序排列，不代表消耗量或比例。"] = "No historical token totals are grouped by provider and model yet. The rankings follow the specified order and do not represent usage amounts or proportions.",

        // ── Source-audited visible UI coverage (2026-11-28) ──
        [" 項檢查"] = " checks",
        ["01 // CPU 溫度"] = "01 // CPU Temperature",
        ["01.A / CPU 溫度"] = "01.A / CPU Temperature",
        ["01.B / CPU 負載"] = "01.B / CPU Load",
        ["01.C / GPU 溫度"] = "01.C / GPU Temperature",
        ["01.D / GPU 負載"] = "01.D / GPU Load",
        ["02 // CPU 負載"] = "02 // CPU Load",
        ["03 // GPU 溫度"] = "03 // GPU Temperature",
        ["04 // 記憶體"] = "04 // Memory",
        ["0–604800 秒；恢復後再次超限才觸發新事件，冷卻只抑制通知。"] = "0–604800 seconds; a new event requires recovery followed by another threshold crossing. Cooldown suppresses notifications only.",
        ["0–86400 秒；連續有效採樣才累積，缺讀後重新計時。"] = "0–86400 seconds; only consecutive valid samples accumulate time. A missing reading restarts the timer.",
        ["2 對"] = "2 pairs",
        ["4 對"] = "4 pairs",
        ["8 組 0x606／0x611、約 3.5 秒；固定 group／LP，以 QPC 差分。估值一律未驗證，不更新任何功耗信任或分析輸入；原低瓦數原因仍待證據。"] = "Eight sets of 0x606/0x611 readings over about 3.5 seconds, pinned to one group/LP, with QPC differences. All estimates remain unverified and do not update power trust or analysis inputs. The original low-power reading still requires evidence.",
        ["CPU 封裝功耗原始證據"] = "Raw CPU package power evidence",
        ["CPU 封裝功耗被動診斷"] = "Passive CPU package power diagnostics",
        ["Driver Store 備份／匯出"] = "Driver Store backup/export",
        ["Driver Store 套件清單"] = "Driver Store package list",
        ["Driver Store 套件盤點與備份"] = "Driver Store Inventory and Backup",
        ["GPT-3 時代，我的程式能力還很青澀，寫出來的程式碼常被人嘲笑。\n那時我暗暗發誓：總有一天，我要成為真正的天才程式設計師。\n時過境遷，我的水準突飛猛進。曾經困擾我好幾天的問題，如今片刻就能解決；從前想都不敢想的對案，現在也能信手拏來。\n偶爾我也會懷疑：今天的成就，是不是借助了太多外力？\n今天，我回顧來時的路：\n從 GPT-3、GPT-4，\n到 GPT-5.3-Codex、Claude Opus 4.6，\n再到 GPT-5.6-Sol、Claude Opus 5，\n直到如今的 GPT-6-Astra、Claude Fable 5.1。\n模型換了一代又一代，Agent 也換了一套又一套，而我的實力始終穩步上升。\n想到這裡，我終於釋然：\n工具一直在換，不變的是我。\n原來，我早就是天才工程師了(壞笑)"] = "Back in the GPT-3 era, my programming skills were still rough, and people often laughed at my code.\nI quietly vowed that one day I would become a truly brilliant programmer.\nTime passed, and my skills improved dramatically. Problems that once took days now take moments; solutions I once could not imagine now come naturally.\nSometimes I wondered: did I owe too much of this success to outside help?\nToday, I look back at the journey:\nfrom GPT-3 and GPT-4,\nto GPT-5.3-Codex and Claude Opus 4.6,\nthen GPT-5.6-Sol and Claude Opus 5,\nand now GPT-6-Astra and Claude Fable 5.1.\nModels changed generation after generation, and agents came and went, while my abilities kept steadily improving.\nAt last, I understood:\nthe tools kept changing, but I was the constant.\nIt turns out I was a brilliant engineer all along. (Grin)",
        ["INDEX // 模組 01—05"] = "INDEX // Modules 01–05",
        ["MSR 索引（十六進位，例如 0x19C）"] = "MSR index (hexadecimal, e.g. 0x19C)",
        ["NVMe 磁碟"] = "NVMe drives",
        ["NVR 接入能力（Mbps）"] = "NVR input capacity (Mbps)",
        ["NVR、頻寬、PoE、光纖、RAID、無線與 UPS 設計試算；輸入由你提供，結果是公式推導，不是本機量測。"] = "Design calculations for NVR storage, bandwidth, PoE, fiber, RAID, wireless and UPS. You supply the inputs; results are calculated, not measured on this PC.",
        ["PSE 供電（V）"] = "PSE supply voltage (V)",
        ["PoE 埠數"] = "PoE port count",
        ["RAID 等級"] = "RAID level",
        ["RDMSR 讀取（唯讀）"] = "Read MSR (RDMSR, read-only)",
        ["RX 靈敏度（dBm）"] = "RX sensitivity (dBm)",
        ["Raw Input 到達間隔"] = "Raw Input Arrival Intervals",
        ["TX 功率（dBm）"] = "TX power (dBm)",
        ["UEFI 韌體磁碟區（FV/FFS 結構）"] = "UEFI firmware volumes (FV/FFS structure)",
        ["Windows SMBIOS/WMI 回報；不是 SPD 晶片直讀。"] = "Reported by Windows SMBIOS/WMI; not a direct SPD-chip reading.",
        ["Windows 設定資料速率與 CPU-Z 報告時脈分開保留；Uncore 不跨平台改名為 UCLK，也不以時脈倍率猜分頻模式。"] = "Windows configured data rate and CPU-Z reported clocks are kept separate. Uncore is not renamed UCLK across platforms, and divider modes are not guessed from clock ratios.",
        ["_匯出 JSON"] = "_Export JSON",
        ["_匯出勾選套件"] = "_Export selected packages",
        ["_取消"] = "_Cancel",
        ["_取消作業"] = "_Cancel operation",
        ["_選擇資料夾"] = "_Select folder",
        ["_重新盤點"] = "_Refresh inventory",
        ["_開始被動取樣"] = "_Start passive sampling",
        ["hex dump 是選中裝置 0x00–0xFF 的設定空間現值；MSR 是指定核心索引的一次 RDMSR。兩者都只讀不寫。"] = "The hex dump shows the selected device's current 0x00–0xFF configuration space. MSR performs one RDMSR at the specified core/index. Both operations are read-only.",
        ["x1 理論單方向 (MB/s)"] = "x1 theoretical one-way bandwidth (MB/s)",
        ["　・ 使用中 "] = " · In use ",
        ["　信賴度 "] = " Trust ",
        ["　範圍 "] = " Scope ",
        ["「本次未收集」說的是這一輪沒有跑到那條路徑（需要驅動、需要提權、或要使用者按下量測），不是那把鍵不存在。這張表刻意不猜是哪一種。"] = "“Not collected this run” means the path was not run this time, possibly because it requires a driver, elevation or a manual measurement. It does not mean the key is missing; this table does not guess the cause.",
        ["上"] = "Up",
        ["上層"] = "Parent",
        ["上行  "] = "Upload  ",
        ["上行每埠（Gbps）"] = "Uplink speed per port (Gbps)",
        ["上行線速（Gbps）"] = "Uplink line rate (Gbps)",
        ["上限"] = "Upper limit",
        ["上限（大於或等於）"] = "Upper limit (greater than or equal to)",
        ["下"] = "Down",
        ["下行  "] = "Download  ",
        ["下限"] = "Lower limit",
        ["下限（小於或等於）"] = "Lower limit (less than or equal to)",
        ["不喜歡 XinSpect-Desktop 嗎？那歡迎試試 XinSpect-CLI。"] = "Prefer another way to use XinSpect? Try XinSpect-CLI.",
        ["中位間隔 — · P95 — · 抖動 MAD —"] = "Median interval — · P95 — · Jitter MAD —",
        ["事件"] = "Event",
        ["交換機 PoE 預算（W）"] = "Switch PoE budget (W)",
        ["以下是 BIOS 標成「PCI Express x4」的插槽：M.2 NVMe 通常是 x4，但 BIOS 沒寫它是 M.2。列在這裡是推測，不是量測結果。"] = "These slots are labeled “PCI Express x4” by BIOS. M.2 NVMe commonly uses x4, but BIOS did not identify them as M.2. This is an inference, not a measurement.",
        ["以瀏覽器開啟 XinSpect 最新 Release，選擇 CLI 資產下載"] = "Open the latest XinSpect release in your browser and choose a CLI download",
        ["企業簽章政策 · 已存快照"] = "Enterprise signature policy · Saved snapshot",
        ["位置／範圍"] = "Location/scope",
        ["來源欄位與時間"] = "Source fields and timestamps",
        ["來源身份"] = "Source identity",
        ["來源：DismGetDrivers(AllDrivers=true)；綁定：Win32_PnPSignedDriver。DISM 僅驗證開機關鍵驅動的簽章，其餘可能為未知；日期是廠商宣告日期。"] = "Source: DismGetDrivers(AllDrivers=true); bindings: Win32_PnPSignedDriver. DISM verifies signatures only for boot-critical drivers; other signatures may be unknown. Dates are vendor-declared.",
        ["來源：WM_INPUT／GetRawInputData；QPC 在接收端記時。只計相對移動報告，排除大於 200 ms 的停頓；P95 使用最近秩，抖動為間隔的中位絕對偏差（MAD）。至少需 20 筆有效間隔。"] = "Source: WM_INPUT/GetRawInputData; QPC timestamps receipt. Counts relative-motion reports only and excludes pauses over 200 ms. P95 uses nearest rank; jitter is the median absolute deviation (MAD) of intervals. At least 20 valid intervals are required.",
        ["例：ptt.cc/bbs/index.html 或 https://www.chiphell.com/"] = "Example: ptt.cc/bbs/index.html or https://www.chiphell.com/",
        ["依序選擇組織預先部署公鑰、簽章政策與已存快照。公鑰信任來源請依組織通道另行核對；不從待驗政策建立信任。"] = "Select the organization's predeployed public key, signature policy and saved snapshot in order. Verify the key's trust through your organization's channels; the policy being verified cannot establish that trust.",
        ["依感測器穩定 ID 與原始單位判定上下限。沿用設定頁的「啟用警示」總開關；通知僅在本機，不自動要求 AI。"] = "Evaluate upper/lower thresholds using stable sensor IDs and original units. Uses the “Enable alerts” master switch in Settings. Notifications stay local and do not automatically request AI assistance.",
        ["保留 U 數"] = "Reserved rack units",
        ["保留中繼資料估算預算 MiB，1 到 512"] = "Estimated retained-metadata budget in MiB, 1–512",
        ["保留模型採保守成本估算；不包含 CLR、原生 I/O 與 UI 暫時配置，因此不是 process/CLR heap 的硬上限。"] = "The retained model uses conservative cost estimates. It excludes temporary CLR, native I/O and UI allocations, so this is not a hard process/CLR-heap limit.",
        ["假設：錄影量以十進位 GB／TB 計（與硬碟標示同一單位）；光纖接頭 0.5 dB、熔接 0.15 dB 取最壞情況；PoE 壓降以定功率負載解二次式，線材電阻用 20 °C 銅導體；背板與包轉發以 64 bytes 最小訊框計算。這些是工程慣例，不是量測值——驗收前仍要實測。"] = "Assumptions: video storage uses decimal GB/TB, matching drive labels. Worst-case fiber losses are 0.5 dB per connector and 0.15 dB per splice. PoE voltage drop solves a constant-power quadratic using copper resistance at 20 °C. Switch fabric and forwarding use minimum 64-byte frames. These are engineering conventions, not measurements; verify on site before acceptance.",
        ["備份"] = "Backup",
        ["備份目的地"] = "Backup destination",
        ["備份目的地（_D）"] = "Backup destination (_D)",
        ["僅掃描本機固定卷，唯讀緩衝 I/O；每種塊尺最多 64 MiB。可選同範圍重讀，速度差不推算快取容量。慢區門檻 100 ms。"] = "Scans local fixed volumes only using read-only buffered I/O, up to 64 MiB per block size. Optional rereads cover the same range; speed differences do not establish cache capacity. Slow-region threshold: 100 ms.",
        ["儀表"] = "Gauge",
        ["儀表／歷史圖刻度（原始單位）"] = "Gauge/history scale (original units)",
        ["儲存本機版面"] = "Save local layout",
        ["儲存規則 (_V)"] = "Save rule (_V)",
        ["允許 AI 主動呼叫本機唯讀查詢工具（溫度、事件、磁碟健康、歷史統計等）。代理會逐輪送出工具查詢結果，每一輪實際送出的內容都會記在對話列表（標「✓ 已送出」）。免費共用額度的中轉不轉送工具，這條額度上代理不生效。"] = "Allow AI to call local read-only tools for temperatures, events, drive health and historical statistics. Each agent turn sends tool results, and the actual content sent is recorded in the conversation as “✓ Sent”. The free shared-quota relay does not forward tools, so agent mode is unavailable with that quota.",
        ["先選取一個磁貼"] = "Select a tile first",
        ["光纜長度（km）"] = "Fiber length (km)",
        ["全部塊尺"] = "All block sizes",
        ["冷卻秒數 (_C)"] = "Cooldown seconds (_C)",
        ["分析目錄完整路徑"] = "Full directory path to analyze",
        ["列出 Windows Driver Store 的套件，另列 WMI 回報的裝置綁定。未回報綁定不代表套件可刪除；本視窗只提供盤點與匯出備份。"] = "List Windows Driver Store packages alongside WMI-reported device bindings. No reported binding does not mean a package is safe to delete. This window provides inventory and backup export only.",
        ["列出所有已公布感測器；未知項目可設定，取得可採信的新讀值前不判定。"] = "Lists all published sensors. Unknown sensors can be configured, but evaluation waits for a new trustworthy reading.",
        ["判定方向 (_D)"] = "Direction (_D)",
        ["刪除規則 (_X)"] = "Delete rule (_X)",
        ["刻度上限"] = "Scale maximum",
        ["刻度下限"] = "Scale minimum",
        ["前往最新 Release 下載 CLI"] = "Download CLI from the latest release",
        ["前景取樣，最長 10 秒；持續移動同一隻滑鼠。"] = "Foreground sampling for up to 10 seconds; keep moving the same mouse.",
        ["副檔名"] = "Extension",
        ["加入所選感測器"] = "Add selected sensor",
        ["勾選任意裝置的項目再開始 CSV；本次記錄欄位固定，變更選取在下次記錄生效。來源內部更新時間未知不代表獨立驗證；未確認數值不納入統計、告警或圖表。"] = "Select readings from any device before starting CSV logging. Columns remain fixed for this session; selection changes apply next time. An unknown source-update time does not provide independent verification. Unconfirmed values are excluded from statistics, alerts and charts.",
        ["勾選可見的第三方套件"] = "Select visible third-party packages",
        ["勾選此套件作為備份對象；Windows 隨附套件不可匯出"] = "Select this package for backup; Windows inbox packages cannot be exported",
        ["匯入 JSON…"] = "Import JSON…",
        ["匯出 JSON…"] = "Export JSON…",
        ["匯出本機 JSON 報告…"] = "Export local JSON report…",
        ["協商理論頻寬"] = "Negotiated theoretical bandwidth",
        ["原因類別"] = "Reason category",
        ["原因／來源"] = "Reason/source",
        ["取樣後顯示原始計數、單位、QPC 前後時間、來源及限制。資料只在按匯出後寫入您選擇的本機 JSON 檔案。"] = "After sampling, displays raw counts, units, QPC start/end timestamps, sources and limitations. Data is written only when you export it to a local JSON file you choose.",
        ["取樣窗 —"] = "Sampling window —",
        ["取樣裝置（各自分組）"] = "Sampling device (grouped separately)",
        ["取消與時間預算在檔案系統呼叫之間檢查；正在等待的 I/O 無法強制中止。重解析點略過，權限與錯誤列在「略過與限制」。部分結果只代表已讀到的範圍。"] = "Cancellation and time budgets are checked between filesystem calls; pending I/O cannot be forcibly interrupted. Reparse points are skipped; access and read errors appear under “Skipped items and limitations”. Partial results cover only the portion actually read.",
        ["只借用已開啟的讀取通道；不啟動負載、不載入／重裝驅動、不更改防護或開關。不支援或通道未開啟時如實停止。"] = "Borrows an already-open read channel only. Does not start a workload, load/reinstall drivers or change protections or switches. Stops honestly if unsupported or no channel is open.",
        ["只採用 Present 且非 Unknown／Speculative 的有限讀值。缺讀、超過 30 秒或單位改變皆為未知；不推定恢復。來源自述不等於校準。"] = "Uses finite Present readings only, excluding Unknown/Speculative data. Missing readings, data older than 30 seconds or changed units are unknown; recovery is not assumed. Source reports do not establish calibration.",
        ["只接受 http／https 網址；其他內容（含 file:、javascript:）一律視為未設定、回到內建頁——不會留下一個每次啟動都打不開的首頁。"] = "Only http/https URLs are accepted. Other content, including file: and javascript:, is treated as unset and returns to the built-in page, avoiding a home page that fails on every start.",
        ["只顯示計數，不列控制識別碼或事實值。政策簽章不證明裝置來源；快照與本次結果未簽章、未做遠端證明。只評估所選已存快照，不重新採集，也不代表目前硬體安全。"] = "Shows counts only, without control identifiers or fact values. A policy signature does not prove device provenance; snapshots and results are unsigned and have no remote attestation. Evaluates only the selected saved snapshot without recollecting data or asserting current hardware security.",
        ["可用感測器，包含各張顯示卡與磁碟"] = "Available sensors, including all GPUs and drives",
        ["右"] = "Right",
        ["名稱 (_N)"] = "Name (_N)",
        ["唯一配置貢獻"] = "Unique allocated contribution",
        ["唯讀讀回 BIOS 區、依 UEFI PI 規格解析 FV → FFS 檔案 → 區段的頂層樹（GUID／型別／大小）。結構存在與否不構成對韌體真偽的判決；壓縮區段只列出不解壓，表頭校驗和不符合規格的檔案如實計數，不拒收也不掩蓋。"] = "Reads the BIOS region and parses the top-level FV → FFS file → section tree (GUID/type/size) under the UEFI PI specification. Structural presence does not establish firmware authenticity. Compressed sections are listed without decompression. Nonconforming header checksums are counted without rejecting or hiding the files.",
        ["啟用此規則 (_E)"] = "Enable this rule (_E)",
        ["啟用／停用 (_G)"] = "Enable/disable (_G)",
        ["喚醒／隱藏迷你浮動監視器；小窗被關掉後可從這裡重新喚醒"] = "Show or hide the mini floating monitor; reopen it here after closing the window",
        ["單碟容量（TB）"] = "Capacity per drive (TB)",
        ["喵！先確認一下"] = "Meow! Please confirm",
        ["域"] = "Domain",
        ["套件來源"] = "Package origin",
        ["套用刻度"] = "Apply scale",
        ["存成 Markdown：標頭會寫明時間、模型、供應商、這次有沒有遮蔽與遮蔽了幾處；圖片內容不會在檔案裡"] = "Save as Markdown. The header records time, model, provider and whether redaction was enabled and how many matches were redacted. Images are not included in the file.",
        ["宣告日期"] = "Declared date",
        ["封裝功率唯讀診斷"] = "Read-only package power diagnostics",
        ["對同一範圍再讀一次；速度差不代表快取容量。"] = "Reread the same range; a speed difference does not establish cache capacity.",
        ["尚未取樣；開啟此視窗不讀硬體。"] = "No samples yet; opening this window does not read hardware.",
        ["尚未安裝 Intel XTU 引擎？請先下載並安裝 "] = "Intel XTU engine not installed? Download and install ",
        ["尚未掃描。可分析本機目錄或可存取的 UNC 共用；遠端或離線裝置可能較慢。"] = "No scan yet. Analyze a local directory or accessible UNC share. Remote or offline devices may be slower.",
        ["尚未盤點。"] = "Inventory not loaded.",
        ["尚未開始；請按開始取樣。"] = "Not started; select Start sampling.",
        ["尚無結果。清單最多保留 2,000 條，總數另列；未遍歷的項目數無法推算。"] = "No results yet. The list retains up to 2,000 entries; the total is shown separately. The number of unvisited items cannot be inferred.",
        ["左"] = "Left",
        ["差值"] = "Difference",
        ["已發佈 INF"] = "Published INF",
        ["已確認唯一配置"] = "Confirmed unique allocation",
        ["平台靶向套件"] = "Platform-targeted suite",
        ["平均長度（m）"] = "Average length (m)",
        ["從左側選取感測器，建立自己的面板。"] = "Choose sensors on the left to build your panel.",
        ["微星 Afterburner（OSD）"] = "MSI Afterburner (OSD)",
        ["恢復閾值 (_R)"] = "Recovery threshold (_R)",
        ["感測器 (_S)"] = "Sensor (_S)",
        ["感測器目前、最小、最大與平均值及來源"] = "Sensor current, minimum, maximum and average readings with sources",
        ["感測器警示規則與狀態"] = "Sensor alert rules and states",
        ["我已了解風險（固定計數器使能位寫入可能影響其他工具；需嘗試還原並核對），明確同意執行"] = "I understand the risks (writing fixed-counter enable bits may affect other tools; restoration must be attempted and verified) and explicitly consent to run",
        ["所選公鑰 SHA-256 指紋"] = "Selected public-key SHA-256 fingerprint",
        ["把上一則提問再送一次（附件沿用同一份）。只在失敗、被停止或模型沒有回覆時出現——正常回答旁邊不給重試鍵。"] = "Resend the previous question with the same attachments. Available only after failure, cancellation or no model reply; successful replies do not show Retry.",
        ["把既有感測服務與歷史倉已經量到的數字攤成一頁監看版：逐核溫度隨時間的熱區、電壓軌對 ATX 規格帶、溫度的統計控制圖、異常事件的逐日日曆。本頁不做任何新的讀取——它看的全部是其他頁面已經在收集的資料，收起來時不占任何取樣成本。"] = "Monitor values already collected by the sensor service and history store: per-core temperature heatmaps, voltage rails against ATX specification bands, statistical temperature control charts and a daily anomaly calendar. This page performs no additional reads and has no sampling cost while hidden.",
        ["把這台電腦的硬體事實交給 AI，請它寫一段評價（共用額度、本機 Ollama 或自填端點都可以）"] = "Ask AI to review this PC's hardware facts using the shared quota, local Ollama or your own endpoint",
        ["把這台電腦的硬體事實交給 AI，請它寫一段評價；按下後會跳到 AI 分頁顯示結果"] = "Ask AI to review this PC's hardware facts; opens the AI tab to show the result",
        ["拆分證據"] = "Separate evidence",
        ["拖曳磁貼標頭移動，拖右下角縮放。聚焦標頭後方向鍵移動，Shift＋方向鍵縮放。"] = "Drag tile headers to move and the lower-right corner to resize. With a header focused, use arrow keys to move or Shift+arrow keys to resize.",
        ["持續秒數 (_U)"] = "Duration seconds (_U)",
        ["按「重新盤點」讀取；不會自動匯出套件。"] = "Select Refresh inventory to read packages; nothing is exported automatically.",
        ["按下開始才取樣：僅 Intel family 6/model 0x55、裸機、Windows 單一實體封裝。須先開啟既有第一級進階診斷，並已有共用 MSR 通道。"] = "Sampling starts only on request: Intel family 6/model 0x55, bare metal, and one Windows physical package only. Requires Level 1 advanced diagnostics and an already-open shared MSR channel.",
        ["按瀏覽器工具列的「首頁」時去哪裡。留空＝內建的離線「硬體導航」頁（常用檢測工具、跑分、驅動、論壇與科技媒體連結）。"] = "Destination for the browser toolbar's Home button. Leave blank for the built-in offline Hardware Navigation page with testing, benchmark, driver, forum and technology-media links.",
        ["掃描後點選目錄檢視子項目。"] = "After scanning, select a directory to view its children.",
        ["接了線的真實螢幕（有 EDID：製造商、型號、製造年週）、軟體虛擬螢幕（驅動合成的最小 EDID）與作業系統的預設監視器物件（後面沒有實體裝置）在 Windows 裡長得很像，設定畫面都顯示成一台螢幕。這一區用 EDID 支撐與實體 PNP 路徑把三者分開。"] = "Physical displays with real EDID (manufacturer, model and manufacturing week/year), software displays with a minimal driver-generated EDID, and default Windows monitor objects without physical devices can look alike in Windows Settings. This section distinguishes them using EDID evidence and physical PNP paths.",
        ["提示：內建瀏覽器只開 http／https，且不會略過 TLS 憑證警告。"] = "Tip: the built-in browser opens http/https only and never bypasses TLS certificate warnings.",
        ["搜尋 Driver Store 套件"] = "Search Driver Store packages",
        ["搜尋 INF、提供者、類別或版本（_F）"] = "Search INF, provider, class or version (_F)",
        ["搜尋感測器"] = "Search sensors",
        ["搜尋裝置、名稱或識別碼"] = "Search device, name or identifier",
        ["攝影機最低電壓（V）"] = "Camera minimum voltage (V)",
        ["攝影機耗電（W）"] = "Camera power (W)",
        ["放大"] = "Enlarge",
        ["放大（Ctrl＋滾輪亦可；範圍 50%–200%）"] = "Zoom in (also Ctrl+wheel; range 50%–200%)",
        ["整包送出內容（系統提示＋硬體快照＋對話）的字元上限。超過時先截斷單則過長訊息、再由最舊的整則丟棄，最後一則提問永遠保留；丟了什麼會寫進系統提示告訴模型，不會讓它以為看到全部。只按「則數」控管擋不住一則貼上的長檔案——那種情況端點會直接回 400，而畫面只會顯示「呼叫失敗」。"] = "Maximum characters in the entire request: system prompt, hardware snapshot and conversation. Overlong messages are truncated first, then the oldest whole messages are removed; the latest question is always retained. The system prompt tells the model what was removed. A message-count limit alone cannot contain a large pasted file, which could otherwise cause an HTTP 400 call failure.",
        ["數字"] = "Number",
        ["新增感測磁貼"] = "Add sensor tile",
        ["新增或編輯規則"] = "Add or edit rule",
        ["新增磁貼的顯示方式"] = "Display type for a new tile",
        ["新增規則 (_A)"] = "New rule (_A)",
        ["族內位置 "] = "Family position ",
        ["日文／韓文翻譯未完成"] = "Japanese/Korean translation is incomplete",
        ["時間預算秒數，1 到 600"] = "Time budget in seconds, 1–600",
        ["時間預算（秒）"] = "Time budget (seconds)",
        ["曦覽 XinSpect"] = "XinSpect",
        ["曦覽 · 磁碟空間分析"] = "XinSpect · Disk Space Analysis",
        ["曦覽 — 自訂感測面板"] = "XinSpect — Custom Sensor Panel",
        ["曦覽 強控台 Power Console"] = "XinSpect Power Console",
        ["曦覽（XinSpect）"] = "XinSpect",
        ["曦覽＝沿用主題色與一般字型；Afterburner（OSD）＝黑底、等寬數字、紅色邊框的密集排版（RTSS 那種）。要增減顯示的項目，點監視器標題列的齒輪：預設全部開啟，關掉就少一行。"] = "XinSpect uses the theme colors and normal font. Afterburner (OSD) uses a dense black layout with monospaced numbers and a red border, like RTSS. Change visible items with the gear in the monitor title bar; all are enabled by default, and disabling an item removes its row.",
        ["最多項目"] = "Maximum items",
        ["最多項目，1 到 1000000"] = "Maximum items, 1–1000000",
        ["最大檔案（最多 500）"] = "Largest files (up to 500)",
        ["有效樣本"] = "Valid samples",
        ["有效間隔 0 筆 · 原始報告 0 筆"] = "Valid intervals: 0 · Raw reports: 0",
        ["未執行。本版原生編程未支援：核心釘選、計數器所有權與寫回能力尚未驗證。"] = "Not run. Native programming is unsupported in this version: core pinning, counter ownership and write-back capability have not been verified.",
        ["本模組偵測已知攻擊痕跡與平台安全設定的事實狀態。不保證偵測所有威脅。讀不到的項目標為「無法評估」而非危險。所有檢查為唯讀——不修改任何系統設定。目前為 Phase 1 偵測模式：所有防線實際執行的只有「偵測與記錄」，「阻擋」模式尚未實施（需要 Phase 2 的核心執行路徑）——即使透過 Bridge 指令把防線設為 block，也不會有任何活動被阻止，狀態列與 status 回應會如實標示 implemented:false。評分公式公開透明：每一分的扣除都可在防線展開卡片中追溯到具體的檢查項目與原始值。"] = "This module detects known attack traces and platform-security facts. It does not guarantee detection of every threat. Unavailable checks are marked “Cannot evaluate”, rather than dangerous. All checks are read-only and do not change system settings. Phase 1 performs detection and logging only. Blocking requires the Phase 2 kernel execution path and is not implemented; setting a defense to block through Bridge does not stop activity. The status bar and status response report implemented:false. The scoring formula is public; each deduction can be traced in the expanded defense card to the specific check and raw value.",
        ["本機時間"] = "Local time",
        ["本機獨立規則檔；最多 256 條。歷程僅保留本次執行最新 200 筆。"] = "Separate local rule file; up to 256 rules. History retains the latest 200 entries from this run only.",
        ["本次執行歷程"] = "History for this run",
        ["核心 #{0}"] = "Core #{0}",
        ["根目錄深度為 0；各項上限先到先停。"] = "Root depth is 0; scanning stops at the first budget reached.",
        ["案場面積（m²）"] = "Site area (m²)",
        ["條件"] = "Condition",
        ["標示包轉發（Mpps，0＝未填）"] = "Rated forwarding (Mpps; 0 = not specified)",
        ["標示背板（Gbps，0＝未填）"] = "Rated switch fabric (Gbps; 0 = not specified)",
        ["標稱 "] = "Nominal ",
        ["標註只說「那個時間點發生了這種事件」（WHEA、TDR、非預期關機、藍屏四類），不建立因果——非預期關機也可能是停電、電源或驅動；事件讀不到會如實標示，不畫成 0 筆。"] = "Annotations record that an event occurred at a given time (WHEA, TDR, unexpected shutdown or blue screen), without establishing causality. Unexpected shutdowns can also involve power loss, the PSU or drivers. Unavailable event logs are reported honestly, not plotted as zero events.",
        ["模型估算（MiB）"] = "Model estimate (MiB)",
        ["機櫃總 U 數"] = "Total rack units",
        ["機箱（SMBIOS Type 3）"] = "Chassis (SMBIOS Type 3)",
        ["檔名數"] = "File-name count",
        ["檔案路徑"] = "File path",
        ["檔案類型"] = "File type",
        ["此值是 OS 報告到達間隔的中位數倒數，不是實體 USB 輪詢頻率、端到端延遲或精度認證。排程／佇列／合併與遠端／虛擬通路都會影響結果；125–8000 Hz 只是常見檔位比對。裝置 ID 為本機介面路徑雜湊，不顯示原始路徑。"] = "This is the reciprocal of the median OS-report arrival interval, not the physical USB polling rate, end-to-end latency or an accuracy certification. Scheduling, queues, coalescing and remote/virtual paths affect results. 125–8000 Hz values are common reference tiers only. Device IDs are hashes of local interface paths; raw paths are not displayed.",
        ["歷史倉最近 6 小時（分鐘級）"] = "Last 6 hours in history (minute resolution)",
        ["歷史折線"] = "History line",
        ["每台 AP 吞吐是設計值：2.4 GHz 20 MHz 約 70 Mbps、5 GHz 80 MHz 約 400 Mbps、6 GHz 160 MHz 約 800 Mbps。這是估算，不是現場量測。"] = "Per-AP throughput is a design estimate: about 70 Mbps at 2.4 GHz/20 MHz, 400 Mbps at 5 GHz/80 MHz and 800 Mbps at 6 GHz/160 MHz. These are estimates, not on-site measurements.",
        ["每台 AP 吞吐（Mbps）"] = "Throughput per AP (Mbps)",
        ["每埠線速（Gbps）"] = "Line rate per port (Gbps)",
        ["每支碼率（Mbps）"] = "Bitrate per stream (Mbps)",
        ["每機耗電（W）"] = "Power per device (W)",
        ["每箱長度（m）"] = "Length per box (m)",
        ["每組顆數（RAID 50/60）"] = "Drives per group (RAID 50/60)",
        ["每路兩端預留（m）"] = "Allowance at both ends per run (m)",
        ["永遠置頂"] = "Always on top",
        ["深度"] = "Depth",
        ["清除全部勾選"] = "Clear all selections",
        ["清除選取"] = "Clear selection",
        ["版本 3.33 ・ ULTIMA XXXIII ・ 便攜單一執行檔"] = "Version 3.33 · ULTIMA XXXIII · Portable single-file executable",
        ["版本 3.34 ・ ULTIMA XXXIV ・ 便攜單一執行檔"] = "Version 3.34 · ULTIMA XXXIV · Portable single-file executable",
        ["獨立桌面視窗 · 不會注入遊戲"] = "Separate desktop window · No game injection",
        ["現值 "] = "Current ",
        ["由人類和多個 AI 模型協力完成。"] = "Created by a human working with several AI models.",
        ["略過與限制"] = "Skipped items and limitations",
        ["目前控制器時脈與副時序"] = "Current controller clocks and secondary timings",
        ["目錄樹與空間圖"] = "Directory tree and space map",
        ["目錄深度上限，0 到 256"] = "Maximum directory depth, 0–256",
        ["看看這次送出（第一輪）到底包含哪些內容（遮蔽與長度裁切都已經套用）。代理模式的逐輪工具結果不在此份裡，但每輪實際送出的內容會即時記在對話列表（標「✓ 已送出」）"] = "Inspect the actual first-turn request after redaction and length limits. Later agent tool results are not included in this view; each turn's actual transmitted content appears in the AI conversation as “✓ Sent”.",
        ["矩形面積對應已讀位元組；點選目錄矩形可深入。零大小與未讀項目不佔面積。"] = "Rectangle area represents bytes actually read. Select a directory rectangle to explore it. Zero-size and unread items occupy no area.",
        ["硬連結重複"] = "Duplicate hard link",
        ["磁碟空間分析"] = "Disk Space Analysis",
        ["磁貼向上"] = "Move tile up",
        ["磁貼向下"] = "Move tile down",
        ["磁貼向右"] = "Move tile right",
        ["磁貼向左"] = "Move tile left",
        ["移動偵測只錄一部分時間時，錄影比例填 0.3～0.5，不要用 24 小時全錄去估。"] = "If motion detection records only part of the time, use a recording fraction of 0.3–0.5 instead of estimating continuous 24-hour recording.",
        ["移動畫軌跡　按鍵／滾輪測試　Space：開始／停止取樣　C：全部重設　Esc：離開"] = "Move to draw a trail · Test buttons/wheel · Space: start/stop sampling · C: reset all · Esc: exit",
        ["移動磁貼（每次 16）"] = "Move tile (16 units per step)",
        ["移除此磁貼"] = "Remove this tile",
        ["空間分析"] = "Space analysis",
        ["空間圖面積基準"] = "Space-map area basis",
        ["簽章（DISM）"] = "Signature (DISM)",
        ["線長（m）"] = "Cable length (m)",
        ["編輯所選磁貼"] = "Edit selected tile",
        ["縮小"] = "Shrink",
        ["縮小（Ctrl＋滾輪亦可；範圍 50%–200%）"] = "Zoom out (also Ctrl+wheel; range 50%–200%)",
        ["總負載（W）"] = "Total load (W)",
        ["能力理論頻寬"] = "Capability theoretical bandwidth",
        ["自訂告警"] = "Custom alerts",
        ["自訂感測器警示"] = "Custom Sensor Alerts",
        ["自訂感測面板"] = "Custom Sensor Panel",
        ["自訂首頁網址（不必打 https://）"] = "Custom home-page URL (https:// is optional)",
        ["裝置 U 數"] = "Device rack units",
        ["裝置綁定回報"] = "Reported device bindings",
        ["覆蓋半徑（m）"] = "Coverage radius (m)",
        ["規則"] = "Rule",
        ["規則與狀態"] = "Rules and states",
        ["觸發閾值 (_T)"] = "Trigger threshold (_T)",
        ["記錄"] = "Log",
        ["設定 "] = "Configured ",
        ["讀不到的那幾列，原因寫在名稱欄後面（例如「平台不支援 …」）；那是這一輪的判定，不是推測。"] = "For unavailable rows, the name field includes the reason, such as “Platform unsupported”. This is the assessment for this run, not speculation.",
        ["貓咪插畫"] = "Cat illustration",
        ["路徑"] = "Path",
        ["輸入 help 看指令清單。↑↓ 切換節區或命令歷史、Ctrl+1–5 跳節區、Esc 關閉。"] = "Type help for commands. Use ↑↓ for sections or command history, Ctrl+1–5 to jump to a section, and Esc to close.",
        ["迷你 HUD"] = "Mini HUD",
        ["這一版實作的每一把事實鍵都在這裡，連同它這一輪的狀態（讀到／平台不支援／權限不足／讀取失敗／本機不適用／未確認）。有些能力沒有專屬頁面、只在匯出檔裡看得到——那些在這裡照樣找得到，不必先知道它在哪一頁。鍵的清單是建置時固定的目錄，不是這次掃到什麼才列什麼。"] = "Every implemented fact key is listed here with its state for this run: present, unsupported, insufficient privilege, read error, not applicable or unconfirmed. Features without dedicated pages, including export-only facts, are still discoverable here. The catalog is fixed at build time rather than limited to what this run found.",
        ["這一群鍵的成員由機器決定（匯流排上有幾張卡、探到哪個埠），編譯期列不完，所以只登記「有哪些家族」與「成員由什麼決定」。它們不計入上面的目錄總數。"] = "Dynamic-family members depend on the machine, such as cards on the bus or detected ports, and cannot all be listed at compile time. The catalog records each family and what determines its members. They are excluded from the catalog total above.",
        ["這不是我的貓"] = "This is not my cat",
        ["這裡申報兩件「我們知道自己不知道什麼」的事：事實鍵有多少條被對帳規則考慮、以及手工知識表各收錄了幾條。兩者都不是錯誤，但都應該看得見——事實進了快照卻沒有規則看它，那個數字就永遠不會被交叉檢查；而查不到名字時顯示原始代碼，代表知識表沒收錄，不是裝置有問題。"] = "This section exposes two known coverage limits: how many fact keys are considered by reconciliation rules, and how many entries each manual knowledge table contains. A fact without a rule will not be cross-checked. A raw code displayed in place of a name means the knowledge table lacks that entry; it does not indicate a device fault.",
        ["選取全部記錄"] = "Select all for logging",
        ["選取套件明細"] = "Selected package details",
        ["選取套件的來源與裝置綁定"] = "Selected package sources and device bindings",
        ["選擇 Raw Input 裝置"] = "Choose Raw Input device",
        ["選擇一種讀取塊尺；每種最多讀取 64 MiB。"] = "Choose a read block size; each reads up to 64 MiB.",
        ["選擇公鑰、簽章政策與已存快照並評估"] = "Select a public key, signature policy and saved snapshot to evaluate",
        ["選擇檔案並評估"] = "Choose files and evaluate",
        ["選擇目錄…"] = "Choose directory…",
        ["選擇目錄後手動開始；唯讀列舉檔案中繼資料，不讀取內容。結果保留在本機記憶體，匯出時才寫入指定的報告。"] = "Choose a directory and start manually. Enumerates file metadata read-only without reading contents. Results stay in local memory; only an explicit export writes the specified report.",
        ["邏輯大小"] = "Logical size",
        ["邏輯大小（按檔名）"] = "Logical size (by file name)",
        ["配置未知檔案"] = "Files with unknown allocation",
        ["重新擷取最新資料（全機）"] = "Refresh latest data (whole system)",
        ["重設"] = "Reset",
        ["重設統計"] = "Reset statistics",
        ["重讀"] = "Reread",
        ["量端點延遲並取回模型清單；不會送出對話，所以不會產生 token 費用"] = "Measure endpoint latency and retrieve its model list. No conversation is sent, so no tokens are charged.",
        ["錄影比例（1＝全錄）"] = "Recording fraction (1 = continuous)",
        ["鍵"] = "Key",
        ["開啟下載資料夾（%LOCALAPPDATA%\\XinSpect\\Downloads）"] = "Open downloads folder (%LOCALAPPDATA%\\XinSpect\\Downloads)",
        ["開啟備份與匯出視窗；按盤點後才讀取，不會自動匯出"] = "Open the backup/export window. Reads only after inventory is requested; does not export automatically.",
        ["開啟封裝功率唯讀診斷；須開啟進階診斷並明確開始，不會自動擷取或施加負載"] = "Open read-only package power diagnostics. Requires advanced diagnostics and an explicit start; does not automatically collect data or apply load.",
        ["開啟後，AI 可自行呼叫 33 項唯讀查詢工具（完整規格、處理器拓樸、即時讀值、所有溫度、感測器總表、風扇與曲線、磁碟健康、事件紀錄、歷史統計、顯示卡與處理器調校現況、場景、健康總評、環境自檢、效能成績、記憶體時序與 SPD、網路組態與流量、螢幕 EDID 色域、升級建議、電池健康、開機啟動項、藍屏傾印，以及 11 項硬核底層事實：Top-down 管線歸因、頻率真相、平台可信度、BIOS 與 ME 微碼、逐核時間歸因、電源政策、記憶體認可帳本、機器檢查與 WHEA、處理器免疫位元、RDT 監測、效能天花板），並在對話中列出每次查詢。全部只讀不寫：不會改設定、不會動硬體、不會啟動任何程式，也不會自己去發動 PMU／MSR 量測——硬核項目你沒按過量測，AI 就只會說「本機尚未量測」。關閉則只送出一次硬體快照。代理會逐輪送出工具查詢結果，每一輪實際送出的內容（經遮蔽後的實文）都會記在 AI 分頁的對話列表（標「✓ 已送出」）；首次真的用代理送出前會說明一次。免費共用（Cloudflare Workers AI）額度的中轉不轉送工具定義，這條額度上代理不生效——不會假裝有代理。"] = "When enabled, AI can call 33 read-only tools and list each call in the conversation: specifications, CPU topology, live readings, temperatures, sensors, fans and curves, drive health, events, history, GPU/CPU tuning state, scenarios, overall health, environment checks, benchmarks, memory timings and SPD, network configuration and traffic, display EDID/gamut, upgrade advice, battery health, startup items, blue-screen dumps, and 11 low-level fact tools: top-down pipeline attribution, actual frequency, platform trust, BIOS/ME microcode, per-core time attribution, power policy, memory commit accounting, machine checks/WHEA, CPU immunity bits, RDT monitoring and performance ceilings. Tools never write settings or hardware, launch programs or initiate PMU/MSR measurement. If you have not run a measurement, AI receives “Not measured on this PC”. When disabled, only one hardware snapshot is sent. Every agent turn records its actual redacted tool results as “✓ Sent”; an explanation appears before first use. The free Cloudflare Workers AI relay does not forward tool definitions, so agent mode is unavailable with that quota.",
        ["開啟監控工程規劃器"] = "Open monitoring system planner",
        ["開啟磁碟空間分析；選擇目錄並按開始後才掃描"] = "Open disk space analysis; scans only after you choose a directory and select Start",
        ["開啟規劃器"] = "Open planner",
        ["開始 Raw Input 滑鼠取樣，最長十秒"] = "Start Raw Input mouse sampling for up to ten seconds",
        ["關閉時自動儲存本機版面。匯出只含版面與感測器身份，不含歷史讀數。"] = "Automatically saves the local layout on close. Export contains layout and sensor identities only, without historical readings.",
        ["關閉第一級進階診斷即停止後續讀取；取消會等目前同步 I/O 真正返回後釋放通道。計數解析度不是準確度；RAPL／LHM 可能共用來源。"] = "Turning off Level 1 advanced diagnostics stops subsequent reads. Cancellation waits for the current synchronous I/O to return before releasing the channel. Count resolution is not accuracy; RAPL and LHM may share a source.",
        ["離開滑鼠檢測（Esc）"] = "Exit mouse test (Esc)",
        ["電池容量（Wh）"] = "Battery capacity (Wh)",
        ["需系統管理員權限；由使用者選取本機目的地，再按匯出。每次建立全新子目錄與 manifest.json，含實際輸出檔案 SHA-256。備份尚未經還原驗證。"] = "Requires administrator privileges. Choose a local destination and select Export. Each run creates a new subdirectory and manifest.json with SHA-256 hashes of actual output files. Restore has not been verified.",
        ["頁內尋找（Ctrl＋F 亦可在網址列有焦點時用；頁面內按 Ctrl＋F 由 Chromium 自己處理）"] = "Find on page (Ctrl+F also works with the address bar focused; within a page, Chromium handles Ctrl+F)",
        ["預設開啟。代理模式（主動診斷）每一輪的工具查詢結果（序號、MAC、路徑等）在送 AI 前也過同一套遮蔽。關閉＝你明示同意讓代理模式原樣送出工具結果。"] = "Enabled by default. Each agent turn redacts identifiers such as serials, MAC addresses and paths in tool results before sending them to AI. Disabling this explicitly permits transmission of unredacted tool results.",
        ["預設開啟（與報告匯出相反：報告留給自己，AI 請求會離開這台電腦）。遮掉的是 UUID、MAC、標了標籤的 IP、C:\\Users\\使用者路徑、有標籤的序號與主機名稱；型號、容量、時脈、溫度、電壓等判斷需要的讀值一律不動。沒有標籤的 1.0.0.0 這種字串不遮——它多半是版本號，遮掉反而少一個線索。AI 分頁的「傳送內容」按鈕可以看到實際送出的全文。"] = "Enabled by default because AI requests leave this PC. Redacts UUIDs, MAC addresses, labeled IPs, user paths, labeled serial numbers and hostnames. Model, capacity, clock, temperature, voltage and other diagnostic readings stay intact. Unlabeled strings such as 1.0.0.0 are preserved because they may be version numbers. Use “Content to send” in the AI tab to inspect the actual request.",
        ["預設關閉。開啟後代理模式每一輪的工具結果在送出前顯示在對話裡，代理暫停等你按送出才繼續——讓你看清楚代理到底送了什麼。關閉＝代理連續執行不暫停（較快但你看不到中間過程）。"] = "Disabled by default. When enabled, each agent turn shows tool results in the conversation and pauses until you select Send. When disabled, the agent runs continuously without pausing, which is faster but hides intermediate content.",
        ["頻寬為非 FLIT 編碼模式下扣除線路編碼開銷的理論單方向速率；未扣除封包／協定開銷，不是實測或應用有效吞吐。Gen6 保留原始傳輸率，FLIT／FEC 頻寬尚未校核。"] = "Theoretical one-way bandwidth after line-coding overhead in non-FLIT mode. Packet/protocol overhead is not deducted; this is neither measured nor application throughput. Gen6 retains its raw transfer rate; FLIT/FEC bandwidth has not been validated.",
        ["顯示方式"] = "Display type",
        ["喵！"] = "Meow!",

