        ["圖片檔 (*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp)|*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp|文字檔 (*.txt;*.log;*.csv;*.json;*.xml;*.yaml;*.yml;*.md)|*.txt;*.log;*.csv;*.json;*.xml;*.yaml;*.yml;*.md|所有檔案 (*.*)|*.*"] = "Images (*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp)|*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp|Text files (*.txt;*.log;*.csv;*.json;*.xml;*.yaml;*.yml;*.md)|*.txt;*.log;*.csv;*.json;*.xml;*.yaml;*.yml;*.md|All files (*.*)|*.*",
        ["未附加「{0}」：不支援的檔案類型（支援圖片與文字檔）。"] = "Could not attach “{0}”: unsupported file type (images and text files are supported).",
