        ["讀取失敗：系統沒有回報電池資訊。"] = "Read failed: the system did not report battery information.",
        ["此機型未提供設計／滿充容量，無法計算耗損率。"] = "This model does not report design or full-charge capacity, so wear cannot be calculated.",
