        ["找不到「{0}」"] = "“{0}” was not found",
        ["找不到這個網域（DNS 查不到）。檢查網址是否拼錯，或這台機器目前的 DNS 是否正常。"] = "This domain could not be found (DNS lookup failed). Check the URL for typos and verify this PC’s DNS settings.",
        ["連不上伺服器（連線被拒絕或中斷）。網站可能暫時不可用，或本機網路／防火牆擋住了。"] = "Could not connect to the server (the connection was refused or interrupted). The website may be temporarily unavailable, or the local network or firewall may be blocking it.",
        ["連線逾時。網站沒有回應，稍後再試或檢查網路。"] = "The connection timed out. The website did not respond. Try again later or check the network.",
        ["網路已中斷。"] = "The network is disconnected.",
        ["無法建立連線（可能是 TLS／憑證問題，或網站拒絕了這個連線）。"] = "Could not establish a connection (there may be a TLS or certificate issue, or the website may have refused the connection).",
        ["網站的 TLS 憑證有問題（名稱不符、過期或已撤銷）。內建瀏覽器不會略過憑證警告。"] = "The website’s TLS certificate has a problem (name mismatch, expiration or revocation). The built-in browser does not bypass certificate warnings.",
