        ["還沒有驗機結果。請先把上面的下拉切到「驗機對帳」並按「重新擷取」,再匯出報告。"] = "No hardware verification results are available yet. Select Hardware Verification in the list above, click Refresh, then export the report.",
        ["純文字報告 (*.txt)|*.txt"] = "Plain text report (*.txt)|*.txt",
        ["XinSpect 時間膠囊 (*.xinsnapshot)|*.xinsnapshot|所有檔案 (*.*)|*.*"] = "XinSpect time capsule (*.xinsnapshot)|*.xinsnapshot|All files (*.*)|*.*",
        ["匯入外部工具的感測器報告"] = "Import a sensor report from an external tool",
        ["外部報告 (*.txt;*.xml;*.csv)|*.txt;*.xml;*.csv|所有檔案 (*.*)|*.*"] = "External reports (*.txt;*.xml;*.csv)|*.txt;*.xml;*.csv|All files (*.*)|*.*",
        ["讀取失敗：{0}"] = "Read failed: {0}",
        ["感測器引擎尚未就緒，稍候將自動載入可控風扇……"] = "The sensor engine is not ready yet. Controllable fans will load automatically shortly…",
        ["未偵測到可由軟體控制的系統風扇。\n\n多數情況需在 BIOS 將風扇模式設為「PWM／可控」；或主機板的 Super I/O 晶片未被 LibreHardwareMonitor 支援。筆電與部分品牌機的風扇由 EC 韌體全權管理，通常無法由軟體介入——此為正常情形，並非程式錯誤。"] = "No software-controllable system fans were detected.\n\nYou may need to set the fan mode to PWM or controllable in the BIOS, or LibreHardwareMonitor may not support the motherboard’s Super I/O chip. Fans in laptops and some prebuilt PCs are managed entirely by EC firmware and usually cannot be controlled by software. This is normal and does not indicate an application error.",
        ["逾時未收到提權實例的結果——可稍後按重新掃描更新狀態。"] = "Timed out waiting for the elevated instance. Click Rescan later to update the status.",
