        ["PMU 原生編程不可用。"] = "Native PMU programming is unavailable.",
        ["編程驗證執行中（3 輪：啟用→工作量→還原）……"] = "Programming validation running (3 rounds: enable → workload → restore)…",
        ["第 {0} 輪啟用{1}計數{2}還原{3}"] = "Round {0}: enable {1}, counting {2}, restore {3}",
        ["指定 FurMark 執行檔"] = "Select the FurMark executable",
        ["FurMark 執行檔|furmark.exe;FurMark_GUI.exe|所有執行檔 (*.exe)|*.exe"] = "FurMark executable|furmark.exe;FurMark_GUI.exe|All executables (*.exe)|*.exe",
