        ["儲存中…"] = "Saving…",
        ["無法寫入 hosts 檔：權限不足。\n請以系統管理員身分重新啟動曦覽。"] = "Cannot write the hosts file: insufficient privileges.\nRestart XinSpect as administrator.",
        ["已儲存並備份 ・ {0:HH:mm:ss}（如需生效可清除 DNS 快取）"] = "Saved and backed up ・ {0:HH:mm:ss} (clear the DNS cache if needed for changes to take effect)",
        ["已載入備份 {0}，請檢視後按「儲存」寫回。"] = "Backup {0} loaded. Review it, then click Save to write it back.",
        ["已清除 DNS 解析快取 ・ {0:HH:mm:ss}"] = "DNS resolver cache cleared ・ {0:HH:mm:ss}",
        ["負載 {0}%"] = "Load {0}%",
        ["認可 {0:0.0} / {1:0.0} GB"] = "Committed {0:0.0} / {1:0.0} GB",
        ["即將立刻重新開機並直接進入主機板的 UEFI／BIOS 設定畫面。\n\n・所有未存檔的工作都會遺失。\n・此動作需要系統管理員權限，會彈出提升視窗。\n・曦覽不會替你修改任何 BIOS 設定；設定一律在主機板自己的介面裡改。\n\n確定要現在重開機嗎？"] = "This will restart the PC immediately and open the motherboard’s UEFI/BIOS settings.\n\n・All unsaved work will be lost.\n・Administrator privileges are required; an elevation prompt will appear.\n・XinSpect does not change any BIOS settings. Make changes in the motherboard’s own interface.\n\nRestart now?",
        ["確認重開機進入 UEFI 設定"] = "Confirm restart into UEFI settings",
        ["中灰 50%"] = "Mid-gray 50%",
        ["黑"] = "Black",
        ["白"] = "White",
