        ["　　（已暫停移動，仍持續計幀）"] = "　　(Movement paused; frame counting continues)",
        ["{0} 未提供可供程式直接量測的公開端點，已跳轉至內建瀏覽器開啟其官方測速頁。"] = "{0} does not provide a public endpoint for direct measurement by the application. Its official speed-test page has been opened in the built-in browser.",
        ["下載中 ・ 目前 {0:0.0} Mbps（{1:0.0} MB/s）"] = "Downloading ・ Current {0:0.0} Mbps ({1:0.0} MB/s)",
        ["上傳中 ・ 目前 {0:0.0} Mbps（{1:0.0} MB/s）"] = "Uploading ・ Current {0:0.0} Mbps ({1:0.0} MB/s)",
        ["未連線"] = "Disconnected",
        ["未找到無線網路介面或 API 失敗"] = "No wireless network interface was found, or the API failed",
        ["偵測到 {0} 個 Wi-Fi 介面，均未連線——連線後 RSSI／頻道／速率才可讀。"] = "Detected {0} Wi-Fi interfaces; none are connected. RSSI, channel and speed are available after connecting.",
        ["已讀取 {0} 個 Wi-Fi 介面（{1} 個連線中）。"] = "Read {0} Wi-Fi interfaces ({1} connected).",
        ["即將套用核心電壓 {0:0.000} V，已超過建議安全上限 {1:0.00} V。\n\n過高的核心電壓可能造成當機、藍屏、過熱，長期更可能永久損壞處理器。\n請確認你清楚此風險，且散熱與供電足以負荷。\n\n確定要繼續套用嗎？"] = "You are about to apply a core voltage of {0:0.000} V, above the recommended safety ceiling of {1:0.00} V.\n\nExcessive core voltage can cause crashes, blue screens and overheating, and may permanently damage the processor over time.\nConfirm that you understand the risk and have adequate cooling and power delivery.\n\nContinue applying this voltage?",
        ["高電壓警告"] = "High-voltage warning",
        ["匯出超頻設定檔"] = "Export overclocking profile",
