        ["確定要清空全部歷史資料嗎？目前已保留 {0} 筆分鐘紀錄（{1}）。此動作無法復原。"] = "Clear all history? There are currently {0} minute records ({1}). This action cannot be undone.",
        ["確定要清空跑分紀錄簿嗎？目前已保留 {0} 筆成績。\n\n曦覽不內建其他機器的參考分數，這份紀錄是「與上次相比」「重複性」的唯一依據；清空後在重新累積出紀錄前，跑分只會有單次數字而無從比較。此動作無法復原。"] = "Clear the benchmark log? There are currently {0} results.\n\nXinSpect does not include reference scores from other PCs. This log is the only basis for comparisons with previous runs and repeatability checks. After clearing it, benchmark runs will show individual results without a comparison until new history is collected. This action cannot be undone.",
        ["免費共用額度目前尚未啟用（這個版本裡還沒有中轉網址），請用本機 Ollama 或自填端點與金鑰。"] = "The shared free quota is not enabled (this version has no relay URL). Use local Ollama or enter your own endpoint and key.",
        ["左聲道　只有左邊應該出聲"] = "Left channel　Only the left speaker should play",
        ["右聲道　只有右邊應該出聲"] = "Right channel　Only the right speaker should play",
