        ["膠囊摘要"] = "Summary capsules",
        ["機型資訊、系統資訊、已運行時間三顆膠囊"] = "Three capsules for model, system and uptime information",
        ["主機板、處理器、記憶體、顯示卡、顯示器、硬碟、聲卡、網卡逐列摘要"] = "Row-by-row summaries of the motherboard, CPU, memory, GPU, display, drives, audio and network adapters",
        ["處理器／顯示卡／主機板／記憶體的廠牌徽章"] = "Brand badges for the CPU, GPU, motherboard and memory",
        ["作業系統與主機板"] = "Operating system and motherboard",
        ["系統版本、開機時間、機型與 BIOS 兩欄資訊"] = "Two columns of OS version, boot time, model and BIOS information",
        ["處理器、核心數、記憶體與顯示卡摘要"] = "CPU, core count, memory and GPU summary",
        ["即時儀表"] = "Live gauges",
        ["CPU 使用率／CPU 溫度／記憶體／GPU 使用率四環儀表（預設關閉）"] = "Four ring gauges for CPU usage, CPU temperature, memory and GPU usage (off by default)",
        ["即時走勢"] = "Live trends",
        ["近 90 秒的 CPU 使用率、CPU 溫度、記憶體與 GPU 使用率（預設關閉）"] = "CPU usage, CPU temperature, memory and GPU usage over the last 90 seconds (off by default)",
        ["更多走勢"] = "More trends",
        ["近 90 秒的 CPU 頻率、GPU 溫度與顯示記憶體用量"] = "CPU frequency, GPU temperature and VRAM usage over the last 90 seconds",
        ["七段數字顯示：CPU 使用率、封裝溫度、封裝功耗與記憶體使用率（預設關閉）"] = "Seven-segment displays for CPU usage, package temperature, package power and memory usage (off by default)",
        ["KPI 觀測台"] = "KPI dashboard",
        ["曦覽硬體觀測儀主標題＋CPU 溫度／負載、GPU 溫度、記憶體四格巨型讀值"] = "XinSpect hardware monitor heading with large readings for CPU temperature/load, GPU temperature and memory",
        ["主機摘要卡"] = "Host summary card",
        ["SMBIOS 面向的主機板、處理器、顯示卡、記憶體、系統與開機時間六列"] = "Six SMBIOS-oriented rows for the motherboard, CPU, GPU, memory, system and boot time",
        ["事件時間軸"] = "Event timeline",
        ["硬體與安全事件的最近記錄（警示、降頻、藍屏偵測到時出現）"] = "Recent hardware and security events (shown when alerts, throttling or blue screens are detected)",
        ["深測中心只並列各測項的原始樣本、可信度與限制，不加權合成單一總分；跨域、跨軟體排名不成立。"] = "Deep Bench presents each test’s raw samples, confidence and limitations side by side, without combining them into a weighted total score. Rankings across domains or software are not valid.",
        ["高負載警告：執行期間 CPU、記憶體、GPU 與儲存可能接近滿載；請先儲存工作，筆電請接電源並注意散熱。"] = "High-load warning: the CPU, memory, GPU and storage may approach full load during the run. Save your work first. Plug in laptops and monitor cooling.",
        ["儲存測試只建立 XinSpect.deepbench.tmp 與 XinSpect.iocp.tmp，不碰既有檔案；結束、例外或取消後都會刪除，啟動前會檢查剩餘空間。"] = "Storage tests create only XinSpect.deepbench.tmp and XinSpect.iocp.tmp and do not touch existing files. These files are deleted after completion, exceptions or cancellation. Free space is checked before starting.",
        ["深測歷史只保存在本機設定資料夾，不上傳；沒有雲端同步，也沒有外部伺服器備份。"] = "Deep Bench history is saved only in the local settings folder and is not uploaded. There is no cloud sync or external server backup.",
        ["尚未啟動；選擇快速或完整檔後執行。"] = "Not started. Select the quick or full profile, then run it.",
        ["正在取消；已完成結果會保留。"] = "Cancelling; completed results will be kept.",
        ["深測尚未啟用。"] = "Deep Bench is not enabled.",
        ["深測已阻止：請先在設定啟用第一級進階診斷。高負載測項不會在背景自動啟動。"] = "Deep Bench was blocked. Enable Level 1 advanced diagnostics in Settings first. High-load tests do not start automatically in the background.",
        ["沒有可執行測項；請重新載入深測中心。"] = "No runnable tests are available. Reload Deep Bench.",
        ["已取消啟動；未執行深測。"] = "Startup cancelled; Deep Bench did not run.",
        ["深測已取消；未執行任何測項。"] = "Deep Bench cancelled; no tests were run.",
        ["準備啟動；不產生加權總分。"] = "Preparing to start; no weighted total score will be generated.",
        ["已取消；已完成結果已保留。"] = "Cancelled; completed results were kept.",
        ["已取消；只保留取消前已完成的結果，未跑項目不補值。"] = "Cancelled. Only results completed before cancellation were kept; unrun tests are not filled in.",
        ["啟動失敗；未產生有效量測。"] = "Startup failed; no valid measurements were produced.",
        ["深測啟動失敗：{0}"] = "Deep Bench startup failed: {0}",
        ["請先選擇儲存根：storage.qd-ladder、storage.mixed-rw、storage.write-integrity、storage.flush-durability、storage.slc-sustained-write 與 storage.iocp-engine 都需要可寫的暫存位置。"] = "Select a storage root first. storage.qd-ladder, storage.mixed-rw, storage.write-integrity, storage.flush-durability, storage.slc-sustained-write and storage.iocp-engine require a writable temporary location.",
        ["無法讀取儲存根剩餘空間：{0}"] = "Cannot read free space at the storage root: {0}",
        ["空間守衛未通過：預算 {0:0} MiB 後必須仍保留 8 GB；目前可用 {1:0} MiB。"] = "Free-space check failed: at least 8 GB must remain after the {0:0} MiB budget; currently {1:0} MiB is available.",
        ["受影響測項：storage.qd-ladder、storage.mixed-rw、storage.write-integrity、storage.flush-durability、storage.slc-sustained-write、storage.iocp-engine。請改用更大磁碟或降低暫存預算。"] = "Affected tests: storage.qd-ladder, storage.mixed-rw, storage.write-integrity, storage.flush-durability, storage.slc-sustained-write and storage.iocp-engine. Use a larger drive or reduce the temporary-space budget.",
        ["已完成 {0} 項；只並列原始量測，不加權合成。"] = "Completed {0} tests; raw measurements are presented side by side without a weighted score.",
        ["已完成 {0} 項，其中含失敗或無效結果；失敗項不補值。"] = "Completed {0} tests, including failures or invalid results; failed tests are not filled in.",
        ["已取消；保留 {0} 項結果，其餘標示未跑。"] = "Cancelled; {0} results were kept and the remaining tests are marked as not run.",
        ["執行中。"] = "Running.",
        ["{0} 項指標；樣本與可信度逐項列出。"] = "{0} metrics; samples and confidence are listed for each.",
        ["沒有有效量測樣本；不提供推算值。"] = "No valid measurement samples; no estimated values are provided.",
        ["已完成；含原始樣本與可信度。"] = "Completed; includes raw samples and confidence.",
        ["無有效量測。"] = "No valid measurements.",
        ["已取消；不補值。"] = "Cancelled; no values are filled in.",
        ["未執行；無有效量測。"] = "Not run; no valid measurements.",
        ["無有效量測（{0}）。"] = "No valid measurements ({0}).",
        ["・{0} 樣本・可信度 {1}"] = "・{0} samples・Confidence {1}",
        ["{0}：{1} 點跨多種配置；不跨配置平均，逐點值如下。"] = "{0}: {1} points across multiple configurations; values are listed below without averaging across configurations.",
        ["{0}：平均 {1:0.###} {2}・樣本 {3}・可信度 {4}"] = "{0}: Mean {1:0.###} {2}・Samples {3}・Confidence {4}",
        ["執行中"] = "Running",
        ["完成"] = "Completed",
        ["完成但含失敗"] = "Completed with failures",
        ["目前沒有降級紀錄。可能是一切正常，也可能是相關功能這次還沒被用到——這個欄位不是「保證無誤」的意思。"] = "No degradation has been recorded. Everything may be working, or the relevant features may not have been used during this run. This does not guarantee that no issues exist.",
        ["累計 {0} 筆，下方列出最近 {1} 筆（記憶體保留最多 {2} 筆，更早的只在紀錄檔裡）。"] = "{0} records in total; the latest {1} are shown below (up to {2} are kept in memory; older records remain only in the log file).",
        ["已清空畫面上的紀錄；diag.log 檔案本身保留不動。"] = "The records shown on screen were cleared; the diag.log file was kept.",
        ["還沒有 diag.log——這台機器上目前沒有任何被接住的例外寫進檔案。"] = "No diag.log exists yet. No caught exceptions have been written to a file on this PC.",
        ["尚未重查"] = "Not rechecked yet",
