        ["記憶體範圍是 Windows 配置的 BAR/孔徑，不是顯示記憶體容量；本頁沒有讀 MMIO、AER、BER 或訓練歷史。"] = "Memory ranges are BARs/apertures allocated by Windows, not VRAM capacity. This page does not read MMIO, AER, BER or link-training history.",
