        ["{0} 條原生 SPD ・ 一致 {1} ・ 矛盾 {2} ・ 可疑 {3} ・ 缺資料 {4}"] = "{0} native SPD records ・ Consistent {1} ・ Conflicting {2} ・ Suspicious {3} ・ Missing data {4}",
        ["目前沒有保留到原生 SPD 位元組；重新初始化後若 SMBus 可讀，這裡才會進行 CRC 與跨來源稽核。"] = "No native SPD bytes have been retained. CRC checks and cross-source audits will run here only if SMBus is readable after reinitialization.",
        ["只有原生 SPD 能驗 CRC；CPU-Z/SMBIOS 是交叉證據。單一欄位不一致不會直接宣稱模組造假。"] = "Only native SPD can be checked by CRC; CPU-Z/SMBIOS provide cross-source evidence. A mismatch in one field does not establish that a module is counterfeit.",
