        ["目前沒有 APERF/MPERF 量測；請先到處理器頁執行「頻率真相」，再回來擷取。"] = "No APERF/MPERF measurements are available. Run Frequency Truth on the Processor page, then return here to collect them.",
        ["保存的是取樣窗平均有效頻率與比值，不把頻率上限當成實際 P-state。"] = "The saved values are average effective frequencies and ratios over the sampling window; frequency ceilings are not treated as actual P-states.",
        ["寫入 {0} 筆 NVMe 原始計數器 ・ 近 30 天 {1} 筆"] = "Saved {0} raw NVMe counter records ・ {1} records in the last 30 days",
        ["沒有讀到 NVMe 健康紀錄；儲存堆疊或外接盒可能不轉發協定查詢，這不等於磁碟沒有 SMART。"] = "No NVMe health log was read. The storage stack or enclosure may not forward protocol queries; this does not mean the drive has no SMART data.",
        ["只顯示原始值與增量，不估算「還能活幾天」。計數器倒退會被標成重設，不算負成長。"] = "Only raw values and deltas are shown; remaining lifespan in days is not estimated. A counter decrease is marked as a reset, not negative growth.",
