        ["已由 SPD 直讀填入。注意：這是模組的 JEDEC 標準時序；若 BIOS 已開 XMP／EXPO，實際時序會比這裡更緊——完整對照仍以 CPU-Z 報告或 BIOS 為準。"] = "Populated by a direct SPD read. These are the module’s JEDEC standard timings. If XMP/EXPO is enabled in the BIOS, actual timings will be tighter; use the CPU-Z report or BIOS for the full comparison.",
