        // ── Reviewed dynamic UI: new-feature-dynamic-candidate.json ──
        ["僅 Intel family 6/model 0x55、裸機、Windows 單一封裝。只借用既有通道；不載入驅動、不施加負載。"] = "Intel family 6/model 0x55, bare metal, and a single Windows package only. Uses an existing channel only; loads no driver and applies no load.",
        ["僅 Intel family 6/model 0x55、裸機、Windows 單一封裝。只借用既有通道；不載入驅動、不施加負載。RAPL 與 LHM 可能共用計數器，並非獨立驗證。計數解析度不是準確度；重設與回繞可能無法區分，多次回繞無法由兩個端點排除。此結果不修改能量計信任，也不確認原 1.3 W 顯示的原因。"] = "Intel family 6/model 0x55, bare metal, and a single Windows package only. Uses an existing channel only; loads no driver and applies no load. RAPL and LHM may share a counter and do not provide independent verification. Counter resolution is not accuracy; resets and wraps may be indistinguishable, and two endpoints cannot rule out multiple wraps. This result does not change the energy counter's trust level or establish the cause of the original 1.3 W reading.",
        ["RAPL 與 LHM 可能共用計數器，並非獨立驗證。計數解析度不是準確度；重設與回繞可能無法區分，"] = "RAPL and LHM may share a counter and do not provide independent verification. Counter resolution is not accuracy; resets and wraps may be indistinguishable, and ",
        ["多次回繞無法由兩個端點排除。此結果不修改能量計信任，也不確認原 1.3 W 顯示的原因。"] = "two endpoints cannot rule out multiple wraps. This result does not change the energy counter's trust level or establish the cause of the original 1.3 W reading.",
        [" + 未知"] = " + unknown",
        ["  [部分]"] = "  [partial]",
        ["  [硬連結]"] = "  [hard link]",
        ["{0}\n邏輯大小（檔名計數）：{1}；已確認唯一配置：{2}\n"] = "{0}\nLogical size (counted by filename): {1}; confirmed unique allocation: {2}\n",
        ["{0}\n邏輯大小（檔名計數）：{1}；已確認唯一配置：{2}\n檔案：{3:N0}；配置未知：{4:N0}"] = "{0}\nLogical size (counted by filename): {1}; confirmed unique allocation: {2}\nFiles: {3:N0}; allocation unknown: {4:N0}",
        ["檔案：{0:N0}；配置未知：{1:N0}"] = "Files: {0:N0}; allocation unknown: {1:N0}",
        ["保留模型採保守估算：固定 64 KiB + 最大檔案保留數 × 64 B；每節點 4096 B + 完整路徑字元數 × 4 B（涵蓋節點、路徑/副檔名、身分及容器餘裕）；每條保留診斷另加 256 B + 路徑與說明字元數 × 2 B。說明最多保留 1024 字元。到預算上限即停止；這不是 CLR/process heap 的硬上限，不含 CLR、原生 I/O 緩衝、UI 與匯出序列化的暫時配置。"] = "The retained model uses conservative accounting: a fixed 64 KiB + maximum retained file count × 64 B; 4096 B per node + full path character count × 4 B (allowing for nodes, paths/extensions, identities, and containers); each retained diagnostic adds 256 B + path and description character count × 2 B. Descriptions retain at most 1024 characters. Scanning stops at the budget. This is not a hard limit on the CLR/process heap and excludes the CLR, native I/O buffers, UI, and temporary export serialization allocations.",
        ["非快照；檔案在掃描時仍可改變。只統計一般檔案的未命名資料流；不含 ADS、目錄/檔案系統中繼資料、磁碟保留空間。配置值是檔案系統回報，非可回收空間或實體扇區稽核；跨檔案共用區塊/重複資料刪除不保證可辨識。重解析點（含連結、掛載點及雲端預留位置）不追蹤。邏輯大小按檔名計，配置依 volume + 128-bit file ID 去重並歸於先遇到的路徑；沒有 ID 的檔案不加入唯一配置總數。遍歷中的目錄持有禁止 delete-sharing 的 0x81 handle；不保證抵抗所選根以上祖先改變或惡意檔案系統/過濾驅動。預算/取消只在檔案系統呼叫之間檢查，無法中止正在等待的系統 I/O。保留模型另有估算預算，非 CLR heap 硬上限。"] = "This is not a snapshot; files can change during the scan. Only unnamed data streams of ordinary files are counted; ADS, directory/filesystem metadata, and disk reserved space are excluded. Allocation is reported by the filesystem; it is not reclaimable space or an audit of physical sectors. Shared blocks and deduplication across files may not be identifiable. Reparse points (including links, mount points, and cloud placeholders) are not followed. Logical size is counted by filename; allocation is deduplicated by volume + 128-bit file ID and attributed to the first path encountered. Files without an ID are excluded from the unique allocation total. Directories being traversed hold a 0x81 handle that denies delete sharing; this does not guarantee protection against changes to ancestors above the selected root or hostile filesystems/filter drivers. Budgets and cancellation are checked only between filesystem calls and cannot interrupt pending system I/O. The retained model has a separate estimated budget, not a hard CLR heap limit.",
        ["{0} · {1:N0} 個檔案 · {2:N0} 個項目 · {3:F1} 秒\n"] = "{0} · {1:N0} files · {2:N0} entries · {3:F1} s\n",
        ["{0} · {1:N0} 個檔案 · {2:N0} 個項目 · {3:F1} 秒\n邏輯大小 {4}；已確認唯一配置 {5}；硬連結重複 {6:N0}；略過/限制/錯誤 {7:N0}\n保留模型估算 {8} / {9}（非 CLR heap 硬上限）"] = "{0} · {1:N0} files · {2:N0} entries · {3:F1} s\nLogical size {4}; confirmed unique allocation {5}; duplicate hard links {6:N0}; skipped/limited/errors {7:N0}\nEstimated retained model {8} / {9} (not a hard CLR heap limit)",
        ["列舉完成"] = "Enumeration complete",
        ["已取消，保留部分結果"] = "Cancelled; partial results retained",
        ["部分結果"] = "Partial results",
        ["邏輯大小 {0}；已確認唯一配置 {1}；硬連結重複 {2:N0}；略過/限制/錯誤 {3:N0}\n"] = "Logical size {0}; confirmed unique allocation {1}; duplicate hard links {2:N0}; skipped/limited/errors {3:N0}\n",
        ["保留模型估算 {0} / {1}（非 CLR heap 硬上限）"] = "Estimated retained model {0} / {1} (not a hard CLR heap limit)",
