        ["尚未支援"] = "Not supported yet",
        ["本程式擷取："] = "Application capture: ",
        ["；來源更新："] = "; source update: ",
        ["目前未取得控制器觀測。"] = "No controller observations have been obtained.",
        ["目前副時序只採用已取得的 CPU-Z 報告欄位；未實作控制器暫存器副時序直讀。tRC／tRRD_S/L／tFAW／tWTR_S/L／tWR／tRTP／tCWL 尚未支援。SPD JEDEC／XMP／EXPO 表不作目前值。"] = "Current subtimings use only fields from an available CPU-Z report; direct controller-register reads of subtimings are not implemented. tRC/tRRD_S/L/tFAW/tWTR_S/L/tWR/tRTP/tCWL are not supported yet. SPD JEDEC/XMP/EXPO tables are not used as current values.",
        ["≥ {0:G} {1}；恢復 ≤ {2:G} {3}"] = "≥ {0:G} {1}; recovery ≤ {2:G} {3}",
        ["≤ {0:G} {1}；恢復 ≥ {2:G} {3}"] = "≤ {0:G} {1}; recovery ≥ {2:G} {3}",
        ["規則 ID 不得為空。"] = "The rule ID must not be empty.",
        ["名稱須為 1–100 個字元，不得含控制字元。"] = "The name must contain 1–100 characters and no control characters.",
        ["感測器 ID 須為 1–512 個字元，不得含控制字元。"] = "The sensor ID must contain 1–512 characters and no control characters.",
        ["感測器單位不合法。"] = "The sensor unit is invalid.",
        ["請選擇有效的上限或下限。"] = "Select a valid upper or lower limit.",
        ["觸發與恢復閾值必須為有限數字。"] = "Trigger and recovery thresholds must be finite numbers.",
        ["上限規則的恢復閾值須低於觸發閾值。"] = "For an upper-limit rule, the recovery threshold must be below the trigger threshold.",
        ["下限規則的恢復閾值須高於觸發閾值。"] = "For a lower-limit rule, the recovery threshold must be above the trigger threshold.",
        ["持續時間須為 0–86400 秒。"] = "Duration must be 0–86400 seconds.",
        ["通知冷卻須為 0–604800 秒。"] = "Notification cooldown must be 0–604800 seconds.",
        ["已停用"] = "Disabled",
        ["正常"] = "Normal",
        ["等待持續 {0:0.0}/{1:G} 秒"] = "Waiting for duration: {0:0.0}/{1:G} s",
        ["警示中"] = "Alert active",
        ["資料未知；警示尚未確認恢復"] = "Data unknown; alert recovery not confirmed",
        ["資料未知／缺讀"] = "Data unknown/missing reading",
        ["此診斷已有採樣正在執行；必須等待同步讀取確實返回。"] = "A capture is already running for this diagnostic; wait for the synchronous read to actually return.",
        ["QPC 頻率無效；未讀 MSR。"] = "Invalid QPC frequency; no MSR was read.",
        ["無法確認 Windows 單一實體封裝拓撲；本版不對多封裝或未知拓撲取樣。"] = "Windows topology could not be confirmed as a single physical package; this version does not sample multiple packages or unknown topologies.",
        ["無法釘選指定 group／LP；未讀 MSR。"] = "Could not pin to the specified group/LP; no MSR was read.",
        ["本診斷僅收錄裸機 Intel family 6/model 0x55，且須取得 CPUID package 身份；未知平台未讀 MSR。"] = "This diagnostic supports only bare-metal Intel family 6/model 0x55 with a CPUID package identity. No MSR was read on an unrecognized platform.",
        ["沒有已開啟且獲准的共用 MSR 通道；本診斷未初始化後端、未載入／重裝驅動。既有 LHM 通道不代表共用路由已開啟。"] = "No shared MSR channel is already open and permitted. This diagnostic did not initialize a backend or load/reinstall a driver. An existing LHM channel does not mean the shared route is open.",
        ["基準點；尚無兩個可比較端點。"] = "Baseline; two comparable endpoints are not yet available.",
        ["讀取失敗；舊值與差分基準均不沿用。"] = "Read failed; neither old values nor the previous differential baseline is reused.",
        ["能量未讀取。"] = "Energy was not read.",
        ["單位或能量保留位無法確認；不換算瓦數。"] = "The unit or reserved energy bits could not be confirmed; no wattage is calculated.",
        ["MSR 單位全零／保留位異常，或能量高 32 位非零；保留 raw，不猜測換算。"] = "The MSR unit value is all zero, reserved bits are invalid, or the upper 32 energy bits are nonzero. Raw values are retained without guessing a conversion.",
        ["被動計數差分；未驗證估值。"] = "Passive counter difference; unverified estimate.",
        ["採樣完成：保留 8 組原始值與 QPC 差分，所有瓦數仍為未驗證估值；未啟動負載或變更信任。"] = "Capture complete: 8 sets of raw values and QPC differences were retained. All wattages remain unverified estimates; no load was started and no trust level was changed.",
        ["第一級進階診斷已關閉；停止後續讀取。"] = "Level 1 advanced diagnostics was disabled; further reads stopped.",
        ["使用者已取消；目前同步讀取確實返回後停止，未沿用舊值。"] = "Cancelled by the user; stopped after the current synchronous read actually returned, without reusing old values.",
        ["既有來源／通道政策已變更；停止後續讀取。"] = "The existing source/channel policy changed; further reads stopped.",
        ["被動診斷失敗；未重試或切換通道："] = "Passive diagnostic failed; no retry or channel switch was attempted: ",
        ["第一級進階診斷已關閉。"] = "Level 1 advanced diagnostics is disabled.",
        ["既有通道已變更。"] = "The existing channel changed.",
        ["目前 group／LP 與釘選目標不符；停止取樣。"] = "The current group/LP differs from the pinned target; sampling stopped.",
        ["同步讀取的 QPC 區間無效或超過 250 ms 預算；raw 僅供診斷，不換算。"] = "The synchronous read's QPC interval is invalid or exceeded the 250 ms budget; raw values are diagnostic only and are not converted.",
        ["既有通道讀取失敗；無 raw，未以零代替。"] = "The existing channel read failed; no raw value is available and zero was not substituted.",
        ["同步讀取成功；不是計數器精度認證。"] = "The synchronous read succeeded; this does not certify counter accuracy.",
        ["時間窗／單位不連續；不換算瓦數，下筆重新建立基準。"] = "The time window or unit is discontinuous; no wattage is calculated. The next sample establishes a new baseline.",
        ["已保留模 2^32 增量；下降可能是回繞或重設，無法區分，因此不發布瓦數。"] = "The modulo-2^32 increment is retained. The decrease may be a wrap or reset and cannot be distinguished, so no wattage is published.",
        ["計數未前進；可能受更新週期／解析度限制，不宣稱功耗為零。"] = "The counter did not advance; its update period or resolution may be limiting. Zero power consumption is not claimed.",
        ["能量計未經校準；一個 count 的瓦數解析度不是誤差界線。無法只靠端點排除多次回繞或中途重設。"] = "The energy counter is uncalibrated; the wattage resolution of one count is not an error bound. Endpoints alone cannot rule out multiple wraps or an intervening reset.",
        ["磁碟配置空間需要 Windows 檔案 API。"] = "Disk allocation analysis requires the Windows file API.",
        ["目錄在取得遍歷保護前已改變類型，已停止讀取此路徑。"] = "The directory changed type before traversal protection was acquired; reading this path stopped.",
        ["檔案系統回報負數長度，拒絕納入統計。"] = "The filesystem reported a negative length; it was excluded from the statistics.",
        ["FileIdInfo 失敗（Win32 {0}）：{1}"] = "FileIdInfo failed (Win32 {0}): {1}",
        ["只可列舉非重解析目錄。"] = "Only directories that are not reparse points can be enumerated.",
        ["請指定完整的目錄路徑。"] = "Specify a fully qualified directory path.",
        ["請選擇一般磁碟/UNC 目錄；不接受裝置命名空間。"] = "Select an ordinary disk/UNC directory; device namespaces are not accepted.",
        ["目錄路徑超過本掃描器的 32,767 字元上限。"] = "The directory path exceeds this scanner's 32,767-character limit.",
        ["達到保留中繼資料的估算預算；已停止讀取/保留後續項目，結果不完整。此預算不是 CLR heap 硬上限。"] = "The estimated retained-metadata budget was reached; reading/retaining further entries stopped and results are incomplete. This budget is not a hard CLR heap limit.",
        [" [截斷]"] = " [truncated]",
        ["使用者要求取消；保留已完成的統計。"] = "Cancellation requested by the user; completed statistics are retained.",
        ["達到時間預算；未列舉的項目數未知。"] = "The time budget was reached; the number of unenumerated entries is unknown.",
        ["達到項目預算；未列舉的項目數未知。"] = "The entry budget was reached; the number of unenumerated entries is unknown.",
        ["位元組加總超出 Int64；此欄已飽和，不能視為精確值。"] = "The byte sum exceeded Int64; this field has saturated and cannot be treated as exact.",
        ["權限不足："] = "Insufficient privileges: ",
        ["讀取失敗："] = "Read failed: ",
        ["本次預算/取消後未讀取。"] = "Not read after the budget limit/cancellation.",
        ["重解析點未追蹤（包含符號連結、junction、掛載點及雲端預留位置）。"] = "Reparse points are not followed (including symbolic links, junctions, mount points, and cloud placeholders).",
        ["所選根路徑不是目錄。"] = "The selected root path is not a directory.",
        ["檔案長度未知或格式無效，未當成 0 納入。"] = "The file length is unknown or invalid; it was not counted as zero.",
        ["缺少檔案身分或配置大小；未加入唯一配置總數。"] = "File identity or allocated size is missing; excluded from the unique allocation total.",
        ["同一 volume + file ID 已計入另一檔名；本路徑的唯一配置貢獻為 0。"] = "The same volume + file ID was already counted under another filename; this path contributes zero to unique allocation.",
        ["（無副檔名）"] = "(no extension)",
        ["目錄身分重複，拒絕重複遍歷。"] = "Duplicate directory identity; repeated traversal was refused.",
        ["已達深度上限，未列舉此目錄內容。"] = "The depth limit was reached; this directory's contents were not enumerated.",
        ["子項路徑超過本掃描器的 32,767 字元上限。"] = "A child path exceeds this scanner's 32,767-character limit.",
        ["列舉器回報非直接子項目，已拒絕越界遍歷。"] = "The enumerator reported an entry that is not an immediate child; traversal outside the boundary was refused.",
        ["根目錄模型預留失敗。"] = "Could not reserve space for the root directory model.",
