        ["DISM 傳回無效或超出預算的套件陣列。"] = "DISM returned an invalid package array or one exceeding the budget.",
        ["{0} 失敗（HRESULT 0x{1:X8}）。"] = "{0} failed (HRESULT 0x{1:X8}).",
        ["僅接受明確的 oem#.inf。"] = "Only an explicit oem#.inf name is accepted.",
        ["PnPUtil /export-driver 需要 Windows 10 1607。"] = "PnPUtil /export-driver requires Windows 10 1607.",
        ["匯出需使用者自行以系統管理員啟動；不會自動提權。"] = "To export, start the application as administrator yourself; it will not elevate automatically.",
        ["找不到系統 PnPUtil。"] = "System PnPUtil was not found.",
        ["無法啟動系統 PnPUtil。"] = "Could not start system PnPUtil.",
        ["PnPUtil 匯出超過每套件 5 分鐘預算，已停止匯出程序；部分檔案保留。"] = "PnPUtil export exceeded the 5-minute budget per package. The export process was stopped; partial files are retained.",
        ["WMI 裝置綁定列舉超過整體時間預算；拒絕發布部分結果。"] = "WMI device binding enumeration exceeded the overall time budget; partial results will not be published.",
        ["WMI 總列舉列數超出預算（含空 INF 列）。"] = "Total WMI rows enumerated exceeded the budget (including rows with an empty INF).",
