        ["請選擇至少一個且不超過 32768 個套件。"] = "Select at least one package and no more than 32768 packages.",
        ["僅可匯出無重複、已確認的第三方 oem#.inf 套件；Windows 隨附套件不支援此匯出介面。"] = "Only confirmed third-party oem#.inf packages without duplicates can be exported. Packages included with Windows are not supported by this export interface.",
