        ["PnPUtil 結束碼 {0}；部分輸出保留，未列為成功備份。"] = "PnPUtil exit code {0}; partial output is retained and is not counted as a successful backup.",
        ["PnPUtil 回報成功，但輸出中沒有 INF；未列為成功備份。"] = "PnPUtil reported success, but the output contains no INF; it is not counted as a successful backup.",
