        ["使用者取消；此目錄可能含部分檔案。"] = "Cancelled by the user; this directory may contain partial files.",
        ["已匯出 {0} 個套件；manifest 記錄實際輸出及 SHA-256。此備份未經還原驗證。"] = "Exported {0} packages; the manifest records actual output and SHA-256 hashes. Restoration from this backup has not been verified.",
        ["已取消；未完成目錄保留供檢查，請勿當成完整備份。"] = "Cancelled; incomplete directories are retained for inspection. Do not treat them as a complete backup.",
        [" manifest 寫入失敗："] = " Manifest write failed: ",
        ["請選擇本機磁碟的完整資料夾路徑（不支援 UNC、裝置路徑及 ADS）。"] = "Select a fully qualified folder path on a local disk (UNC, device paths, and ADS are not supported).",
        ["目的地必須是現有資料夾且完整路徑不超過 170 字元。"] = "The destination must be an existing folder with a fully qualified path no longer than 170 characters.",
        ["請選擇 Windows 與 Program Files 系統目錄以外的備份目的地。"] = "Select a backup destination outside the Windows and Program Files system directories.",
        ["備份目的地不得經過 junction、符號連結或其他 reparse point。"] = "The backup destination must not pass through a junction, symbolic link, or other reparse point.",
        ["單套件目錄深度超過 64 層預算。"] = "A package directory exceeds the depth budget of 64 levels.",
