        ["無法解析備份資料夾的真實路徑。"] = "Could not resolve the backup folder's actual path.",
        ["備份目的地須為本機磁碟。"] = "The backup destination must be on a local disk.",
        ["MCLK／UCLK／FCLK 來自既有 LHM AMD CPU 的 Memory／Uncore／Fabric 感測器。上游只有特定 PM-table 佈局（001E0004／00240903／00380805／00540004）提供這三欄，不能按世代名稱推定支援。Intel／其他平台未提供這條路徑。本程式快照 30 秒到期；來源快取仍未確認新鮮度。未新增硬體存取或驅動。"] = "MCLK/UCLK/FCLK come from the existing LHM AMD CPU Memory/Uncore/Fabric sensors. Upstream provides these three fields only for specific PM-table layouts (001E0004/00240903/00380805/00540004); support cannot be inferred from a generation name. Intel and other platforms do not provide this path. This application's snapshot expires after 30 seconds; the freshness of the source cache remains unconfirmed. No hardware access or driver was added.",
        ["MCLK（記憶體時脈）"] = "MCLK (memory clock)",
        ["UCLK（控制器時脈）"] = "UCLK (controller clock)",
        ["FCLK（Fabric 時脈）"] = "FCLK (fabric clock)",
        ["此 CPU 的既有 provider 未提供此感測器。"] = "This CPU's existing provider does not supply this sensor.",
        ["同一 CPU 有重複感測器，拒絕任選一筆。"] = "Duplicate sensors exist for the same CPU; selecting an arbitrary reading was refused.",
        ["既有 provider 快取觀測；LHM 讀取 PM table 失敗時可能保留舊值，無逐值更新證據，故不標為已確認即時量測。"] = "Cached observation from the existing provider. LHM may retain old values when reading the PM table fails. No evidence confirms updates for individual values, so this is not labeled a confirmed real-time measurement.",
        ["此輪感測值缺失、非有限數，或超出既有頻率範圍（0–{0} MHz，不含 0）；不沿用本程式上一輪數值。"] = "This poll's sensor value is missing, non-finite, or outside the existing frequency range (0–{0} MHz, excluding 0); this application's value from the previous poll is not reused.",
        ["Windows 設定資料速率"] = "Windows configured data rate",
        ["Windows 回報設定值；不以此數字除以二填成目前 MCLK。"] = "Windows reports a configured value; it is not divided by two and used as the current MCLK.",
        ["來源回報的目前 DRAM 時脈；來源更新時間未知。"] = "Current DRAM clock reported by the source; the source update time is unknown.",
        ["Windows 設定資料速率，不是控制器即時時脈。"] = "Windows configured data rate, not the controller's real-time clock.",
        ["全機"] = "System-wide",
        ["尚未取得一致且有效的 Windows 設定資料速率；不以 SPD 額定值補入。"] = "A consistent, valid Windows configured data rate has not been obtained; SPD rated values are not substituted.",
        ["未取得目前副時序來源；SPD 能力表不補為目前值。"] = "No source of current subtimings was obtained; SPD capability tables are not substituted for current values.",
        ["目前時序來源回報值，單位為 DRAM clock cycles；沒有套用 SPD 表。"] = "Value reported by the current timing source, in DRAM clock cycles; no SPD table was applied.",
        ["原始回報不是可確認的正整數 clock cycles；保留原文但不確認為有效時序。"] = "The raw report cannot be confirmed as a positive integer number of clock cycles. The original text is retained without confirming it as a valid timing.",
        ["既有 provider 未提供可用的目前值；未由設定速率或其他時脈推導。"] = "The existing provider did not supply a usable current value; none was derived from a configured rate or another clock.",
        ["本程式最近一次成功輪詢已超過 {0:0.#} 秒或單調鐘區間無效；清除數值。來源更新時間仍未知。"] = "This application's last successful poll is more than {0:0.#} seconds old, or the monotonic clock interval is invalid; values were cleared. The source update time remains unknown.",
        ["此輪硬體輪詢失敗或服務已關閉；不沿用先前值。"] = "This hardware poll failed or the service was closed; previous values are not reused.",
        ["IHardware / ISensor metadata 與快取值"] = "IHardware / ISensor metadata and cached values",
