        ["已取得 {0} / {1} 個來源觀測；來源內部更新時間未知，未驗證功率不進統計。"] = "Obtained {0} / {1} source observations; internal source-update times are unknown, and unverified power readings are excluded from statistics.",
        ["已取得 {0} / {1} 個來源觀測（超過 16,384 項上限者未發布）；來源內部更新時間未知，未驗證功率不進統計。"] = "Obtained {0} / {1} source observations (items beyond the 16,384 limit were not published); internal source-update times are unknown, and unverified power readings are excluded from statistics.",
        ["本拍讀取失敗；保留已累積統計，但不把舊讀值當成新樣本。"] = "This poll failed. Accumulated statistics are retained, but old readings are not counted as new samples.",
        ["來源內部更新時間未知；本時間是本程式取得觀測的時間。"] = "The internal source-update time is unknown; this timestamp records when this application obtained the observation.",
        ["來源未提供有效有限讀值；不以舊值或 0 補值。"] = "The source provided no valid finite reading; neither old values nor zero are substituted.",
        ["LHM CPU 功率缺少當拍讀取成功與來源更新時間證據；全域 RAPL 響應驗證未綁定此感測器。保留上報值供診斷，不納入統計／CSV 數值／告警。"] = "LHM CPU power lacks evidence of a successful read this poll and a source-update timestamp. Global RAPL response validation is not bound to this sensor. The reported value is retained for diagnosis but excluded from statistics, CSV numeric values and alerts.",
        ["LHM PM table 可能保留前值；來源未提供成功更新時間，不能確認是目前控制器時脈。"] = "The LHM PM table may retain an earlier value. The source supplies no successful-update timestamp, so the value cannot be confirmed as the current controller clock.",
        ["來源識別碼不可讀；識別僅限本次工作階段。"] = "The source identifier is unreadable; identity is limited to this session.",
