        // ── Reviewed dynamic UI: memory-controller-boundary-candidate.json ──
        ["本程式擷取：未知；來源更新：未知"] = "Application capture: unknown; source update: unknown",
        ["本程式擷取：{0}；來源更新：未知"] = "Application capture: {0}; source update: unknown",
        ["本程式擷取：未知；來源更新：{0}"] = "Application capture: unknown; source update: {0}",
        ["{0} · {1} · 全機"] = "{0} · {1} · Whole system",
        ["{0} · {1} · 全機（來源未提供逐控制器範圍）"] = "{0} · {1} · Whole system (the source provides no per-controller scope)",
        ["{0} · {1} · 來源身分未能確認"] = "{0} · {1} · Source identity unconfirmed",
        ["{0} · {1} · 未知"] = "{0} · {1} · Unknown",
        ["{0}；此 CPU 的既有 provider 未提供此感測器。"] = "{0}; This CPU's existing provider does not supply this sensor.",
        ["{0}；同一 CPU 有重複感測器，拒絕任選一筆。"] = "{0}; Duplicate sensors exist for the same CPU; selecting an arbitrary reading was refused.",
        ["{0}；既有 provider 快取觀測；LHM 讀取 PM table 失敗時可能保留舊值，無逐值更新證據，故不標為已確認即時量測。"] = "{0}; Cached observation from the existing provider. LHM may retain old values when reading the PM table fails. No evidence confirms updates for individual values, so this is not labeled a confirmed real-time measurement.",
        ["{0}；此輪感測值缺失、非有限數，或超出既有頻率範圍（0–{1} MHz，不含 0）；不沿用本程式上一輪數值。"] = "{0}; This poll's sensor value is missing, non-finite, or outside the existing frequency range (0–{1} MHz, excluding 0); this application's value from the previous poll is not reused.",
        ["{0}；Windows 回報設定值；不以此數字除以二填成目前 MCLK。"] = "{0}; Windows reports a configured value; it is not divided by two and used as the current MCLK.",
        ["{0}；來源回報的目前 DRAM 時脈；來源更新時間未知。"] = "{0}; Current DRAM clock reported by the source; the source update time is unknown.",
        ["{0}；Windows 設定資料速率，不是控制器即時時脈。"] = "{0}; Windows configured data rate, not the controller's real-time clock.",
        ["{0}；尚未取得一致且有效的 Windows 設定資料速率；不以 SPD 額定值補入。"] = "{0}; A consistent, valid Windows configured data rate has not been obtained; SPD rated values are not substituted.",
        ["{0}；未取得目前副時序來源；SPD 能力表不補為目前值。"] = "{0}; No source of current subtimings was obtained; SPD capability tables are not substituted for current values.",
        ["{0}；目前時序來源回報值，單位為 DRAM clock cycles；沒有套用 SPD 表。"] = "{0}; Value reported by the current timing source, in DRAM clock cycles; no SPD table was applied.",
        ["{0}；原始回報不是可確認的正整數 clock cycles；保留原文但不確認為有效時序。"] = "{0}; The raw report cannot be confirmed as a positive integer number of clock cycles. The original text is retained without confirming it as a valid timing.",
        ["{0}；既有 provider 未提供可用的目前值；未由設定速率或其他時脈推導。"] = "{0}; The existing provider did not supply a usable current value; none was derived from a configured rate or another clock.",
        ["{0}；本程式最近一次成功輪詢已超過 {1:0.#} 秒或單調鐘區間無效；清除數值。來源更新時間仍未知。"] = "{0}; This application's last successful poll is more than {1:0.#} seconds old, or the monotonic clock interval is invalid; values were cleared. The source update time remains unknown.",
        ["{0}；此輪硬體輪詢失敗或服務已關閉；不沿用先前值。"] = "{0}; This hardware poll failed or the service was closed; previous values are not reused.",
        ["{0}；記憶體控制器觀測支線擷取失敗（{1}）；不是已確認無硬體。其他感測器仍依原輪詢結果發布。"] = "{0}; Memory controller observation capture failed ({1}); this does not confirm that the hardware is absent. Other sensors are still published according to the original poll results.",

