        ["L1／L2 都還在（同一顆核心的兩條執行緒共用），代價最小。"] = "L1/L2 remain available (shared by the two threads on the same core), with the lowest cost.",
        ["L1／L2 的內容留在原本那顆核上，得重新拉；L3 還命中。"] = "L1/L2 contents remain on the original core and must be fetched again; L3 can still provide hits.",
        ["連 L3 都要重新拉——跨 CCX、跨 die 或跨 mesh 分片時就是這一層。"] = "Even L3 contents must be fetched again. This is the level for crossing CCXs, dies, or mesh partitions.",
        ["記憶體變成遠端存取，延遲與頻寬雙重打折，代價最大。"] = "Memory access becomes remote, affecting both latency and bandwidth, with the highest cost.",
