        ["無法確認此型號的管線寬度與事件可用性，故不出數字：猜一個分母去除，比誠實說「不知道」更糟。"] = "The pipeline width and event availability for this model cannot be confirmed, so no figures are reported. Guessing a denominator would be worse than acknowledging that it is unknown.",
