        ["LGA2066 Xeon W-2100／W-2200 工作站平台。CPU SKU 決定記憶體通道、ECC 與 PCIe 能力；主機板、BIOS 及處理器共同決定實際配置。"] = "LGA2066 Xeon W-2100/W-2200 workstation platform. The CPU SKU determines memory channels, ECC, and PCIe capabilities; the motherboard, BIOS, and processor together determine the actual configuration.",
        ["Basin Falls 高階桌面平台，搭配 LGA2066 Core X。Kaby Lake-X 與 Skylake-X／Cascade Lake-X 的記憶體通道及 PCIe 能力不同，須按 CPU SKU 判讀；PCH 資源也受主機板配置影響。"] = "Basin Falls high-end desktop platform for LGA2066 Core X. Memory channels and PCIe capabilities differ between Kaby Lake-X and Skylake-X/Cascade Lake-X and must be interpreted by CPU SKU; motherboard configuration also affects PCH resources.",
        ["Grantley 工作站／伺服器晶片組，常見於 LGA2011-v3 Xeon E5 v3／v4。CPU SKU、主機板與 BIOS 決定插槽數、記憶體通道、ECC／RDIMM 與 PCIe 配置。"] = "Grantley workstation/server chipset, commonly used with LGA2011-v3 Xeon E5 v3/v4. The CPU SKU, motherboard, and BIOS determine socket count, memory channels, ECC/RDIMM support, and PCIe configuration.",
        ["LGA2011-v3 Haswell-E／Broadwell-E 高階桌面平台。記憶體與 PCIe 能力依處理器 SKU；X99 主機板不能據此推定 Xeon E5 伺服器功能。"] = "LGA2011-v3 Haswell-E/Broadwell-E high-end desktop platform. Memory and PCIe capabilities depend on the processor SKU; an X99 motherboard does not establish the presence of Xeon E5 server features.",
        ["LGA2011 Sandy Bridge-E／Ivy Bridge-E 高階桌面平台；同代 Xeon E5 使用 C600 系列晶片組。CPU、主機板與 BIOS 決定記憶體及 PCIe 配置。"] = "LGA2011 Sandy Bridge-E/Ivy Bridge-E high-end desktop platform; contemporary Xeon E5 processors use C600-series chipsets. The CPU, motherboard, and BIOS determine memory and PCIe configuration.",
        ["LGA1366 Nehalem／Westmere 高階桌面與工作站平台；X58 北橋搭配 ICH10 系列南橋。實際 CPU、記憶體插槽與擴充配置由主機板決定。"] = "LGA1366 Nehalem/Westmere high-end desktop and workstation platform; the X58 northbridge is paired with an ICH10-series southbridge. The motherboard determines the actual CPU, memory slots, and expansion configuration.",
        ["Intel C600 系列伺服器／工作站 PCH。與 C602／C604／C606 同屬一代平台；CPU SKU、主機板與 BIOS 決定記憶體、插槽及 I/O 能力。"] = "Intel C600-series server/workstation PCH. It belongs to the same platform generation as C602/C604/C606; the CPU SKU, motherboard, and BIOS determine memory, sockets, and I/O capabilities.",
        ["Intel C600 系列伺服器／工作站 PCH。Xeon E5 能力依處理器與主機板配置，不由晶片組名稱單獨決定。"] = "Intel C600-series server/workstation PCH. Xeon E5 capabilities depend on processor and motherboard configuration, rather than the chipset name alone.",
        ["Intel C600 系列伺服器／工作站 PCH，常見於 LGA2011 Xeon E5 v1／v2。CPU SKU、主機板與 BIOS 決定記憶體、插槽及 I/O 能力。"] = "Intel C600-series server/workstation PCH, commonly used with LGA2011 Xeon E5 v1/v2. The CPU SKU, motherboard, and BIOS determine memory, sockets, and I/O capabilities.",
        ["Intel C600 系列"] = "Intel C600 series",
        ["韌體或裝置名稱只回報 C600 系列，無法據此分辨 C602／C604／C606／C608；不推定單一型號。"] = "The firmware or device name reports only the C600 series. This does not distinguish C602/C604/C606/C608, so no specific model is inferred.",
        ["伺服器 PCH；不同插槽世代與 Xeon Scalable CPU 不可只憑相似型號互推。記憶體與 PCIe 能力須依 CPU SKU、主機板及 BIOS 核對。"] = "Server PCH. Similar model names alone do not establish equivalence between socket generations or Xeon Scalable CPUs. Check memory and PCIe capabilities against the CPU SKU, motherboard, and BIOS.",
        ["Lewisburg 伺服器／工作站 PCH，常見於 LGA3647 Xeon Scalable 與部分 Xeon W 平台。CPU SKU、主機板及 BIOS 決定記憶體、插槽及 I/O 配置。"] = "Lewisburg server/workstation PCH, commonly used with LGA3647 Xeon Scalable and some Xeon W platforms. The CPU SKU, motherboard, and BIOS determine memory, sockets, and I/O configuration.",
        ["Lewisburg 伺服器／工作站 PCH。CPU SKU、主機板與 BIOS 決定記憶體、插槽及 I/O 配置。"] = "Lewisburg server/workstation PCH. The CPU SKU, motherboard, and BIOS determine memory, sockets, and I/O configuration.",
        ["Xeon W-2400／W-3400 工作站晶片組；不同 Xeon W SKU 的記憶體通道、ECC 與 PCIe 資源不同，須按處理器型號判讀。"] = "Xeon W-2400/W-3400 workstation chipset. Memory channels, ECC, and PCIe resources differ by Xeon W SKU and must be interpreted by processor model.",
        ["Threadripper PRO 工作站平台；處理器 SKU 決定記憶體與 PCIe 上限，實際插槽配置受主機板限制。"] = "Threadripper PRO workstation platform. The processor SKU determines memory and PCIe limits; the motherboard limits the actual slot configuration.",
        ["EPYC SP5 平台；I/O 與記憶體控制器整合於處理器，通道、插槽與可用功能依 EPYC SKU、主機板及 BIOS。"] = "EPYC SP5 platform. I/O and memory controllers are integrated into the processor; channels, sockets, and available features depend on the EPYC SKU, motherboard, and BIOS.",
        ["EPYC SP3 平台；I/O 與記憶體控制器整合於處理器，通道、插槽與可用功能依 EPYC SKU、主機板及 BIOS。"] = "EPYC SP3 platform. I/O and memory controllers are integrated into the processor; channels, sockets, and available features depend on the EPYC SKU, motherboard, and BIOS.",
        ["AMD EPYC SoC 平台"] = "AMD EPYC SoC platform",
        ["EPYC 將記憶體控制器與主要 I/O 整合於處理器；插槽、通道、NUMA 與 I/O 能力須依 EPYC SKU、主機板及 BIOS 核對，不能當作單一晶片組規格。"] = "EPYC integrates memory controllers and primary I/O into the processor. Sockets, channels, NUMA, and I/O capabilities must be checked against the EPYC SKU, motherboard, and BIOS; they cannot be treated as one chipset specification.",
        ["LGA1700 旗艦晶片組，支援第 12/13/14 代 Core 之 CPU 與記憶體超頻。雙通道 DDR5 / DDR4、CPU PCIe 5.0、PCH 最多 20 條 PCIe 4.0、USB 3.2 Gen2x2（20Gb/s）。"] = "LGA1700 flagship chipset supporting CPU and memory overclocking for 12th/13th/14th Gen Core. Dual-channel DDR5/DDR4, CPU PCIe 5.0, up to 20 PCH PCIe 4.0 lanes, and USB 3.2 Gen2x2 (20 Gb/s).",
        ["LGA1700 超頻晶片組，支援第 12/13 代 Core。雙通道 DDR5 / DDR4、PCIe 5.0、DMI 4.0 x8、USB 3.2 Gen2x2。"] = "LGA1700 overclocking chipset supporting 12th/13th Gen Core. Dual-channel DDR5/DDR4, PCIe 5.0, DMI 4.0 x8, and USB 3.2 Gen2x2.",
        ["LGA1700 主流晶片組，支援記憶體超頻（CPU 不可超頻）。雙通道 DDR5 / DDR4、PCIe 5.0（CPU）、USB 3.2 Gen2x2。"] = "LGA1700 mainstream chipset supporting memory overclocking (CPU overclocking is unavailable). Dual-channel DDR5/DDR4, PCIe 5.0 (CPU), and USB 3.2 Gen2x2.",
        ["LGA1700 中階晶片組，較 B760 提供更多 PCIe / USB 通道，支援記憶體超頻。"] = "LGA1700 midrange chipset offering more PCIe/USB lanes than B760 and supporting memory overclocking.",
        ["LGA1700 主流晶片組，支援記憶體超頻。雙通道 DDR5 / DDR4、PCIe 4.0。"] = "LGA1700 mainstream chipset supporting memory overclocking. Dual-channel DDR5/DDR4 and PCIe 4.0.",
        ["LGA1700 入門晶片組，功能精簡，不支援超頻，僅 DDR5 / DDR4 單一時脈。"] = "LGA1700 entry-level chipset with reduced features and no overclocking support; only one DDR5/DDR4 clock setting.",
        ["LGA1200 超頻晶片組，支援第 10/11 代 Core。雙通道 DDR4、第 11 代提供 PCIe 4.0、USB 3.2 Gen2x2。"] = "LGA1200 overclocking chipset supporting 10th/11th Gen Core. Dual-channel DDR4, PCIe 4.0 with 11th Gen processors, and USB 3.2 Gen2x2.",
        ["LGA1200 主流晶片組，開放記憶體超頻。雙通道 DDR4、PCIe 4.0（11 代）。"] = "LGA1200 mainstream chipset supporting memory overclocking. Dual-channel DDR4 and PCIe 4.0 (11th Gen).",
        ["LGA1200 超頻晶片組，支援第 10 代 Core（相容 11 代）。雙通道 DDR4。"] = "LGA1200 overclocking chipset supporting 10th Gen Core (compatible with 11th Gen). Dual-channel DDR4.",
        ["AM5 旗艦晶片組（雙 PCH），全面 PCIe 5.0（顯示卡 + 儲存）。雙通道 DDR5、支援 CPU / 記憶體超頻與 EXPO。"] = "AM5 flagship chipset (dual PCH), with PCIe 5.0 for both graphics and storage. Dual-channel DDR5, CPU/memory overclocking, and EXPO support.",
        ["AM5 高階晶片組（雙 PCH），PCIe 5.0 儲存、顯示卡多為 5.0。雙通道 DDR5、支援超頻與 EXPO。"] = "AM5 high-end chipset (dual PCH), with PCIe 5.0 storage and graphics usually at PCIe 5.0. Dual-channel DDR5, overclocking, and EXPO support.",
        ["AM5 中高階晶片組，顯示卡與儲存皆 PCIe 5.0。雙通道 DDR5、支援超頻與 EXPO。"] = "AM5 upper-midrange chipset with PCIe 5.0 for both graphics and storage. Dual-channel DDR5, overclocking, and EXPO support.",
        ["AM5 主流晶片組，PCIe 5.0 儲存。雙通道 DDR5、支援超頻與 EXPO。"] = "AM5 mainstream chipset with PCIe 5.0 storage. Dual-channel DDR5, overclocking, and EXPO support.",
        ["AM4 旗艦晶片組，首發 PCIe 4.0（顯示卡 + 儲存）。雙通道 DDR4、支援超頻，PCH 常需主動散熱。"] = "AM4 flagship chipset that introduced PCIe 4.0 for graphics and storage. Dual-channel DDR4 and overclocking support; the PCH often requires active cooling.",
        ["AM4 主流晶片組，顯示卡 / 主 M.2 為 PCIe 4.0。雙通道 DDR4、支援 CPU 超頻。"] = "AM4 mainstream chipset with PCIe 4.0 for graphics and the primary M.2 slot. Dual-channel DDR4 and CPU overclocking support.",
        ["AM4 入門晶片組，PCIe 3.0，支援記憶體超頻但不支援 CPU 超頻。"] = "AM4 entry-level chipset with PCIe 3.0 and memory overclocking support, but no CPU overclocking support.",
        ["AM4 上一代高階晶片組，PCIe 3.0，支援超頻與 StoreMI。"] = "Previous-generation AM4 high-end chipset with PCIe 3.0, overclocking, and StoreMI support.",
        ["AM4 主流晶片組，PCIe 3.0，支援 CPU 超頻，相容性廣。"] = "AM4 mainstream chipset with PCIe 3.0, CPU overclocking support, and broad compatibility.",
        ["Threadripper（sTRX4）HEDT 平台，四通道 DDR4、大量 PCIe 4.0 通道，支援超頻。"] = "Threadripper (sTRX4) HEDT platform with quad-channel DDR4, many PCIe 4.0 lanes, and overclocking support.",
        ["{0} MHz（額定 {1}）"] = "{0} MHz (rated {1})",
