        ["{0}，{1} 插槽／周期"] = "{0}, {1} slots/cycle",
        ["{0} 這一代 Intel 已改由 PERF_METRICS（MSR 0x329）搭配 TOPDOWN.SLOTS 固定計數器直接提供 Level 1，舊的四事件配方在此架構上對不上，本頁不出數字——寧可空著，也不給一組看起來合理但是錯的比例。"] = "This Intel generation ({0}) uses PERF_METRICS (MSR 0x329) with the TOPDOWN.SLOTS fixed counter to provide Level 1 directly. The old four-event formula does not fit this architecture, so this page reports no figures rather than plausible but incorrect ratios.",
        ["{0} 屬 Atom 系，用的是 TOPDOWN_FE_BOUND／BE_BOUND／RETIRING／BAD_SPECULATION 這一組專屬事件，與大核編碼完全不同，套用大核事件只會得到亂數，故不出數字。"] = "{0} belongs to the Atom family and uses the dedicated TOPDOWN_FE_BOUND/BE_BOUND/RETIRING/BAD_SPECULATION events. Their encodings differ completely from performance-core encodings; using performance-core events would produce meaningless results, so no figures are reported.",
